        if (!empty($bill_id) && is_numeric($bill_id)) {
            // Get customer_name from bills, and consignee from jobs
            $stmtFix = $pdo->prepare("SELECT b.customer_name, j.consignee 
                                      FROM bills b 
                                      LEFT JOIN jobs j ON b.job_id = j.id 
                                      WHERE b.id = ?");
            $stmtFix->execute([$bill_id]);
            $fixData = $stmtFix->fetch(PDO::FETCH_ASSOC);
            if ($fixData) {
                if (empty($clearing_agent) || $clearing_agent == 'N/A') {
                    $clearing_agent = $fixData['customer_name'] ?? '';
                }
                if (empty($consignee) || $consignee == 'N/A') {
