    return $full_path;
}

function saveInvoiceHTMLDirect($bill, $items, $year, $consignee, $clearing_agent, $job_details) {
    global $pdo;
    
    // Get bill_id
    $bill_id = $bill['id'] ?? $bill['bill_id'] ?? null;
    
    if (empty($bill_id) && !empty($bill['bill_number'])) {
        $stmtFind = $pdo->prepare("SELECT id FROM bills WHERE bill_number = ? LIMIT 1");
        $stmtFind->execute([$bill['bill_number']]);
        $bill_id = $stmtFind->fetchColumn();
    }
    
    if (empty($bill_id)) {
        $bill_id = time();
    }
    
    // ========== FIX: Get consignee and customer_name from database if empty ==========
    if (empty($consignee) || $consignee == 'N/A') {
        $consignee = $bill['consignee'] ?? '';
    }
    if (empty($clearing_agent) || $clearing_agent == 'N/A') {
        $clearing_agent = $bill['customer_name'] ?? '';
    }
    
    // Fetch IGM, Index, Loading Date + consignee/customer
    if (!empty($bill_id) && is_numeric($bill_id)) {
        $stmtBill = $pdo->prepare("SELECT igm_number, index_number, loading_date, consignee, customer_name FROM bills WHERE id = ?");
        $stmtBill->execute([$bill_id]);
        $billData = $stmtBill->fetch(PDO::FETCH_ASSOC);
        if ($billData) {
            $bill['igm_number'] = $billData['igm_number'] ?? '';
            $bill['index_number'] = $billData['index_number'] ?? '';
            $bill['loading_date'] = $billData['loading_date'] ?? '';
            if (empty($consignee)) $consignee = $billData['consignee'] ?? '';
            if (empty($clearing_agent)) $clearing_agent = $billData['customer_name'] ?? '';
        }
    }
    // ========== END FIX ==========
    
    // Fetch job_date if not present
    if (empty($bill['job_date']) && !empty($bill['job_id'])) {
        $stmtJob = $pdo->prepare("SELECT job_date FROM jobs WHERE id = ?");
        $stmtJob->execute([$bill['job_id']]);
        $bill['job_date'] = $stmtJob->fetchColumn();
    }
    
    // --- fetch job number ---
    $job_number = null;
    if (!empty($bill['job_id'])) {
        $stmtJobNo = $pdo->prepare("SELECT job_number FROM jobs WHERE id = ?");
        $stmtJobNo->execute([$bill['job_id']]);
        $job_number = $stmtJobNo->fetchColumn();
        if (empty($job_number)) {
            $job_number = $bill['job_id'];
        }
    } else {
        $job_number = 'no_job';
    }
    
    // --- Get folder path ---
    $folder_path = createInvoiceFolder($year, $consignee, $clearing_agent, $job_number);
    
    // ========== UNIQUE FILENAME WITH BILL ID ==========
    $bill_type = $bill['bill_type'] ?? '';
    $bill_type_lower = strtolower(trim($bill_type));
    
    $prefix = '';
    if ($bill_type_lower == 'forwarding' || strpos($bill_type_lower, 'forwarding') !== false) {
        $prefix = 'Forwarding-';
    } elseif ($bill_type_lower == 'detention' || strpos($bill_type_lower, 'detention') !== false) {
        $prefix = 'Detention-';
    }
    
    $bill_number = $bill['bill_number'] ?? 'bill';
    $filename = $prefix . $bill_number . '-' . $bill_id . '.pdf';
    // ========== END FIX ==========
    
    $full_path = $folder_path . $filename;
    
    // Free Time Remaining
    $freeTimeRemaining = '';
    $vesselArrivalDate = $bill['vessel_arrival_date'] ?? $job_details['vessel_arrival_date'] ?? '';
    $freeTimeDays = $bill['free_time'] ?? $job_details['free_time'] ?? '';
    
    if (!empty($freeTimeDays) && !empty($vesselArrivalDate)) {
        $freeTimeDays = intval($freeTimeDays);
        $vesselArrival = new DateTime($vesselArrivalDate);
        $freeTimeEnd = clone $vesselArrival;
        $freeTimeEnd->modify("+{$freeTimeDays} days");
        $today = new DateTime();
        $remaining = $today->diff($freeTimeEnd);
        $remainingDays = $remaining->days;
        
        if ($today > $freeTimeEnd) {
            $freeTimeRemaining = $remainingDays . " day(s) ago";
        } else {
            $freeTimeRemaining = $remainingDays . " day(s) remaining";
