// =============================================
// KARACHI CLEARANCE FUNCTIONS
// =============================================

function generateKarachiClearanceNumber($pdo) {
    // METHOD 1: Try to get max from proper format "XXX-Khi-Clr"
    $stmt = $pdo->prepare("SELECT karachi_clearance_number FROM karachi_clearance WHERE karachi_clearance_number REGEXP '^[0-9]+-Khi-Clr$' ORDER BY LENGTH(karachi_clearance_number) DESC, karachi_clearance_number DESC LIMIT 1");
    $stmt->execute();
    $last = $stmt->fetchColumn();
    
    $max_num = 0;
    
    if ($last && preg_match('/^(\d+)-Khi-Clr$/', $last, $matches)) {
        $max_num = intval($matches[1]);
    } else {
        // METHOD 2: Try to extract number from any format (like "717", "717-Khi", "717-khi-clr")
        $stmt2 = $pdo->prepare("SELECT karachi_clearance_number FROM karachi_clearance WHERE karachi_clearance_number REGEXP '[0-9]+' ORDER BY id DESC LIMIT 100");
        $stmt2->execute();
        $all_records = $stmt2->fetchAll(PDO::FETCH_COLUMN);
        
        foreach ($all_records as $record) {
            if (preg_match('/(\d+)/', $record, $num_matches)) {
                $num = intval($num_matches[1]);
                if ($num > $max_num) {
                    $max_num = $num;
                }
            }
        }
        
        // METHOD 3: If still no data, check if any job number exists in jobs table
        if ($max_num == 0) {
            $stmt3 = $pdo->prepare("SELECT MAX(CAST(job_number AS UNSIGNED)) FROM jobs WHERE job_number REGEXP '^[0-9]+$'");
            $stmt3->execute();
            $job_max = $stmt3->fetchColumn();
            if ($job_max && $job_max > $max_num) {
                $max_num = $job_max;
            }
        }
    }
    
    // If still no number found, start from 1
    if ($max_num == 0) {
        $max_num = 0;
    }
    
    $next_num = $max_num + 1;
    
    // Format with leading zeros (01, 02, 03, ..., 717, 718)
    return str_pad($next_num, 2, '0', STR_PAD_LEFT) . "/KHI/CLR";
}

function getKarachiClearance($pdo, $search = '', $start_date = '', $end_date = '') {
    $userId = getUserId();
    $isAdmin = isAdmin();
    
    $sql = "SELECT * FROM karachi_clearance WHERE 1=1";
    $params = [];
    
    // Apply user permission filter
    if (!$isAdmin) {
        $sql .= " AND (created_by = ? OR id IN (SELECT record_id FROM user_karachi_clearance_permissions WHERE user_id = ?))";
        $params[] = $userId;
        $params[] = $userId;
    }
    
    if (!empty($search)) {
        $sql .= " AND (karachi_clearance_number LIKE ? OR shipper LIKE ? OR on_account LIKE ? OR clearing_agent LIKE ? OR importer_name LIKE ? OR bl_no LIKE ? OR container_no LIKE ? OR vessel_name LIKE ?)";
        $search_param = "%$search%";
        $params = array_merge($params, [$search_param, $search_param, $search_param, $search_param, $search_param, $search_param, $search_param, $search_param]);
    }
    
    if (!empty($start_date) && !empty($end_date)) {
        $sql .= " AND date BETWEEN ? AND ?";
        $params[] = $start_date;
        $params[] = $end_date;
    }
    
    $sql .= " ORDER BY id DESC";
    
    $stmt = $pdo->prepare($sql);
    $stmt->execute($params);
    return $stmt->fetchAll();
}



