function getLoadingFilesGroupedByDate($pdo, $search = '', $start_date = '', $end_date = '') {
    $userId = getUserId();
    $isAdmin = isAdmin();
    
    $sql = "SELECT lf.*, j.job_number as job_number_ref, j.consignee, j.customer_name,
            DATE(lf.loading_date) as record_date
            FROM loading_files lf 
            LEFT JOIN jobs j ON lf.job_id = j.id 
            WHERE 1=1";
    $params = [];
    
    // Apply user permission filter (NON-ADMIN users only see their own jobs + granted jobs)
    if (!$isAdmin) {
        $sql .= " AND (j.created_by = ? OR EXISTS (SELECT 1 FROM user_job_permissions ujp WHERE ujp.job_id = j.id AND ujp.user_id = ?))";
        $params[] = $userId;
        $params[] = $userId;
    }
    
    if (!empty($search)) {
        $sql .= " AND (j.job_number LIKE ? OR lf.clearing_agent LIKE ? OR lf.importer LIKE ? OR lf.container_no LIKE ? OR lf.vehicles_no LIKE ?)";
        $search_param = "%$search%";
        $params = array_merge($params, [$search_param, $search_param, $search_param, $search_param, $search_param]);
    }
    
    // Date range filter
    if (!empty($start_date) && !empty($end_date)) {
        $sql .= " AND (lf.loading_date BETWEEN ? AND ? OR DATE(lf.created_at) BETWEEN ? AND ?)";
        $params[] = $start_date;
        $params[] = $end_date;
        $params[] = $start_date;
        $params[] = $end_date;
    } elseif (!empty($start_date)) {
        $sql .= " AND (lf.loading_date >= ? OR DATE(lf.created_at) >= ?)";
        $params[] = $start_date;
        $params[] = $start_date;
    } elseif (!empty($end_date)) {
        $sql .= " AND (lf.loading_date <= ? OR DATE(lf.created_at) <= ?)";
        $params[] = $end_date;
        $params[] = $end_date;
    }
    
    $sql .= " ORDER BY lf.loading_date DESC, lf.id DESC";
    
    $stmt = $pdo->prepare($sql);
    $stmt->execute($params);
    $records = $stmt->fetchAll();
    
    // Group records by date
    $grouped = [];
    foreach ($records as $record) {
        $date = $record['record_date'];
        if (!$date) $date = 'No Date';
        if (!isset($grouped[$date])) {
            $grouped[$date] = [];
        }
        $grouped[$date][] = $record;
    }
    
    return $grouped;
}

function getLoadingFiles($pdo, $search = '', $start_date = '', $end_date = '', $selected_date = '') {
    $sql = "SELECT lf.*, j.job_number as job_number_ref, j.consignee, j.customer_name,
            DATE(lf.loading_date) as record_date,
            DATE(lf.created_at) as file_date
            FROM loading_files lf 
            LEFT JOIN jobs j ON lf.job_id = j.id 
            WHERE 1=1";
    $params = [];
    
    if (!empty($search)) {
        $sql .= " AND (j.job_number LIKE ? OR lf.clearing_agent LIKE ? OR lf.importer LIKE ? OR lf.container_no LIKE ? OR lf.vehicles_no LIKE ?)";
        $search_param = "%$search%";
        $params = [$search_param, $search_param, $search_param, $search_param, $search_param];
    }
    
    // Agar specific date select ki hai toh sirf us date ke records dikhayein
    if (!empty($selected_date)) {
        $sql .= " AND DATE(lf.loading_date) = ?";
        $params[] = $selected_date;
    }
    
    // Date range filter
    if (!empty($start_date) && !empty($end_date)) {
        $sql .= " AND (lf.loading_date BETWEEN ? AND ? OR DATE(lf.created_at) BETWEEN ? AND ?)";
        $params[] = $start_date;
        $params[] = $end_date;
        $params[] = $start_date;
        $params[] = $end_date;
    } elseif (!empty($start_date)) {
        $sql .= " AND (lf.loading_date >= ? OR DATE(lf.created_at) >= ?)";
        $params[] = $start_date;
        $params[] = $start_date;
    } elseif (!empty($end_date)) {
        $sql .= " AND (lf.loading_date <= ? OR DATE(lf.created_at) <= ?)";
        $params[] = $end_date;
        $params[] = $end_date;
    }
    
    $sql .= " ORDER BY lf.loading_date DESC, lf.id DESC";
    
    $stmt = $pdo->prepare($sql);
    $stmt->execute($params);
    return $stmt->fetchAll();
}

function getDistinctLoadingDates($pdo) {
    $stmt = $pdo->query("SELECT DISTINCT DATE(loading_date) as record_date 
                         FROM loading_files 
                         WHERE loading_date IS NOT NULL 
                         ORDER BY record_date DESC");
    return $stmt->fetchAll(PDO::FETCH_COLUMN);
}

function getLoadingFileById($pdo, $id) {
    $stmt = $pdo->prepare("SELECT lf.*, j.job_number as job_number_ref, j.consignee, j.customer_name 
                           FROM loading_files lf 
                           LEFT JOIN jobs j ON lf.job_id = j.id 
                           WHERE lf.id = ?");
    $stmt->execute([$id]);
    return $stmt->fetch(PDO::FETCH_ASSOC);
}

function getLoadingFileByJobId($pdo, $job_id) {
    $stmt = $pdo->prepare("SELECT * FROM loading_files WHERE job_id = ?");
    $stmt->execute([$job_id]);
    return $stmt->fetch(PDO::FETCH_ASSOC);
}

function saveLoadingFile($pdo, $data, $user_id) {
    // Auto-set table_date based on loading_date or current date
    $table_date = !empty($data['loading_date']) ? $data['loading_date'] : date('Y-m-d');
    
    if (empty($data['id'])) {
        // Insert new record - MANUAL created_at use karein
        $stmt = $pdo->prepare("INSERT INTO loading_files (
            job_id, clearing_agent, bonded_carrier, importer, dry_port, 
            container_size, container_no, shipping_line, free_days, 
            vessel_arrival, loading_date, created_at, lahore_arrival, status, 
            vehicles_no, trucker_cell, soc, created_by, table_date
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
        
        // IMPORTANT: User provided created_at use karein, agar nahi hai toh current date
        $created_at = !empty($data['created_at']) ? $data['created_at'] : date('Y-m-d H:i:s');
        
        $stmt->execute([
            $data['job_id'],
            $data['clearing_agent'],
            $data['bonded_carrier'],
            $data['importer'],
            $data['dry_port'],
            $data['container_size'],
            $data['container_no'],
            $data['shipping_line'],
            $data['free_days'],
            !empty($data['vessel_arrival']) ? $data['vessel_arrival'] : null,
            !empty($data['loading_date']) ? $data['loading_date'] : null,
            $created_at,
            !empty($data['lahore_arrival']) ? $data['lahore_arrival'] : null,
            $data['status'],
            $data['vehicles_no'],
            $data['trucker_cell'],
            $data['soc'],
            $user_id,
            $table_date
        ]);
        return $pdo->lastInsertId();
    } else {
        // Update existing record - created_at update nahi karna
        $stmt = $pdo->prepare("UPDATE loading_files SET 
            clearing_agent = ?, bonded_carrier = ?, importer = ?, dry_port = ?, 
            container_size = ?, container_no = ?, shipping_line = ?, free_days = ?, 
            vessel_arrival = ?, loading_date = ?, lahore_arrival = ?, status = ?, 
            vehicles_no = ?, trucker_cell = ?, soc = ?, table_date = ?
            WHERE id = ?");
        
        $stmt->execute([
            $data['clearing_agent'],
            $data['bonded_carrier'],
            $data['importer'],
            $data['dry_port'],
            $data['container_size'],
            $data['container_no'],
            $data['shipping_line'],
            $data['free_days'],
            !empty($data['vessel_arrival']) ? $data['vessel_arrival'] : null,
            !empty($data['loading_date']) ? $data['loading_date'] : null,
            !empty($data['lahore_arrival']) ? $data['lahore_arrival'] : null,
            $data['status'],
            $data['vehicles_no'],
            $data['trucker_cell'],
            $data['soc'],
            $table_date,
            $data['id']
        ]);
        return $data['id'];
    }
}

function deleteLoadingFile($pdo, $id) {
    $stmt = $pdo->prepare("DELETE FROM loading_files WHERE id = ?");
    return $stmt->execute([$id]);
}

