// ========== Updated getMasters (with description from masters table) 
// ========== Updated getMasters (with description from masters table) 
function getMasters($pdo, $type, $limit = null, $offset = null) {
    $columnMap = [
        'bonded_carrier'        => 'bonded_carrier',
        'do_collected_date'     => 'do_collected_date',
        'customer_name'         => 'customer_name',
        'consignee'             => 'consignee',
        'container_size'        => 'container_size',
        'dry_port'              => 'dry_port',
        'vessel_name'           => 'vessel_name',
        'shipping_line'         => 'shipping_line',
        'freight_forwarder_name'=> 'freight_forwarder_name',
        'depositor'             => 'depositor',
        'description'           => 'description'
    ];

    if (!isset($columnMap[$type])) return [];
    $col = $columnMap[$type];

    // 1. Jobs table se distinct values
    $sql = "SELECT DISTINCT `$col` as name FROM jobs WHERE `$col` != '' AND `$col` IS NOT NULL ORDER BY `$col`";
    if ($limit !== null && $offset !== null) {
        $sql .= " LIMIT $limit OFFSET $offset";
    }
    $stmt = $pdo->prepare($sql);
    $stmt->execute();
    $jobValues = $stmt->fetchAll(PDO::FETCH_COLUMN);

    // 2. Linked jobs count + masters info (NO auto‑insert)
    $linkStmt = $pdo->prepare("SELECT COUNT(*) FROM jobs WHERE `$col` = ?");
    $linkedJobsStmt = $pdo->prepare("SELECT GROUP_CONCAT(job_number ORDER BY job_number SEPARATOR ', ') FROM jobs WHERE `$col` = ?");
    $mastersStmt = $pdo->prepare("SELECT id, code, sort_order, is_active, ntn, st_no FROM masters WHERE type = ? AND name = ?");

    $masters = [];
    $index = 0; // ✅ Counter for unique ID generation
    foreach ($jobValues as $val) {
        $linkStmt->execute([$val]);
        $jobCount = (int)$linkStmt->fetchColumn();

        // ✅ Get linked jobs list
        $linkedJobsStmt->execute([$val]);
        $linkedJobs = $linkedJobsStmt->fetchColumn() ?: '';

        $mastersStmt->execute([$type, $val]);
        $masterRow = $mastersStmt->fetch();

        // ✅ FIXED: Ensure every row has a unique ID
        $rowId = $masterRow ? $masterRow['id'] : ('job_' . $type . '_' . $index);
        
        $masters[] = [
            'id'          => $rowId, // ✅ Always has a value now
            'code'        => $masterRow['code'] ?? $val, // ✅ Use name as code fallback
            'name'        => $val,
            'sort_order'  => $masterRow['sort_order'] ?? 0,
            'is_active'   => $masterRow['is_active'] ?? 1,
            'ntn'         => $masterRow['ntn'] ?? '',
            'st_no'       => $masterRow['st_no'] ?? '',
            'job_count'   => $jobCount,
            'linked_jobs' => $linkedJobs, // ✅ Added linked jobs
            'type'        => $type
        ];
        $index++;
    }
    return $masters;
}

// ===================== getMastersCount() =====================
function getMastersCount($pdo, $type) {
    $columnMap = [
        'consignee'             => 'consignee',
        'bonded_carrier'        => 'bonded_carrier',
        'do_collected_date'     => 'do_collected_date',  // ✅ Fixed
        'customer_name'         => 'customer_name',
        'container_size'        => 'container_size',
        'dry_port'              => 'dry_port',
        'vessel_name'           => 'vessel_name',
        'shipping_line'         => 'shipping_line',
        'freight_forwarder_name'=> 'freight_forwarder_name',
        'depositor'             => 'depositor',
        'description'           => 'description'  // ✅ Added description
    ];

    if (!isset($columnMap[$type])) return 0;
    $col = $columnMap[$type];

    $stmt = $pdo->prepare("SELECT COUNT(DISTINCT `$col`) as cnt FROM jobs WHERE `$col` != '' AND `$col` IS NOT NULL");
    $stmt->execute();
    return (int)$stmt->fetch()['cnt'];
}


// ===================== Helper to fetch a single master for AJAX =====================
function getMasterById($pdo, $id) {
    $stmt = $pdo->prepare("SELECT * FROM masters WHERE id = ?");
    $stmt->execute([$id]);
    $row = $stmt->fetch(PDO::FETCH_ASSOC);
    if (!$row) return null;

    $type = $row['type'];
    $name = $row['name'];

    // ✅ FIX: Updated column map with do_collected_date
    $columnMap = [
        'bonded_carrier'        => 'bonded_carrier',
        'do_collected_date'     => 'do_collected_date',  // ✅ Changed from 'do' to 'do_collected_date'
        'customer_name'         => 'customer_name',
        'consignee'             => 'consignee',
        'container_size'        => 'container_size',
        'dry_port'              => 'dry_port',
        'vessel_name'           => 'vessel_name',
        'shipping_line'         => 'shipping_line',
        'freight_forwarder_name'=> 'freight_forwarder_name',
        'depositor'             => 'depositor',
        'description'           => 'description'
    ];

    $col = isset($columnMap[$type]) ? $columnMap[$type] : null;
    $job_count = 0;
    $linked_jobs = '';

    if ($col) {
        $ljStmt = $pdo->prepare("SELECT GROUP_CONCAT(job_number ORDER BY job_number SEPARATOR ', ') as jobs, COUNT(*) as cnt FROM jobs WHERE `$col` = ?");
        $ljStmt->execute([$name]);
        $lj = $ljStmt->fetch();
        $job_count = (int)($lj['cnt'] ?? 0);
        $linked_jobs = $lj['jobs'] ?? '';
    }

    return [
        'id'          => $row['id'],
        'code'        => $row['code'] ?? '',
        'name'        => $row['name'],
        'ntn'         => $row['ntn'] ?? '',
        'st_no'       => $row['st_no'] ?? '',
        'is_active'   => $row['is_active'] ?? 1,
        'job_count'   => $job_count,
        'linked_jobs' => $linked_jobs
    ];
}



function generateJobNumber($pdo) {
    $currentYear = date('Y'); // Get current year (2026)
    
    // Get all job numbers for current year, sorted numerically
    $stmt = $pdo->prepare("SELECT CAST(job_number AS UNSIGNED) as job_num 
                           FROM jobs 
                           WHERE job_number REGEXP '^[0-9]+$' 
                           AND YEAR(job_date) = ? 
                           ORDER BY CAST(job_number AS UNSIGNED) ASC");
    $stmt->execute([$currentYear]);
    $existingJobs = $stmt->fetchAll(PDO::FETCH_COLUMN);
    
    if (empty($existingJobs)) {
        // If no jobs exist for this year, start with 001
        return '001';
    }
    
    // Find the first missing number in the sequence
    $expectedNumber = 1;
    foreach ($existingJobs as $jobNumber) {
        $currentNumber = (int)$jobNumber;
        
        if ($currentNumber > $expectedNumber) {
            // Found a gap, use the missing number
            return str_pad($expectedNumber, 3, '0', STR_PAD_LEFT);
        }
        $expectedNumber = $currentNumber + 1;
    }
    
    // No gaps found, use the next sequential number
    $lastNumber = (int)end($existingJobs);
    $nextNumber = $lastNumber + 1;
    
    return str_pad($nextNumber, 3, '0', STR_PAD_LEFT);
}

function checkExistingBills($pdo, $job_id) {
    $stmt = $pdo->prepare("SELECT COUNT(*) FROM bills WHERE job_id = ?");
    $stmt->execute([$job_id]);
    return $stmt->fetchColumn() > 0;
}

function getExistingBillsList($pdo, $job_id) {
    $stmt = $pdo->prepare("SELECT bill_number, bill_type, total_amount, created_at FROM bills WHERE job_id = ? ORDER BY created_at DESC");
    $stmt->execute([$job_id]);
    return $stmt->fetchAll();
}

function getMonthlyRevenue($pdo) {
    $stmt = $pdo->prepare("SELECT DATE_FORMAT(created_at, '%M') as month, SUM(total_amount) as total FROM bills WHERE YEAR(created_at) = YEAR(CURDATE()) GROUP BY MONTH(created_at) ORDER BY MONTH(created_at)");
    $stmt->execute();
    return $stmt->fetchAll();
}

function getRecentBills($pdo, $limit = 5) {
    $userId = getUserId();
    if (isAdmin()) {
        $stmt = $pdo->prepare("SELECT b.*, j.consignee, j.job_number FROM bills b LEFT JOIN jobs j ON b.job_id = j.id ORDER BY b.created_at DESC LIMIT ?");
        $stmt->execute([$limit]);
    } else {
        $stmt = $pdo->prepare("SELECT b.*, j.consignee, j.job_number FROM bills b LEFT JOIN jobs j ON b.job_id = j.id WHERE b.created_by = ? ORDER BY b.created_at DESC LIMIT ?");
        $stmt->execute([$userId, $limit]);
    }
    return $stmt->fetchAll();
}

