function exportJobsToExcel($jobs, $start_date, $end_date) {
    global $exports_dir, $pdo;
    
    $timestamp = date('Y-m-d_H-i-s');
    $filename = "jobs_export_{$start_date}_to_{$end_date}_{$timestamp}.xls";
    $filepath = $exports_dir . $filename;
    
    $html = '<html><head><meta charset="UTF-8"><title>Jobs Export</title></head><body>';
    $html .= '<h2>Qadria International - Jobs Report</h2>';
    $html .= '<p>Date Range: ' . $start_date . ' to ' . $end_date . '</p>';
    $html .= '<p>Generated on: ' . date('Y-m-d H:i:s') . '</p>';
    $html .= '<table border="1" cellpadding="5" cellspacing="0">';
    $html .= '<thead><tr>
        <th>Job #</th><th>Original Documents Received</th><th>Job Creation Dt</th><th>Bonded Carrier Name</th>
        <th>D/O Collected on</th><th>Customer Name</th><th>Consignee</th><th>BL #</th>
        <th>Container #</th><th>Container Size</th><th>Vessel Name</th><th>Vessel Arrival Date</th>
        <th>Port of Loading</th><th>Port of Discharge</th><th>KHI Port</th><th>Dry Port</th>
        <th>Shipping Line</th><th>Freight Forwarder Name</th><th>Depositor</th>
        <th>Free Time</th><th>Detention Tariff</th><th>SOC</th><th>Mobile No</th>
        <th>Description</th><th>Status</th><th>Created By</th>
        </tr></thead><tbody>';
    
    foreach($jobs as $job) {
        $creator_name = '';
        if (!empty($job['created_by'])) {
            $stmt = $pdo->prepare("SELECT full_name FROM users WHERE id = ?");
            $stmt->execute([$job['created_by']]);
            $creator = $stmt->fetch();
            $creator_name = $creator['full_name'] ?? '';
        }
        
        $html .= '<tr>
            <td>' . htmlspecialchars($job['job_number'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['original_documents_date'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['job_date'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['bonded_carrier'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['do_collected_date'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['customer_name'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['consignee'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['bl_number'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['container_number'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['container_size'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['vessel_name'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['vessel_arrival_date'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['port_of_loading'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['port_of_discharge'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['khi_port'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['dry_port'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['shipping_line'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['freight_forwarder_name'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['depositor'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['free_time'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['detention_tariff'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['soc'] ?? 'No') . '</td>
            <td>' . htmlspecialchars($job['mobile_no'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['description'] ?? '') . '</td>
            <td>' . htmlspecialchars($job['status'] ?? '') . '</td>
            <td>' . htmlspecialchars($creator_name) . '</td>
        </tr>';
    }
    
