function createZipArchive($files, $zip_name) {
    global $exports_dir;
    
    $zip_path = $exports_dir . $zip_name;
    $zip = new ZipArchive();
    
    if ($zip->open($zip_path, ZipArchive::CREATE | ZipArchive::OVERWRITE) === TRUE) {
        foreach ($files as $file) {
            if (file_exists($file)) {
                $zip->addFile($file, basename($file));
            }
        }
        $zip->close();
        return $zip_path;
    }
    return false;
}

