// system.php mein add karein
elseif($page == 'search-jobs') {
    header('Content-Type: application/json');
    
    $page_num = isset($_GET['page_num']) ? max(1, (int)$_GET['page_num']) : 1;
    $search = $_GET['search'] ?? '';
    $start_date = $_GET['start_date'] ?? '';
    $end_date = $_GET['end_date'] ?? '';
    $year = $_GET['year'] ?? '';
    $column_filters = $_GET['column_filters'] ?? '';
    
    $limit = 20;
    $offset = ($page_num - 1) * $limit;
    
    $isAdmin = isAdmin();
    $currentUserId = getUserId();
    
    // ========== JOIN with users table to get created_by_name ==========
    $sql = "SELECT j.*, u.full_name as created_by_name FROM jobs j LEFT JOIN users u ON j.created_by = u.id WHERE 1=1";
    $count_sql = "SELECT COUNT(*) as total FROM jobs j WHERE 1=1";
    $params = [];
    $where = [];
    
    // ========== PERMISSION FILTER (NON-ADMIN USERS) - FIXED ==========
    if (!$isAdmin) {
        $where[] = "(j.created_by = :current_user_id OR EXISTS (SELECT 1 FROM user_job_permissions ujp WHERE ujp.job_id = j.id AND ujp.user_id = :perm_user_id))";
        $params[':current_user_id'] = $currentUserId;
        $params[':perm_user_id'] = $currentUserId;
    }
    
    // Date filter
    if(!empty($start_date) && !empty($end_date)) {
        $where[] = "j.job_date BETWEEN :start_date AND :end_date";
        $params[':start_date'] = $start_date;
        $params[':end_date'] = $end_date . ' 23:59:59';
    }
    
    // Year filter
    if(!empty($year)) {
        $where[] = "YEAR(j.job_date) = :year";
        $params[':year'] = $year;
    }
    
    // Global search
    if(!empty($search)) {
        $search_cols = ['j.job_number','j.customer_name','j.consignee','j.bl_number','j.container_number','j.container_size','j.vessel_name','j.port_of_loading','j.port_of_discharge','j.khi_port','j.dry_port','j.shipping_line','j.freight_forwarder_name','j.depositor','j.free_time','j.detention_tariff','j.bonded_carrier','j.do_collected_date','j.mobile_no','j.description','j.soc','j.status','j.mbl_number','u.full_name'];
        $search_where = [];
        foreach($search_cols as $col) {
            $search_where[] = "$col LIKE :search";
        }
        $where[] = "(" . implode(" OR ", $search_where) . ")";
        $params[':search'] = "%$search%";
    }
    
    // Column filters
    if(!empty($column_filters)) {
        $filters = explode('|', $column_filters);
        foreach($filters as $filter) {
            $parts = explode(':', $filter, 2);
            if(count($parts) == 2) {
                $col = $parts[0];
                $val = $parts[1];
                
                if($col == 'created_by_name') {
                    $where[] = "u.full_name LIKE :filter_$col";
                }
                elseif(in_array($col, ['job_date', 'original_documents_date', 'vessel_arrival_date'])) {
                    $where[] = "DATE_FORMAT(j.$col, '%d-%m-%Y') LIKE :filter_$col";
                } else {
                    $where[] = "j.$col LIKE :filter_$col";
                }
                $params[':filter_'.$col] = "%$val%";
            }
        }
    }
    
    if(!empty($where)) {
        $where_clause = " AND " . implode(" AND ", $where);
        $sql .= $where_clause;
        $count_sql .= $where_clause;
    }
    
    // Get total
    $stmt = $pdo->prepare($count_sql);
    $stmt->execute($params);
    $total_records = $stmt->fetch(PDO::FETCH_ASSOC)['total'];
    $total_pages = ceil($total_records / $limit);
    
    // Get data
    $sql .= " ORDER BY j.job_date DESC, j.id DESC LIMIT :limit OFFSET :offset";
    $stmt = $pdo->prepare($sql);
    foreach($params as $key => $value) {
        $stmt->bindValue($key, $value);
    }
    $stmt->bindValue(':limit', $limit, PDO::PARAM_INT);
    $stmt->bindValue(':offset', $offset, PDO::PARAM_INT);
    $stmt->execute();
    $jobs = $stmt->fetchAll(PDO::FETCH_ASSOC);
    
    echo json_encode([
        'success' => true,
        'jobs' => $jobs,
        'current_page' => $page_num,
        'total_pages' => $total_pages,
        'total_records' => $total_records
    ]);
    exit;
}
