    $userId = getUserId();
    
    if (isAdmin()) {
        $stmt = $pdo->prepare("SELECT b.*, j.job_number, j.consignee FROM bills b LEFT JOIN jobs j ON b.job_id = j.id WHERE DATE(b.created_at) BETWEEN ? AND ? ORDER BY b.created_at DESC");
        $stmt->execute([$start_date, $end_date]);
    } else {
        $stmt = $pdo->prepare("SELECT b.*, j.job_number, j.consignee FROM bills b LEFT JOIN jobs j ON b.job_id = j.id WHERE b.created_by = ? AND DATE(b.created_at) BETWEEN ? AND ? ORDER BY b.created_at DESC");
        $stmt->execute([$userId, $start_date, $end_date]);
    }
    $bills = $stmt->fetchAll();
    
    if (count($bills) == 0) {
        $_SESSION['error'] = "No bills found in the selected date range!";
        header("Location: system.php?page=bills");
        exit();
    }
    
    $excel_file = exportBillsToExcel($bills, $start_date, $end_date);
    $pdf_file = exportBillsToPDF($bills, $start_date, $end_date);
    
    $timestamp = date('Y-m-d_H-i-s');
    $zip_name = "bills_export_{$start_date}_to_{$end_date}_{$timestamp}.zip";
    $zip_path = createZipArchive([$excel_file, $pdf_file], $zip_name);
    
    if ($zip_path) {
        header('Content-Type: application/zip');
        header('Content-Disposition: attachment; filename="' . $zip_name . '"');
        header('Content-Length: ' . filesize($zip_path));
        readfile($zip_path);
        unlink($excel_file);
        unlink($pdf_file);
        unlink($zip_path);
    } else {
        $_SESSION['error'] = "Failed to create zip archive!";
        header("Location: system.php?page=bills");
    }
    exit();
}


