// ========== ADMIN CHANGE USER PASSWORD ==========
elseif ($page == 'admin-change-user-password' && isAdmin()) {
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        $userId = intval($_POST['user_id'] ?? 0);
        $newPassword = $_POST['new_password'] ?? '';
        $confirmPassword = $_POST['confirm_password'] ?? '';

        // Basic validations
        if (empty($newPassword) || empty($confirmPassword)) {
            $_SESSION['error'] = "Please fill both password fields.";
        } elseif ($newPassword !== $confirmPassword) {
            $_SESSION['error'] = "Passwords do not match.";
        } elseif (strlen($newPassword) < 6) {
            $_SESSION['error'] = "Password must be at least 6 characters.";
        } else {
            // Check user exists (optional: prevent changing own password here? not needed)
            $stmt = $pdo->prepare("SELECT id FROM users WHERE id = ?");
            $stmt->execute([$userId]);
            $user = $stmt->fetch();

            if (!$user) {
                $_SESSION['error'] = "User not found.";
            } else {
                // Hash the new password
                $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);
                $updateStmt = $pdo->prepare("UPDATE users SET password = ? WHERE id = ?");
                if ($updateStmt->execute([$hashedPassword, $userId])) {
                    $_SESSION['success'] = "Password updated successfully for the user.";
                } else {
                    $_SESSION['error'] = "Failed to update password. Please try again.";
                }
            }
        }
    }
    header("Location: system.php?page=users");
    exit;
}



