// CSV IMPORT HANDLER
// CSV IMPORT HANDLER - COMPLETE FIXED VERSION
elseif ($page == 'import-jobs-csv') {
    error_reporting(0);
    ini_set('display_errors', 0);
    ob_clean();
    ob_start();
    
    header('Content-Type: application/json');
    
    if (!isset($_FILES['csv_file']) || $_FILES['csv_file']['error'] !== UPLOAD_ERR_OK) {
        $errorMsg = 'No file uploaded.';
        if (isset($_FILES['csv_file'])) {
            $uploadErrors = [
                UPLOAD_ERR_INI_SIZE => 'File exceeds upload_max_filesize',
                UPLOAD_ERR_FORM_SIZE => 'File exceeds MAX_FILE_SIZE',
                UPLOAD_ERR_PARTIAL => 'File was only partially uploaded',
                UPLOAD_ERR_NO_FILE => 'No file was uploaded',
                UPLOAD_ERR_NO_TMP_DIR => 'Missing temporary folder',
                UPLOAD_ERR_CANT_WRITE => 'Failed to write file to disk',
                UPLOAD_ERR_EXTENSION => 'A PHP extension stopped the upload'
            ];
            $errorMsg = isset($uploadErrors[$_FILES['csv_file']['error']]) 
                ? $uploadErrors[$_FILES['csv_file']['error']] 
                : 'Upload error code: ' . $_FILES['csv_file']['error'];
        }
        ob_clean();
        echo json_encode(['success' => false, 'message' => $errorMsg]);
        exit;
    }
    
    $file = $_FILES['csv_file'];
    
    $fileType = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
    if ($fileType !== 'csv') {
        ob_clean();
        echo json_encode(['success' => false, 'message' => 'Invalid file type. Please upload a CSV file only.']);
        exit;
    }
    
    $maxSize = 10 * 1024 * 1024;
    if ($file['size'] > $maxSize) {
        ob_clean();
        echo json_encode(['success' => false, 'message' => 'File is too large. Maximum size is 10MB.']);
        exit;
    }
    
    $handle = @fopen($file['tmp_name'], 'r');
    if (!$handle) {
        ob_clean();
        echo json_encode(['success' => false, 'message' => 'Could not read the uploaded file.']);
        exit;
    }
    
    $headers = @fgetcsv($handle, 0, ',', '"', '\\');
    if (!$headers) {
        fclose($handle);
        ob_clean();
        echo json_encode(['success' => false, 'message' => 'CSV file is empty or has no header row.']);
        exit;
    }
    
    $headers = array_map(function($h) {
        return strtolower(trim($h));
    }, $headers);
    
    $columns = [
        'job_number',
        'job_date',
        'original_documents_date',
        'bonded_carrier',
        'do_collected_date',
        'customer_name',
        'consignee',
        'bl_number',
        'container_number',
        'container_size',
        'vessel_name',
        'vessel_arrival_date',
        'description',
        'free_till',
        'port_of_loading',
        'port_of_discharge',
        'dry_port',
        'shipping_line',
        'freight_forwarder_name',
        'depositor',
        'free_time',
        'detention_tariff',
        'soc',
        'mobile_no',
        'mbl_number',
        'status',
        'remarks',
        'created_by'
    ];
    
    $foundColumns = array_intersect($columns, $headers);
    if (count($foundColumns) < 3) {
        fclose($handle);
        ob_clean();
        echo json_encode([
            'success' => false,
            'message' => 'CSV file has insufficient matching columns. Found: ' . implode(', ', $foundColumns) . '. Expected columns: ' . implode(', ', $columns)
        ]);
        exit;
    }
    
    $colIndex = [];
    foreach ($columns as $col) {
        $colIndex[$col] = array_search($col, $headers);
    }
    
    // Get last job number from database
    $lastJobStmt = $pdo->query("SELECT MAX(CAST(job_number AS UNSIGNED)) as max_num FROM jobs WHERE job_number REGEXP '^[0-9]+$'");
    $lastJobResult = $lastJobStmt->fetch(PDO::FETCH_ASSOC);
    $nextJobNumber = ($lastJobResult['max_num'] ?? 0) + 1;
    
    $totalRows = 0;
    $imported = 0;
    $errors = 0;
    $errorDetails = [];
    $rowNumber = 1;
    
    // ✅ GET CURRENT USER FOR created_by
    $currentUser = $_SESSION['username'] ?? $_SESSION['full_name'] ?? 'system';
    
    $pdo->beginTransaction();
    
    try {
        $sql = "INSERT INTO jobs (
            job_number, job_date, original_documents_date, bonded_carrier,
            do_collected_date, customer_name, consignee, bl_number,
            container_number, container_size, vessel_name, vessel_arrival_date,
            description, free_till, port_of_loading, port_of_discharge,
            dry_port, shipping_line, freight_forwarder_name, depositor,
            free_time, detention_tariff, soc, mobile_no, mbl_number, status, remarks,
            created_by, created_at
        ) VALUES (
            :job_number, :job_date, :original_documents_date, :bonded_carrier,
            :do_collected_date, :customer_name, :consignee, :bl_number,
            :container_number, :container_size, :vessel_name, :vessel_arrival_date,
            :description, :free_till, :port_of_loading, :port_of_discharge,
            :dry_port, :shipping_line, :freight_forwarder_name, :depositor,
            :free_time, :detention_tariff, :soc, :mobile_no, :mbl_number, :status, :remarks,
            :created_by, NOW()
        )";
        
        $stmt = $pdo->prepare($sql);
        
        while (($row = @fgetcsv($handle, 0, ',', '"', '\\')) !== false) {
            $totalRows++;
            $rowNumber++;
            
            $hasData = false;
            foreach ($row as $cell) {
                if (trim($cell) !== '') {
                    $hasData = true;
                    break;
                }
            }
            if (!$hasData) {
                continue;
            }
            
            $data = [];
            foreach ($columns as $col) {
                if ($col === 'job_number') {
                    // ✅ CHECK IF job_number is "AUTO" or empty
                    $csvJobNumber = ($colIndex[$col] !== false && isset($row[$colIndex[$col]])) ? trim($row[$colIndex[$col]]) : '';
                    if (empty($csvJobNumber) || strtoupper($csvJobNumber) === 'AUTO') {
                        // Auto-generate job number
                        $data[$col] = (string)$nextJobNumber;
                    } else {
                        // Use the job number from CSV
                        $data[$col] = $csvJobNumber;
                    }
                } elseif ($col === 'created_by') {
                    // ✅ FORCE SET created_by FROM SESSION
                    $data[$col] = $currentUser;
                } else {
                    $data[$col] = ($colIndex[$col] !== false && isset($row[$colIndex[$col]])) ? trim($row[$colIndex[$col]]) : '';
                }
            }
            
            if (empty($data['status'])) {
                $data['status'] = 'active';
            }
            
            if (empty($data['soc'])) {
                $data['soc'] = 'No';
            }
            
            $dateFields = ['job_date', 'vessel_arrival_date', 'original_documents_date'];
            foreach ($dateFields as $field) {
                if (!empty($data[$field])) {
                    $date = date_create($data[$field]);
                    if ($date) {
                        $data[$field] = date_format($date, 'Y-m-d');
                    } else {
                        $data[$field] = null;
                    }
                } else {
                    $data[$field] = null;
                }
            }
            
            if (empty($data['do_collected_date'])) {
                $data['do_collected_date'] = null;
            }
            
            try {
                $stmt->execute([
                    ':job_number' => $data['job_number'],
                    ':job_date' => $data['job_date'],
                    ':original_documents_date' => $data['original_documents_date'],
                    ':bonded_carrier' => $data['bonded_carrier'],
                    ':do_collected_date' => $data['do_collected_date'],
                    ':customer_name' => $data['customer_name'],
                    ':consignee' => $data['consignee'],
                    ':bl_number' => $data['bl_number'],
                    ':container_number' => $data['container_number'],
                    ':container_size' => $data['container_size'],
                    ':vessel_name' => $data['vessel_name'],
                    ':vessel_arrival_date' => $data['vessel_arrival_date'],
                    ':description' => $data['description'],
                    ':free_till' => $data['free_till'],
                    ':port_of_loading' => $data['port_of_loading'],
                    ':port_of_discharge' => $data['port_of_discharge'],
                    ':dry_port' => $data['dry_port'],
                    ':shipping_line' => $data['shipping_line'],
                    ':freight_forwarder_name' => $data['freight_forwarder_name'],
                    ':depositor' => $data['depositor'],
                    ':free_time' => $data['free_time'],
                    ':detention_tariff' => $data['detention_tariff'],
                    ':soc' => $data['soc'],
                    ':mobile_no' => $data['mobile_no'],
                    ':mbl_number' => $data['mbl_number'],
                    ':status' => $data['status'],
                    ':remarks' => $data['remarks'],
                    ':created_by' => $data['created_by']
                ]);
                $imported++;
                $nextJobNumber++;
            } catch (PDOException $e) {
                $errors++;
                $errorDetails[] = "Row $rowNumber: DB Error - " . $e->getMessage();
            }
        }
        
        fclose($handle);
        $pdo->commit();
        
        ob_clean();
        echo json_encode([
            'success' => true,
            'message' => "Successfully imported $imported jobs. Errors: $errors. Created by: $currentUser",
            'total_rows' => $totalRows,
            'imported' => $imported,
            'skipped' => 0,
            'errors' => $errors,
            'error_details' => $errorDetails,
            'starting_job_number' => ($lastJobResult['max_num'] ?? 0) + 1,
            'last_job_number' => $nextJobNumber - 1
        ]);
        
    } catch (Exception $e) {
        $pdo->rollBack();
        if (is_resource($handle)) {
            fclose($handle);
        }
        
        ob_clean();
        echo json_encode([
            'success' => false,
            'message' => 'Database error: ' . $e->getMessage(),
            'error_details' => [$e->getMessage()]
        ]);
    }
    exit;
}

