        $stmt = $pdo->prepare("INSERT INTO karachi_clearance (karachi_clearance_number, date, shipper, on_account, clearing_agent, importer_name, bl_no, container_no, description, vessel_name, eta, soc, created_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
        
        $stmt->execute([
            $clearance_number,
            $_POST['date'] ?? date('Y-m-d'),
            $_POST['shipper'] ?? '',
            $_POST['on_account'] ?? '',
            $_POST['clearing_agent'] ?? '',
            $_POST['importer_name'] ?? '',
            $_POST['bl_no'] ?? '',
            $_POST['container_no'] ?? '',
            $_POST['description'] ?? '',
            $_POST['vessel_name'] ?? '',
            !empty($_POST['eta']) ? $_POST['eta'] : null,
            $_POST['soc'] ?? 'No',
            $userId
        ]);
        
        $_SESSION['success'] = "Karachi Clearance record created successfully! Number: " . $clearance_number;
        header("Location: system.php?page=karachi-clearance&new=1");
        exit();
    } catch(Exception $e) {
        $_SESSION['error'] = "Error: " . $e->getMessage();
        header("Location: system.php?page=karachi-clearance");
        exit();
    }
}

if ($page == 'edit-karachi-clearance' && $_SERVER['REQUEST_METHOD'] == 'POST') {
    try {
        $id = $_POST['id'];
        $userId = getUserId();
        
        // PERMISSION CHECK: Verify user has permission to edit this record
        if (!isAdmin()) {
            $checkStmt = $pdo->prepare("SELECT created_by FROM karachi_clearance WHERE id = ?");
            $checkStmt->execute([$id]);
            $record = $checkStmt->fetch();
            
            if (!$record) {
                $_SESSION['error'] = "Record not found!";
                header("Location: system.php?page=karachi-clearance");
                exit();
            }
            
            if ($record['created_by'] != $userId) {
                $_SESSION['error'] = "You do not have permission to edit this clearance record!";
                header("Location: system.php?page=karachi-clearance");
                exit();
            }
        }
        
        // Get existing record to preserve original values if needed
        $stmt = $pdo->prepare("SELECT * FROM karachi_clearance WHERE id = ?");
        $stmt->execute([$id]);
        $existing = $stmt->fetch();
        
        if (!$existing) {
            $_SESSION['error'] = "Record not found!";
            header("Location: system.php?page=karachi-clearance");
            exit();
        }
        
        // Prepare update statement
        $updateStmt = $pdo->prepare("UPDATE karachi_clearance SET 
            date = ?, 
            shipper = ?, 
            on_account = ?, 
            clearing_agent = ?, 
            importer_name = ?, 
            bl_no = ?, 
            container_no = ?, 
            description = ?, 
            vessel_name = ?, 
            eta = ?, 
            soc = ?, 
            status = ? 
            WHERE id = ?");
        
        $updateStmt->execute([
            !empty($_POST['date']) ? $_POST['date'] : date('Y-m-d'),
            !empty($_POST['shipper']) ? $_POST['shipper'] : '',
            !empty($_POST['on_account']) ? $_POST['on_account'] : '',
            !empty($_POST['clearing_agent']) ? $_POST['clearing_agent'] : '',
            !empty($_POST['importer_name']) ? $_POST['importer_name'] : '',
            !empty($_POST['bl_no']) ? $_POST['bl_no'] : '',
            !empty($_POST['container_no']) ? $_POST['container_no'] : '',
            !empty($_POST['description']) ? $_POST['description'] : '',
            !empty($_POST['vessel_name']) ? $_POST['vessel_name'] : '',
            !empty($_POST['eta']) ? $_POST['eta'] : null,
            isset($_POST['soc']) ? $_POST['soc'] : 'No',
            isset($_POST['status']) ? $_POST['status'] : 'active',
            $id
        ]);
        
        $_SESSION['success'] = "Karachi Clearance record updated successfully!";
        header("Location: system.php?page=karachi-clearance");
        exit();
        
    } catch(Exception $e) {
        error_log("Karachi Clearance Edit Error: " . $e->getMessage());
        $_SESSION['error'] = "Error updating record: " . $e->getMessage();
        header("Location: system.php?page=karachi-clearance");
        exit();
    }
}

if ($page == 'delete-karachi-clearance' && isset($_GET['id'])) {
    try {
        $id = $_GET['id'];
        $userId = getUserId();
        
        // PERMISSION CHECK: User can only delete their own records (or admin)
        if (!isAdmin()) {
            $stmt = $pdo->prepare("SELECT created_by FROM karachi_clearance WHERE id = ?");
            $stmt->execute([$id]);
            $record = $stmt->fetch();
            if (!$record || $record['created_by'] != $userId) {
                $_SESSION['error'] = "You do not have permission to delete this record!";
                header("Location: system.php?page=karachi-clearance");
                exit();
            }
