            $totalJobs = $pdo->query("SELECT COUNT(*) FROM jobs")->fetchColumn();
            $activeJobs = $pdo->query("SELECT COUNT(*) FROM jobs WHERE status = 'active'")->fetchColumn();
            $totalBills = $pdo->query("SELECT COUNT(*) FROM bills")->fetchColumn();
            $totalRevenue = $pdo->query("SELECT SUM(total_amount) FROM bills")->fetchColumn();
            
            // ✅ CHANGED: Recent jobs - ONLY current year
            $recentJobs = $pdo->query("SELECT * FROM jobs WHERE YEAR(job_date) = YEAR(CURDATE()) ORDER BY id DESC LIMIT 5")->fetchAll();
        } else {
            $jobs = getUserVisibleJobs($pdo, $userId);
            $totalJobs = count($jobs);
            $activeJobs = 0;
            foreach ($jobs as $job) {
                if ($job['status'] == 'active') $activeJobs++;
            }
            
            $bills = getUserVisibleBills($pdo, $userId);
            $totalBills = count($bills);
            $totalRevenue = 0;
            foreach ($bills as $bill) {
                $totalRevenue += floatval($bill['total_amount'] ?? 0);
            }
            
            // ✅ CHANGED: Recent jobs - ONLY current year for non-admin users
            $allVisibleJobs = getUserVisibleJobs($pdo, $userId);
            $recentJobs = array_filter($allVisibleJobs, function($job) {
                $jobYear = !empty($job['job_date']) ? date('Y', strtotime($job['job_date'])) : null;
                return $jobYear == date('Y');
            });
            $recentJobs = array_slice($recentJobs, 0, 5);
        }
        
        try {
            $stmt = $pdo->prepare("SELECT DATE_FORMAT(created_at, '%M') as month, SUM(total_amount) as total FROM bills WHERE YEAR(created_at) = YEAR(CURDATE()) GROUP BY MONTH(created_at) ORDER BY MONTH(created_at)");
            $stmt->execute();
            $monthlyRevenue = $stmt->fetchAll();
        } catch (PDOException $e) {
            $monthlyRevenue = [];
        }
        
        try {
            if (isAdmin()) {
                $stmt = $pdo->prepare("SELECT b.*, j.consignee, j.job_number FROM bills b LEFT JOIN jobs j ON b.job_id = j.id ORDER BY b.created_at DESC LIMIT 5");
                $stmt->execute();
            } else {
                $stmt = $pdo->prepare("SELECT b.*, j.consignee, j.job_number FROM bills b LEFT JOIN jobs j ON b.job_id = j.id WHERE b.created_by = ? ORDER BY b.created_at DESC LIMIT 5");
                $stmt->execute([$userId]);
            }
            $recentBills = $stmt->fetchAll();
        } catch (PDOException $e) {
            $recentBills = [];
        }
        
    } catch (PDOException $e) {
        $totalJobs = 0;
        $activeJobs = 0;
        $totalBills = 0;
        $totalRevenue = 0;
        $recentJobs = [];
        $monthlyRevenue = [];
        $recentBills = [];
    }
}
   
