if ($page == 'create-job' && $_SERVER['REQUEST_METHOD'] == 'POST') {
    try {
        $jobNumber = generateJobNumber($pdo);
        $jobDate = !empty($_POST['job_date']) ? $_POST['job_date'] : date('Y-m-d');
        $userId = getUserId();
        
        $bonded_carrier = !empty($_POST['bonded_carrier']) ? $_POST['bonded_carrier'] : ($_POST['bonded_carrier_text'] ?? '');
        $customer_name = !empty($_POST['customer_name']) ? $_POST['customer_name'] : ($_POST['customer_name_text'] ?? '');
        $consignee_val = !empty($_POST['consignee']) ? $_POST['consignee'] : ($_POST['consignee_text'] ?? '');
        $container_size_val = !empty($_POST['container_size']) ? $_POST['container_size'] : ($_POST['container_size_text'] ?? '');
        $khi_port_val = !empty($_POST['khi_port']) ? $_POST['khi_port'] : ($_POST['khi_port_text'] ?? '');
        $dry_port_val = !empty($_POST['dry_port']) ? $_POST['dry_port'] : ($_POST['dry_port_text'] ?? '');
        $vessel_name_val = !empty($_POST['vessel_name']) ? $_POST['vessel_name'] : ($_POST['vessel_name_text'] ?? '');
        $shipping_line_val = !empty($_POST['shipping_line']) ? $_POST['shipping_line'] : ($_POST['shipping_line_text'] ?? '');
        $freight_forwarder_val = !empty($_POST['freight_forwarder_name']) ? $_POST['freight_forwarder_name'] : ($_POST['freight_forwarder_name_text'] ?? '');
        $depositor_val = !empty($_POST['depositor']) ? $_POST['depositor'] : ($_POST['depositor_text'] ?? '');
        
        // Free till value
        $free_till = $_POST['free_till'] ?? '';
        
        $stmt = $pdo->prepare("INSERT INTO jobs (job_number, original_documents_date, job_date, bonded_carrier, do_collected_date, customer_name, consignee, bl_number, container_number, container_size, khi_port, dry_port, port_of_loading, port_of_discharge, vessel_name, vessel_arrival_date, shipping_line, freight_forwarder_name, depositor, free_time, detention_tariff, soc, mobile_no, mbl_number, description, remarks, free_till, created_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
        
        $stmt->execute([
            $jobNumber, 
            !empty($_POST['original_documents_date']) ? $_POST['original_documents_date'] : null,
            $jobDate, 
            $bonded_carrier, 
            !empty($_POST['do_collected_date']) ? $_POST['do_collected_date'] : null,
            $customer_name,
            $consignee_val, 
            $_POST['bl_number'] ?? '', 
            $_POST['container_number'] ?? '', 
            $container_size_val, 
            $khi_port_val, 
            $dry_port_val,
            $_POST['port_of_loading'] ?? '', 
            $_POST['port_of_discharge'] ?? '',
            $vessel_name_val, 
            !empty($_POST['vessel_arrival_date']) ? $_POST['vessel_arrival_date'] : null, 
            $shipping_line_val, 
            $freight_forwarder_val, 
            $depositor_val, 
            $_POST['free_time'] ?? '',
            $_POST['detention_tariff'] ?? '', 
            $_POST['soc'] ?? 'No', 
            $_POST['mobile_no'] ?? '',
            $_POST['mbl_number'] ?? '',
            $_POST['description'] ?? '', 
            $_POST['remarks'] ?? '',
            $free_till,
            $userId
        ]);

        $jobId = $pdo->lastInsertId();


        // Find users who already have permission on this customer's old jobs
        $usersStmt = $pdo->prepare("
            SELECT DISTINCT ujp.user_id
            FROM user_job_permissions ujp
            INNER JOIN jobs j ON j.id = ujp.job_id
            WHERE j.customer_name = ?
        ");

        $usersStmt->execute([$customer_name]);

        $allowedUsers = $usersStmt->fetchAll(PDO::FETCH_COLUMN);


        // Copy permissions to new job
        if(!empty($allowedUsers)) {

            $permissionStmt = $pdo->prepare("
                INSERT IGNORE INTO user_job_permissions
                (
                    user_id,
                    job_id,
                    granted_by
                )
                VALUES (?, ?, ?)
            ");

            foreach($allowedUsers as $allowedUserId) {

                $permissionStmt->execute([
                    $allowedUserId,
                    $jobId,
                    $userId
                ]);

            }
        }
        
        $_SESSION['success'] = "Job created successfully! Job Number: " . $jobNumber;
        header("Location: system.php?page=create-job");
        exit();
    } catch(Exception $e) {
        $_SESSION['error'] = "Error: " . $e->getMessage();
        header("Location: system.php?page=create-job");
        exit();
    }
}

if ($page == 'jobs') {
    $userId = getUserId();
    $isAdmin = isAdmin();
    
    // Get all filter values from GET
    $search = isset($_GET['search']) ? trim($_GET['search']) : '';
    $start_date = isset($_GET['start_date']) ? $_GET['start_date'] : '';
    $end_date = isset($_GET['end_date']) ? $_GET['end_date'] : '';
    $year = isset($_GET['year']) ? $_GET['year'] : '';
    
    // Column filters
    $col_filters = [];
    $filter_columns = ['job_number', 'consignee', 'customer_name', 'bl_number', 'container_number', 'status', 
                       'vessel_name', 'shipping_line', 'bonded_carrier', 'container_size', 'khi_port', 
                       'dry_port', 'port_of_loading', 'port_of_discharge', 'freight_forwarder_name', 
                       'depositor', 'free_time', 'detention_tariff', 'soc', 'mobile_no', 'mbl_number', 'description', 'free_till'];
    foreach($filter_columns as $col) {
        if(isset($_GET['filter_' . $col]) && !empty($_GET['filter_' . $col])) {
            $col_filters[$col] = trim($_GET['filter_' . $col]);
        }
    }
    
    // Pagination variables
    $current_page = isset($_GET['p']) ? (int)$_GET['p'] : 1;
    $limit = 20;
    $offset = ($current_page - 1) * $limit;
    
    // Build WHERE clause
    $where = [];
    $params = [];
    
    // PERMISSION FILTER (NON-ADMIN USERS)
    if (!$isAdmin) {
        $where[] = "(created_by = :user_id OR EXISTS (SELECT 1 FROM user_job_permissions ujp WHERE ujp.job_id = jobs.id AND ujp.user_id = :perm_user_id))";
        $params[':user_id'] = $userId;
        $params[':perm_user_id'] = $userId;
    }
    
    // Date range filter
    if (!empty($start_date) && !empty($end_date)) {
        $where[] = "DATE(job_date) BETWEEN ? AND ?";
        $params[] = $start_date;
        $params[] = $end_date;
    } elseif (!empty($start_date)) {
        $where[] = "DATE(job_date) >= ?";
        $params[] = $start_date;
    } elseif (!empty($end_date)) {
        $where[] = "DATE(job_date) <= ?";
        $params[] = $end_date;
    }
    
    // Year filter
    if (!empty($year)) {
        $where[] = "YEAR(job_date) = ?";
        $params[] = $year;
    }
    
    // GLOBAL SEARCH
    if (!empty($search)) {
        $search_conditions = [];
        $search_columns = [
            'job_number', 'consignee', 'customer_name', 'bl_number', 'container_number',
            'vessel_name', 'shipping_line', 'bonded_carrier', 'container_size', 'khi_port',
            'dry_port', 'port_of_loading', 'port_of_discharge', 'freight_forwarder_name',
            'depositor', 'free_time', 'detention_tariff', 'soc', 'mobile_no', 'mbl_number', 'description',
            'remarks', 'status', 'free_till'
        ];
        foreach($search_columns as $col) {
            $search_conditions[] = "$col LIKE ?";
            $params[] = "%$search%";
        }
        $where[] = "(" . implode(" OR ", $search_conditions) . ")";
    }
    
    // Column filters
    foreach($col_filters as $col => $val) {
        $where[] = "$col LIKE ?";
        $params[] = "%$val%";
    }
    
    $where_clause = !empty($where) ? "WHERE " . implode(" AND ", $where) : "";
    
    // Get total count for pagination
    $count_sql = "SELECT COUNT(*) FROM jobs $where_clause";
    $count_stmt = $pdo->prepare($count_sql);
    $count_stmt->execute($params);
    $total_records = $count_stmt->fetchColumn();
    $total_pages = ($total_records > 0) ? ceil($total_records / $limit) : 1;
    
    // Ensure current page is valid
    if($current_page > $total_pages && $total_pages > 0) {
        $current_page = $total_pages;
        $offset = ($current_page - 1) * $limit;
    }
    
    // Get paginated jobs
    $sql = "SELECT * FROM jobs $where_clause ORDER BY id DESC LIMIT $limit OFFSET $offset";
    $stmt = $pdo->prepare($sql);
    $stmt->execute($params);
    $jobs = $stmt->fetchAll();
    
    // Store in session for view
    $_SESSION['jobs_data'] = $jobs;
    $_SESSION['jobs_total_records'] = $total_records;
    $_SESSION['jobs_total_pages'] = $total_pages;
    $_SESSION['jobs_current_page'] = $current_page;
    $_SESSION['jobs_limit'] = $limit;
    $_SESSION['jobs_start_date'] = $start_date;
    $_SESSION['jobs_end_date'] = $end_date;
    $_SESSION['jobs_search'] = $search;
    $_SESSION['jobs_year'] = $year;
    $_SESSION['jobs_col_filters'] = $col_filters;
}

