if ($page == 'get-last-job-bill-items') {
    header('Content-Type: application/json');
    
    $currentJobId = isset($_GET['job_id']) ? intval($_GET['job_id']) : 0;
    $billType = isset($_GET['bill_type']) ? $_GET['bill_type'] : 'forwarding';
    
    try {
        $stmt = $pdo->prepare("
            SELECT b.id as bill_id, b.job_id, j.job_number, bi.heading, bi.receipt_status 
            FROM bills b 
            JOIN bill_items bi ON bi.bill_id = b.id 
            JOIN jobs j ON j.id = b.job_id 
            WHERE b.job_id != :current_job_id 
            AND b.bill_type = :bill_type
            AND b.id = (
                SELECT MAX(id) FROM bills 
                WHERE job_id != :current_job_id2 
                AND bill_type = :bill_type2
            )
            ORDER BY bi.id ASC
        ");
        
        $stmt->execute([
            'current_job_id' => $currentJobId,
            'bill_type' => $billType,
            'current_job_id2' => $currentJobId,
            'bill_type2' => $billType
        ]);
        
        $results = $stmt->fetchAll();
        
        $items = [];
        $jobNumber = '';
        
        foreach ($results as $row) {
            $items[] = [
                'heading' => $row['heading'],
                'receipt_status' => $row['receipt_status'] ? $row['receipt_status'] : 'Receipted'
            ];
            $jobNumber = $row['job_number'];
        }
        
        echo json_encode([
            'items' => $items,
            'job_number' => $jobNumber,
            'count' => count($items)
        ]);
        
    } catch(PDOException $e) {
        echo json_encode([
            'items' => [],
            'job_number' => '',
            'count' => 0
        ]);
    }
    exit;
}

