        header("Location: system.php?page=jobs");
        exit();
    }
    
    // ========== FIXED: Query ab permissions ko bhi check karegi ==========
    if (isAdmin()) { 
        $stmt = $pdo->prepare("SELECT * FROM jobs WHERE id = ?"); 
        $stmt->execute([$job_id]); 
    } else { 
        $stmt = $pdo->prepare("
            SELECT j.* 
            FROM jobs j 
            WHERE j.id = ? 
            AND (
                j.created_by = ? 
                OR EXISTS (
                    SELECT 1 
                    FROM user_job_permissions ujp 
                    WHERE ujp.job_id = j.id 
                    AND ujp.user_id = ?
                )
            )
        "); 
        $stmt->execute([$job_id, $userId, $userId]); 
    }
    // ======================================================================
    
    $job = $stmt->fetch();
    if (!$job) { 
        $_SESSION['error'] = "Job not found!"; 
        header("Location: system.php?page=jobs"); 
        exit(); 
    }
