            !empty($_POST['port_of_loading']) ? $_POST['port_of_loading'] : ($existing_job['port_of_loading'] ?? ''),
            !empty($_POST['port_of_discharge']) ? $_POST['port_of_discharge'] : ($existing_job['port_of_discharge'] ?? ''),
            !empty($_POST['vessel_name']) ? $_POST['vessel_name'] : ($existing_job['vessel_name'] ?? ''),
            !empty($_POST['vessel_arrival_date']) ? $_POST['vessel_arrival_date'] : ($existing_job['vessel_arrival_date'] ?? null),
            !empty($_POST['shipping_line']) ? $_POST['shipping_line'] : ($existing_job['shipping_line'] ?? ''),
            !empty($_POST['freight_forwarder_name']) ? $_POST['freight_forwarder_name'] : ($existing_job['freight_forwarder_name'] ?? ''),
            !empty($_POST['depositor']) ? $_POST['depositor'] : ($existing_job['depositor'] ?? ''),
            !empty($_POST['free_time']) ? $_POST['free_time'] : ($existing_job['free_time'] ?? ''),
            !empty($_POST['detention_tariff']) ? $_POST['detention_tariff'] : ($existing_job['detention_tariff'] ?? ''),
            !empty($_POST['soc']) ? $_POST['soc'] : ($existing_job['soc'] ?? 'No'),
            !empty($_POST['mobile_no']) ? $_POST['mobile_no'] : ($existing_job['mobile_no'] ?? ''),
            !empty($_POST['description']) ? $_POST['description'] : ($existing_job['description'] ?? ''),
            !empty($_POST['remarks']) ? $_POST['remarks'] : ($existing_job['remarks'] ?? ''),
            $job_id
        ]);
        
        $_SESSION['success'] = "Job details updated successfully!";
    } catch (Exception $e) {
        $_SESSION['error'] = "Error updating job: " . $e->getMessage();
    }
    
    header("Location: system.php?page=" . $return_url);
    exit();
}

// ========== FUNCTION: Load Masters Data with Cache ==========
function loadAllMastersWithCache($pdo) {
    $all_masters = Cache::get('all_masters_data');

    if (!$all_masters || !is_array($all_masters)) {
        // If not in cache, load from database
        $all_masters = [
            'bonded_carriers' => getMasters($pdo, 'bonded_carrier') ?: [],
            'dos' => getMasters($pdo, 'do_collected_date') ?: [],
            'customer_names' => getMasters($pdo, 'customer_name') ?: [],
            'consignees' => getMasters($pdo, 'consignee') ?: [],
            'container_size' => getMasters($pdo, 'container_size') ?: [],
            'khiPorts' => getMasters($pdo, 'khi_port') ?: [],
            'dryPorts' => getMasters($pdo, 'dry_port') ?: [],
            'vessel_names' => getMasters($pdo, 'vessel_name') ?: [],
            'shippingLines' => getMasters($pdo, 'shipping_line') ?: [],
            'freight_forwarders' => getMasters($pdo, 'freight_forwarder_name') ?: [],
            'depositors' => getMasters($pdo, 'depositor') ?: []
        ];
        Cache::set('all_masters_data', $all_masters, 86400); // Cache for 24 hours
    }

    return $all_masters;
}

