        $stmt->execute([$_GET['id']]); 
    } else { 
        $stmt = $pdo->prepare("SELECT b.*, j.job_number, j.consignee, j.bl_number FROM bills b LEFT JOIN jobs j ON b.job_id = j.id WHERE b.id = ? AND b.created_by = ?"); 
        $stmt->execute([$_GET['id'], $userId]); 
    }
    $bill = $stmt->fetch();
    if (!$bill) { die("Bill not found!"); }
    $stmt = $pdo->prepare("SELECT * FROM bill_items WHERE bill_id = ? ORDER BY sort_order"); 
    $stmt->execute([$_GET['id']]); 
    $items = $stmt->fetchAll();
    $items = array_filter($items, function($item) {
        return floatval($item['amount'] ?? 0) > 0;
    });
    
    header('Content-Type: application/vnd.ms-excel');
    header('Content-Disposition: attachment; filename="qadria_invoice_' . ($bill['bill_number'] ?? 'bill') . '.xls"');
    echo "QADRIA INTERNATIONAL\n";
    echo "Invoice #\t" . ($bill['bill_number'] ?? '') . "\n";
    echo "Date\t" . date('Y-m-d', strtotime($bill['created_at'] ?? 'now')) . "\n";
    echo "Job #\t" . ($bill['job_number'] ?? '') . "\n";
    echo "Bill to\t" . ($bill['customer_name'] ?? '') . "\n";
    echo "Messer\t" . ($bill['consignee'] ?? '') . "\n\n";
    echo "Description\tStatus\tAmount\n";
    foreach ($items as $item) { 
        $status = $item['receipt_status'] ?? 'Unreceipted';
        echo ($item['heading'] ?? '') . "\t" . $status . "\t" . number_format($item['amount'] ?? 0, 2) . "\n"; 
    }
    echo "\nTotal Amount\t\t" . number_format($bill['total_amount'] ?? 0, 2) . "\n";
    echo "Advance Amount\t\t" . number_format($bill['advance_amount'] ?? 0, 2) . "\n";
    echo "Balance Amount\t\t" . number_format($bill['balance_amount'] ?? 0, 2) . "\n";
    exit();
}

if ($page == 'delete-invoice' && isset($_GET['path'])) {
    $path = $_GET['path'];
    $type = $_GET['type'] ?? 'file';
    $full_path = __DIR__ . '/invoices/' . $path;
    $userId = getUserId();
    
    if ($type == 'folder') {
        if (!canUserViewInvoiceDirectory($pdo, $userId, $path)) {
            $_SESSION['error'] = "You don't have permission to delete this folder!";
            header("Location: system.php?page=invoices");
            exit();
        }
    } else {
        if (!canUserViewInvoice($pdo, $userId, $path)) {
            $_SESSION['error'] = "You don't have permission to delete this file!";
            header("Location: system.php?page=invoices");
            exit();
        }
    }
    
    try {
        if ($type == 'folder') {
            if (is_dir($full_path)) {
                $files = glob($full_path . '/*');
                foreach ($files as $file) {
                    if (is_file($file)) {
                        unlink($file);
                    }
                }
                rmdir($full_path);
                $_SESSION['success'] = "Folder deleted successfully!";
            } else {
                $_SESSION['error'] = "Folder not found!";
            }
        } else {
            if (is_file($full_path)) {
                unlink($full_path);
                $_SESSION['success'] = "File deleted successfully!";
            } else {
                $_SESSION['error'] = "File not found!";
            }
        }
    } catch(Exception $e) {
        $_SESSION['error'] = "Error deleting: " . $e->getMessage();
    }
    
    $parent_path = dirname($path);
    if ($parent_path == '.') {
        $parent_path = '';
    }
    header("Location: system.php?page=invoices&path=" . urlencode($parent_path));
    exit();
}

