// Forgot password handling ke liye variables
$showForgotForm = false;
$showResetForm = false;
$resetToken = '';
$forgotError = '';
$forgotSuccess = '';

// Check if forgot password form dikhana hai
if (isset($_GET['forgot']) && $_GET['forgot'] == '1') {
    $showForgotForm = true;
}

// Check if reset password form dikhana hai  
if (isset($_GET['action']) && $_GET['action'] == 'reset' && isset($_GET['token'])) {
    $showResetForm = true;
    $resetToken = $_GET['token'];
}

// Forgot Password - Send Reset Link
if (isset($_POST['forgot_password'])) {
    $email = $_POST['email'];
    
    $stmt = $pdo->prepare("SELECT * FROM users WHERE email = ?");
    $stmt->execute([$email]);
    $user = $stmt->fetch();
    
    if ($user) {
        $token = bin2hex(random_bytes(32));
        $expiry = date('Y-m-d H:i:s', strtotime('+1 hour'));
        
        $update = $pdo->prepare("UPDATE users SET reset_token = ?, reset_token_expiry = ? WHERE email = ?");
        $update->execute([$token, $expiry, $email]);
        
        $resetLink = "https://qadriainternational.com/system.php?action=reset&token=" . $token;
        
        $to = $email;
        $subject = "Password Reset - QADIRA INTERNATIONAL";
        $message = "
        <html>
        <body>
            <h2>Password Reset Request</h2>
            <p>You requested to reset your password.</p>
            <p>Click this link to reset your password:</p>
            <p><a href='$resetLink'>$resetLink</a></p>
            <p>This link will expire in 1 hour.</p>
            <p>If you didn't request this, please ignore this email.</p>
            <br>
            <p>QADIRA INTERNATIONAL</p>
        </body>
        </html>
        ";
        
        $headers = "MIME-Version: 1.0\r\n";
        $headers .= "Content-type: text/html; charset=UTF-8\r\n";
        $headers .= "From: QADIRA INTERNATIONAL <noreply@qadriainternational.com>\r\n";
        
        if (mail($to, $subject, $message, $headers)) {
            $forgotSuccess = "Reset link has been sent to your email! Please check your inbox.";
        } else {
            $forgotError = "Failed to send email. Please try again later.";
        }
    } else {
        $forgotError = "No account found with this email address!";
    }
}

// Reset Password - Save New Password
// Reset Password - Save New Password
if (isset($_POST['reset_password'])) {
    // Token POST se lo, agar nahi hai to GET se lo
    $token = isset($_POST['token']) ? $_POST['token'] : (isset($_GET['token']) ? $_GET['token'] : '');
    $newPassword = isset($_POST['new_password']) ? $_POST['new_password'] : '';
    $confirmPassword = isset($_POST['confirm_password']) ? $_POST['confirm_password'] : '';
    
    if (empty($token)) {
        $error = "Invalid reset link!";
    } elseif ($newPassword !== $confirmPassword) {
        $error = "Passwords do not match!";
    } elseif (strlen($newPassword) < 6) {
        $error = "Password must be at least 6 characters!";
    } else {
        $stmt = $pdo->prepare("SELECT * FROM users WHERE reset_token = ? AND reset_token_expiry > NOW()");
        $stmt->execute([$token]);
        $user = $stmt->fetch();
        
        if ($user) {
            $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);
            
            $update = $pdo->prepare("UPDATE users SET password = ?, reset_token = NULL, reset_token_expiry = NULL WHERE id = ?");
            $update->execute([$hashedPassword, $user['id']]);
            
            $forgotSuccess = "Password reset successful! You can now login with your new password.";
            $showResetForm = false;
        } else {
            $error = "Invalid or expired reset link!";
        }
    }
}



