// Bulk grant by job IDs - with batching support
if ($page == 'bulk-grant-permissions' && $_SERVER['REQUEST_METHOD'] == 'POST' && isAdmin()) {
    $user_id = (int)$_POST['user_id'];
    $job_ids = isset($_POST['job_ids']) ? $_POST['job_ids'] : [];
    
    // Handle JSON input for batched requests
    if (empty($job_ids)) {
        $json_input = json_decode(file_get_contents('php://input'), true);
        if ($json_input && isset($json_input['job_ids'])) {
            $job_ids = $json_input['job_ids'];
            $user_id = (int)$json_input['user_id'];
        }
    }
    
    if (empty($job_ids)) {
        $_SESSION['error'] = "No jobs selected!";
        header("Location: system.php?page=manage-permissions&user_id=" . $user_id);
        exit();
    }
    
    $total_granted = 0;
    $total_jobs = count($job_ids);
    
    foreach ($job_ids as $job_id) {
        if (grantJobPermission($pdo, $user_id, (int)$job_id)) {
            $total_granted++;
        }
    }
    
    // If it's an AJAX request, return JSON
    if (!empty($_SERVER['HTTP_X_REQUESTED_WITH']) && strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) == 'xmlhttprequest') {
        echo json_encode(['success' => true, 'granted' => $total_granted, 'total' => $total_jobs]);
        exit();
    }
    
    $_SESSION['success'] = "Permissions granted for " . $total_granted . " out of " . $total_jobs . " selected job(s)";
    header("Location: system.php?page=manage-permissions&user_id=" . $user_id);
    exit();
}

// Bulk revoke by job IDs - with batching support
elseif ($page == 'bulk-revoke-permissions' && $_SERVER['REQUEST_METHOD'] == 'POST' && isAdmin()) {
    $user_id = (int)$_POST['user_id'];
    $job_ids = isset($_POST['job_ids']) ? $_POST['job_ids'] : [];
    
