}

// Grant single clearance permission
if ($page == 'grant-clearance-permission' && isset($_GET['user_id']) && isset($_GET['clearance_id']) && isAdmin()) {
    try {
        $userId = $_GET['user_id'];
        $clearanceId = $_GET['clearance_id'];
        $adminId = getUserId();
        
        $checkStmt = $pdo->prepare("SELECT id FROM user_karachi_clearance_permissions WHERE user_id = ? AND record_id = ?");
        $checkStmt->execute([$userId, $clearanceId]);
        
        if (!$checkStmt->fetch()) {
            $stmt = $pdo->prepare("INSERT INTO user_karachi_clearance_permissions (user_id, record_id, granted_by) VALUES (?, ?, ?)");
            $stmt->execute([$userId, $clearanceId, $adminId]);
            $_SESSION['success'] = "Clearance permission granted successfully!";
        } else {
            $_SESSION['info'] = "Permission already exists!";
        }
    } catch(Exception $e) {
        $_SESSION['error'] = "Error granting permission: " . $e->getMessage();
    }
    header("Location: system.php?page=manage-permissions&tab=clearance&user_id=" . $_GET['user_id']);
    exit();
}

