// Bulk grant clearance permissions
if ($page == 'bulk-grant-clearance-permissions' && isAdmin()) {
    header('Content-Type: application/json');
    try {
        $userId = $_POST['user_id'] ?? 0;
        $clearanceIds = $_POST['clearance_ids'] ?? [];
        $adminId = getUserId();
        $granted = 0;
        $stmt = $pdo->prepare("INSERT IGNORE INTO user_karachi_clearance_permissions (user_id, record_id, granted_by) VALUES (?, ?, ?)");
        foreach ($clearanceIds as $id) { $stmt->execute([$userId, $id, $adminId]); if ($stmt->rowCount() > 0) $granted++; }
        echo json_encode(['success' => true, 'total' => count($clearanceIds), 'granted' => $granted]);
    } catch(Exception $e) { echo json_encode(['success' => false, 'error' => $e->getMessage()]); }
    exit();
}

// Bulk revoke clearance permissions
if ($page == 'bulk-revoke-clearance-permissions' && isAdmin()) {
    header('Content-Type: application/json');
    try {
        $userId = $_POST['user_id'] ?? 0;
        $clearanceIds = $_POST['clearance_ids'] ?? [];
        $revoked = 0;
        $stmt = $pdo->prepare("DELETE FROM user_karachi_clearance_permissions WHERE user_id = ? AND record_id = ?");
        foreach ($clearanceIds as $id) { $stmt->execute([$userId, $id]); if ($stmt->rowCount() > 0) $revoked++; }
        echo json_encode(['success' => true, 'total' => count($clearanceIds), 'revoked' => $revoked]);
