    exit();
}


if ($page == 'invoices') {
    $current_path = isset($_GET['path']) ? $_GET['path'] : '';
    $full_path = __DIR__ . '/invoices/' . $current_path;
    $userId = getUserId();
    
    if (is_file($full_path)) {
        if (canUserViewInvoice($pdo, $userId, $current_path)) {
            // Detect file type from extension
            $extension = strtolower(pathinfo($full_path, PATHINFO_EXTENSION));
            
            if ($extension === 'pdf') {
                header('Content-Type: application/pdf');
                header('Content-Disposition: inline; filename="' . basename($current_path) . '"');
            } elseif (in_array($extension, ['jpg', 'jpeg', 'png', 'gif', 'webp'])) {
                $mime_types = [
                    'jpg' => 'image/jpeg',
                    'jpeg' => 'image/jpeg',
                    'png' => 'image/png',
                    'gif' => 'image/gif',
                    'webp' => 'image/webp',
                ];
                header('Content-Type: ' . $mime_types[$extension]);
            } else {
                header('Content-Type: application/octet-stream');
            }
            
            header('Content-Length: ' . filesize($full_path));
            readfile($full_path);
            exit();
        } else {
            $_SESSION['error'] = "You don't have permission to view this invoice!";
            header("Location: system.php?page=invoices");
            exit();
        }
    }
    
    $items = getUserInvoiceItems($pdo, $userId, $current_path);
}

