        .form-group { margin-bottom:20px; }
        .form-group input, .form-group select, .form-group textarea { width:100%; padding:12px 15px; border:2px solid #e9edf2; border-radius:12px; font-size:1rem; }
        .form-group input:focus, .form-group select:focus { outline:none; border-color:#8e181e; }
        .checkbox-group { display:flex; justify-content:space-between; margin:20px 0; }
        .login-btn { width:100%; padding:12px; background:#8e181e; color:white; border:none; border-radius:12px; font-size:1rem; font-weight:600; cursor:pointer; }
        .login-btn:hover { background:#6b1217; }
        .error-message { background:#ffebee; color:#c62828; padding:12px; border-radius:12px; margin-bottom:20px; text-align:center; }
        .success-message { background:#e8f5e9; color:#2e7d32; padding:12px; border-radius:12px; margin-bottom:20px; text-align:center; }
        .dashboard-container { display:flex; min-height:100vh; }
        .sidebar { width:296px; background:#18224b; position:fixed; height:100vh; overflow:hidden; z-index:100; box-shadow:2px 0 10px rgba(0,0,0,0.1); transition:transform 0.3s ease-in-out; transform:translateX(0); }
        .sidebar.collapsed { transform:translateX(-100%); }
        .sidebar-header { padding:30px 0px; text-align:center; border-bottom:1px solid rgba(255,255,255,0.2); background:rgba(0,0,0,0.1); }
        .sidebar-logo-wrapper { background:white; padding:15px; border-radius:20px; display:inline-block; box-shadow:0 4px 15px rgba(0,0,0,0.15); }
        .sidebar-logo { height:75px; width:auto; display:block; margin:0 auto; }
        .sidebar-nav { padding:20px 0; }
        .nav-item { display:flex; align-items:center; padding:12px 20px; color:rgba(255,255,255,0.85); text-decoration:none; gap:12px; transition:all 0.3s; }
        .nav-item:hover, .nav-item.active { background:rgba(255,255,255,0.2); border-left:3px solid #8e181e; }
        .nav-item i { width:20px; }
        .main-content { flex:1; margin-left:296px; background:#fcfdff; min-height:100vh; transition:margin-left 0.3s ease-in-out; }
        body.sidebar-collapsed .main-content { margin-left:0; }
        .top-header { background:white; padding:15px 25px; display:flex; justify-content:space-between; align-items:center; box-shadow:0 2px 5px rgba(0,0,0,0.05); position:sticky; top:0; z-index:99; }
        .sidebar-toggle-header { background:#8e181e; width:40px; height:40px; border-radius:12px; display:flex; align-items:center; justify-content:center; cursor:pointer; transition:all 0.3s; margin-right:15px; box-shadow:0 2px 5px rgba(0,0,0,0.1); }
        .sidebar-toggle-header:hover { background:#6b1217; transform:scale(1.02); }
        .sidebar-toggle-header i { color:white; font-size:18px; }
        .header-search { display:flex; align-items:center; background:#f5f9f5; padding:8px 15px; border-radius:12px; width:300px; }
        .header-search i { color:#479ace; margin-right:8px; }
        .header-search input { border:none; background:none; outline:none; width:100%; }
        .user-menu { display:flex; align-items:center; gap:15px; }
        .user-name { color:#18224b; font-weight:600; }
        .user-avatar { width:40px; height:40px; background:#8e181e; border-radius:50%; display:flex; align-items:center; justify-content:center; color:white; cursor:pointer; position:relative; }
        .user-dropdown { position:absolute; top:50px; right:0; background:white; border-radius:12px; box-shadow:0 5px 20px rgba(0,0,0,0.15); width:280px; display:none; z-index:1000; overflow:hidden; }
        .user-dropdown.show { display:block; }
        .dropdown-header { padding:15px; border-bottom:1px solid #e9edf2; background:#f8fafd; }
        .dropdown-header h4 { color:#18224b; margin-bottom:5px; }
        .dropdown-header p { font-size:12px; color:#666; }
        .dropdown-item { padding:12px 15px; display:flex; align-items:center; gap:12px; text-decoration:none; color:#333; transition:all 0.3s; border-bottom:1px solid #e9edf2; cursor:pointer; }
        .dropdown-item:hover { background:#f8fafd; }
        .dropdown-item i { width:20px; color:#8e181e; }
        .dropdown-item.logout { color:#ef5350; }
        .dropdown-item.logout i { color:#ef5350; }
        .content-wrapper { padding:25px; }
        .dashboard-header { display:flex; justify-content:space-between; align-items:center; margin-bottom:25px; flex-wrap:wrap; gap:15px; }
        .page-title { font-size:1.8rem; color:#18224b; }
        .page-subtitle { color:#479ace; margin-top:5px; }
        .stats-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(240px,1fr)); gap:20px; margin-bottom:25px; }
        .stat-card { background:white; border-radius:16px; padding:20px; display:flex; align-items:center; justify-content:space-between; cursor:pointer; transition:all 0.3s; box-shadow:0 2px 5px rgba(0,0,0,0.05); }
        .stat-card:hover { transform:translateY(-5px); box-shadow:0 5px 20px rgba(0,0,0,0.1); }
        .stat-icon { width:55px; height:55px; background:#f8fafd; border-radius:12px; display:flex; align-items:center; justify-content:center; font-size:1.5rem; color:#8e181e; }
        .stat-info h3 { font-size:1.8rem; color:#18224b; }
        .stat-info p { color:#479ace; }
        .card { background:white; border-radius:16px; overflow:hidden; box-shadow:0 2px 5px rgba(0,0,0,0.05); margin-bottom:20px; }
        .card-header { padding:15px 20px; border-bottom:1px solid #e9edf2; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; }
        .card-header h3 { color:#18224b; font-size:1.2rem; }
        .card-header h3 i { color:#8e181e; margin-right:8px; }
        .card-body { padding:20px; }
        .table-container { overflow-x:auto; border-radius:12px; -webkit-overflow-scrolling:touch; }
        .data-table { width:100%; border-collapse:collapse; background:white; border-radius:12px; overflow:hidden; min-width:600px; }
        .data-table thead { background:#18224b; }
        .data-table th { color:white; padding:14px 12px; text-align:left; font-weight:600; font-size:0.85rem; white-space:nowrap; }
        .data-table td { padding:12px; border-bottom:1px solid #e9edf2; color:#4a5568; font-size:0.85rem; }
        .data-table tbody tr { transition:all 0.3s; cursor:pointer; }
        .data-table tbody tr:hover { background:#f8fafd; }
        .status-badge { display:inline-block; padding:4px 12px; border-radius:20px; font-size:0.7rem; font-weight:600; white-space:nowrap; }
        .status-badge.active { background:#e8f5e9; color:#4caf50; }
        .status-badge.completed { background:#e3f2fd; color:#2196f3; }
        .status-badge.cancelled { background:#ffebee; color:#f44336; }
        .btn-primary { background:#8e181e; color:white; border:none; padding:8px 20px; border-radius:8px; cursor:pointer; display:inline-flex; align-items:center; gap:8px; text-decoration:none; font-size:0.85rem; transition:all 0.3s; }
        .btn-primary:hover { background:#6b1217; transform:translateY(-2px); box-shadow:0 4px 12px rgba(142,24,30,0.3); }
        .btn-danger { background:#ef5350; color:white; border:none; padding:5px 12px; border-radius:6px; cursor:pointer; text-decoration:none; font-size:0.75rem; transition:all 0.3s; display:inline-flex; align-items:center; gap:5px; }
        .btn-danger:hover { background:#c62828; }
        .btn-warning { background:#ff9800; color:white; border:none; padding:5px 12px; border-radius:6px; cursor:pointer; font-size:0.75rem; transition:all 0.3s; display:inline-flex; align-items:center; gap:5px; }
        .btn-warning:hover { background:#e65100; }
        .btn-info { background:#479ace; color:white; border:none; padding:5px 12px; border-radius:6px; cursor:pointer; font-size:0.75rem; text-decoration:none; transition:all 0.3s; display:inline-flex; align-items:center; gap:5px; }
        .btn-info:hover { background:#2c7cb3; }
        .btn-success { background:#2196f3; color:white; border:none; padding:5px 12px; border-radius:6px; cursor:pointer; font-size:0.75rem; text-decoration:none; transition:all 0.3s; display:inline-flex; align-items:center; gap:5px; }
        .btn-success:hover { background:#1565c0; }
        .btn-link { color:#8e181e; text-decoration:none; font-size:0.85rem; }
        .action-buttons { display:flex; gap:5px; flex-wrap:wrap; }
        .form-row { display:grid; grid-template-columns:repeat(2,1fr); gap:20px; margin-bottom:20px; }
        .form-group { margin-bottom:20px; }
        .form-group label { display:block; margin-bottom:8px; color:#8e181e; font-weight:500; font-size:0.85rem; }
        .bill-items-table { width:100%; margin-bottom:20px; border-collapse:collapse; }
        .bill-items-table th { background:#8e181e; color:white; padding:12px; text-align:left; }
        .bill-items-table td { padding:10px; border-bottom:1px solid #e9edf2; }
        .remove-row { background:#ef5350; color:white; border:none; padding:5px 10px; border-radius:5px; cursor:pointer; }
        .add-row { background:#8e181e; color:white; border:none; padding:8px 16px; border-radius:8px; cursor:pointer; margin-bottom:20px; }
        .modal { display:none; position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.5); z-index:1000; align-items:center; justify-content:center; }
        .modal-content { background:white; border-radius:16px; max-width:900px; width:90%; max-height:80vh; overflow-y:auto; }
        .modal-header { padding:20px; border-bottom:1px solid #e9edf2; display:flex; justify-content:space-between; align-items:center; position:sticky; top:0; background:white; z-index:10; }
        .modal-header h3 { color:#18224b; }
        .modal-body { padding:20px; }
        .modal-footer { padding:20px; border-top:1px solid #e9edf2; display:flex; justify-content:flex-end; gap:10px; position:sticky; bottom:0; background:white; }
        .close-modal { background:none; border:none; font-size:1.5rem; cursor:pointer; color:#999; transition:all 0.3s; }
        .close-modal:hover { color:#8e181e; transform:rotate(90deg); }
        .folder-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(220px,1fr)); gap:20px; margin-bottom:30px; }
        .folder-card { background:white; border-radius:12px; padding:20px; text-align:center; transition:all 0.3s; border:1px solid #e9edf2; position:relative; }
        .folder-card:hover { transform:translateY(-5px); box-shadow:0 5px 20px rgba(0,0,0,0.1); border-color:#8e181e; }
        .folder-icon { font-size:3rem; color:#ff9800; margin-bottom:10px; cursor:pointer; }
        .folder-name { font-weight:600; color:#18224b; cursor:pointer; }
        .master-types { display:flex; flex-wrap:wrap; gap:8px; margin-bottom:20px; }
        .master-type-btn { background:#f8fafd; border:1px solid #c8e6c9; padding:8px 16px; border-radius:20px; cursor:pointer; text-decoration:none; color:#18224b; font-size:0.85rem; transition:all 0.3s; }
        .master-type-btn:hover, .master-type-btn.active { background:#8e181e; color:white; border-color:#8e181e; }
        .invoice-wrapper { background:white; border-radius:16px; padding:30px; max-width:1000px; margin:0 auto; }
        .invoice-header { text-align:center; border-bottom:2px solid #8e181e; padding-bottom:20px; margin-bottom:30px; }
        .invoice-header .logo-img { height:50px; width:auto; margin-bottom:10px; }
        .invoice-title { font-size:1.8rem; color:#18224b; margin-bottom:10px; }
        .invoice-details { display:flex; justify-content:space-between; margin-bottom:30px; padding:15px; background:#f8fafd; border-radius:8px; flex-wrap:wrap; gap:15px; }
        
        .invoice-table { width:100%; border-collapse:collapse; margin-bottom:30px; }
        
        .invoice-table th { background:#8e181e; color:white; padding:12px; text-align:left; }
        
        .invoice-table td { padding:12px; border-bottom:1px solid #e9edf2; }
        
        .invoice-total { text-align:right; margin-top:20px; padding-top:20px; border-top:2px solid #8e181e; }
        
        .invoice-total p { margin:5px 0; }
        
        
        .invoice-footer { text-align:center; margin-top:50px; font-size:12px; color:#666; }
        .menu-toggle { display:none; background:#8e181e; color:white; border:none; padding:10px; border-radius:8px; cursor:pointer; margin-right:15px; }
        .shortcut-hint { position:fixed; bottom:10px; right:10px; background:rgba(0,0,0,0.7); color:white; padding:5px 10px; border-radius:5px; font-size:10px; z-index:999; }
        .chart-container { margin-bottom:25px; background:white; border-radius:16px; padding:20px; }
        .chart-bar { display:flex; align-items:center; margin-bottom:10px; }
        .chart-label { width:100px; font-size:12px; color:#666; }
        .chart-bar-fill { height:30px; background:#8e181e; border-radius:5px; display:flex; align-items:center; justify-content:flex-end; padding-right:10px; color:white; font-size:11px; min-width:30px; }
        .quick-actions { display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:15px; margin-bottom:25px; }
        .quick-action-card { background:white; border-radius:12px; padding:15px; text-align:center; cursor:pointer; transition:all 0.3s; border:1px solid #e9edf2; }
        .quick-action-card:hover { transform:translateY(-3px); box-shadow:0 5px 15px rgba(0,0,0,0.1); border-color:#8e181e; }
        .quick-action-icon { font-size:1.8rem; color:#8e181e; margin-bottom:10px; }
        
        /* Google Sheets Style for Jobs Table - Only for jobs table */
        .jobs-google-sheets-container {
            overflow-x: auto;
            border-radius: 8px;
            border: 1px solid #e0e0e0;
            background: white;
            max-height: calc(100vh - 300px);
            overflow-y: auto;
        }
        .jobs-google-sheets-container::-webkit-scrollbar {
            width: 8px;
            height: 8px;
        }
        .jobs-google-sheets-container::-webkit-scrollbar-track {
            background: #f1f1f1;
            border-radius: 4px;
        }
        .jobs-google-sheets-container::-webkit-scrollbar-thumb {
            background: #c1c1c1;
            border-radius: 4px;
        }
        .jobs-google-sheets-container::-webkit-scrollbar-thumb:hover {
            background: #a8a8a8;
        }
        .jobs-google-sheets-table {
            width: 100%;
            border-collapse: collapse;
            font-family: 'Segoe UI', 'Roboto', 'Arial', sans-serif;
            font-size: 13px;
            background: white;
        }
        .jobs-google-sheets-table thead tr {
            background-color: #f8f9fa;
            border-bottom: 1px solid #e0e0e0;
        }
        .jobs-google-sheets-table th {
            padding: 8px 6px;
            text-align: left;
            font-weight: 500;
            color: #202124;
            font-size: 13px;
            border-right: 1px solid #e0e0e0;
            background-color: #f8f9fa;
            white-space: nowrap;
            position: sticky;
            top: 0;
            z-index: 10;
        }
        .jobs-google-sheets-table th:last-child {
            border-right: none;
        }
        .jobs-google-sheets-table td {
            padding: 8px 6px;
            border-bottom: 1px solid #e8eaed;
            border-right: 1px solid #e8eaed;
            color: #202124;
            font-size: 13px;
            white-space: nowrap;
            transition: background-color 0.2s ease;
        }
        .jobs-google-sheets-table td:last-child {
            border-right: none;
        }
        .jobs-google-sheets-table tbody tr:hover {
            background-color: #f0f5ff;
            cursor: pointer;
        }
        .jobs-google-sheets-table tbody tr.selected {
            background-color: #e8f0fe;
        }
        .jobs-google-sheets-table .action-cell {
            white-space: nowrap;
            text-align: center;
        }
        .jobs-google-sheets-table .btn-sm {
            padding: 4px 8px;
            font-size: 11px;
            margin: 0 2px;
            border-radius: 4px;
            border: none;
            cursor: pointer;
            transition: all 0.2s ease;
        }
        .jobs-google-sheets-table .btn-sm i {
            font-size: 11px;
        }
        .jobs-google-sheets-table .btn-sm:hover {
            transform: scale(1.02);
            opacity: 0.9;
        }
        .jobs-google-sheets-table .status-badge {
            display: inline-block;
            padding: 2px 8px;
            border-radius: 12px;
            font-size: 11px;
            font-weight: 500;
            text-align: center;
            white-space: nowrap;
        }
        .jobs-google-sheets-table .status-badge.active {
            background-color: #e6f4ea;
            color: #137333;
        }
        .jobs-google-sheets-table .status-badge.completed {
            background-color: #e8f0fe;
            color: #1967d2;
        }
        .jobs-google-sheets-table .status-badge.cancelled {
            background-color: #fce8e6;
            color: #c5221f;
        }
        .jobs-google-sheets-table th.sortable {
            cursor: pointer;
            user-select: none;
            position: relative;
            padding-right: 20px;
        }
        .jobs-google-sheets-table th.sortable:hover {
            background-color: #e8eaed;
        }
        .jobs-google-sheets-table th.sortable::after {
            content: '⇅';
            position: absolute;
            right: 6px;
            top: 50%;
            transform: translateY(-50%);
            opacity: 0.4;
            font-size: 11px;
        }
        .jobs-google-sheets-table th.sortable.asc::after {
            content: '↑';
            opacity: 1;
        }
        .jobs-google-sheets-table th.sortable.desc::after {
            content: '↓';
            opacity: 1;
        }
        
        /* Jobs table column filter styles */
        .jobs-google-sheets-table th {
            position: relative;
        }
        .column-filter {
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            padding: 2px 4px;
            background: #f8f9fa;
            border-top: 1px solid #e0e0e0;
        }
        .column-filter input {
            width: 100%;
            padding: 2px 4px;
            font-size: 11px;
            border: 1px solid #ddd;
            border-radius: 3px;
            background: white;
        }
        .column-filter input:focus {
            outline: none;
            border-color: #8e181e;
        }
        
        .date-filter {
            background: white;
            border-radius: 12px;
            padding: 15px 20px;
            margin-bottom: 20px;
            display: flex;
            flex-wrap: wrap;
            align-items: flex-end;
            gap: 15px;
            box-shadow: 0 2px 5px rgba(0,0,0,0.05);
            border: 1px solid #e0e0e0;
        }
        .date-filter-group {
            display: flex;
            flex-direction: column;
            gap: 5px;
        }
        .date-filter-group label {
            font-size: 12px;
            color: #8e181e;
            font-weight: 600;
        }
        .date-filter-group input {
            padding: 8px 12px;
            border: 1px solid #e0e0e0;
            border-radius: 8px;
            font-size: 14px;
            background: white;
        }
        .filter-actions {
            display: flex;
            gap: 10px;
            margin-left: auto;
        }
        @media (max-width: 768px) {
            .date-filter {
                flex-direction: column;
                align-items: stretch;
            }
            .filter-actions {
                margin-left: 0;
                justify-content: flex-end;
            }
        }
        
        .bill-summary-section { margin-top: 25px; padding-top: 20px; border-top: 2px solid #e9edf2; }
        .bill-summary-title { font-size: 16px; font-weight: bold; color: #18224b; margin-bottom: 15px; }
        .bill-summary-title i { color: #8e181e; margin-right: 8px; }
        .bill-summary-table { width: 100%; border-collapse: collapse; font-size: 13px; }
        .bill-summary-table th { background: #f8fafd; padding: 10px; text-align: left; color: #18224b; font-weight: 600; border-bottom: 2px solid #e0e0e0; }
        .bill-summary-table td { padding: 8px 10px; border-bottom: 1px solid #e9edf2; }
        .bill-summary-table tr:hover { background: #f8fafd; }
        .bill-summary-table .bill-type-badge { display: inline-block; padding: 4px 10px; border-radius: 20px; font-size: 11px; font-weight: 600; }
        .bill-type-badge.forwarding { background: #e3f2fd; color: #2196f3; }
        .bill-type-badge.detention { background: #fff3e0; color: #ff9800; }
        .bill-summary-empty { text-align: center; padding: 20px; color: #999; font-style: italic; }
        .view-bill-link { color: #8e181e; text-decoration: none; font-size: 12px; }
        .view-bill-link:hover { text-decoration: underline; }
        
        /* Karachi Clearance Table Styles */
        .clearance-table {
            width: 100%;
            border-collapse: collapse;
            background: white;
            border-radius: 12px;
            overflow: hidden;
        }
        .clearance-table th {
            background: #18224b;
            color: white;
            padding: 12px;
            text-align: left;
            font-weight: 600;
            font-size: 0.85rem;
            white-space: nowrap;
        }
        .clearance-table td {
            padding: 10px 12px;
            border-bottom: 1px solid #e9edf2;
            color: #4a5568;
            font-size: 0.85rem;
        }
        .clearance-table tbody tr:hover {
            background: #f8fafd;
        }
        
        /* Loading File Table Styles - UPDATED FOR IN-TABLE EDIT & WIDER FIELDS */
        .loading-table {
            width: 100%;
            border-collapse: collapse;
            background: white;
            border-radius: 12px;
            overflow: hidden;
        }
        .loading-table th {
            background: #18224b;
            color: white;
            padding: 12px 8px;
            text-align: left;
            font-weight: 600;
            font-size: 0.85rem;
            white-space: nowrap;
        }
        .loading-table td {
            padding: 10px 8px;
            border-bottom: 1px solid #e9edf2;
            color: #4a5568;
            font-size: 0.85rem;
        }
        .loading-table tbody tr:hover {
            background: #f8fafd;
        }
        .loading-table .editable-row input, 
        .loading-table .editable-row select {
            width: 100%;
            min-width: 100px;
            padding: 8px 10px;
            border: 1px solid #c8e6c9;
            border-radius: 6px;
            font-size: 0.85rem;
            background: #fff;
            box-sizing: border-box;
        }
        .loading-table .editable-row .save-btn, 
        .loading-table .editable-row .cancel-btn {
            padding: 6px 12px;
            font-size: 12px;
            margin: 0 2px;
        }
        /* Wider input fields for specific columns */
        .loading-table .editable-row input[name="importer"],
        .loading-table .editable-row input[name="clearing_agent"],
