                    <input type="date" id="job_end_date" value="<?php echo htmlspecialchars($_SESSION['jobs_end_date'] ?? ''); ?>">
                </div>
                <div class="date-filter-group" style="flex-direction:row; align-items:flex-end; gap:8px;">
                    <div style="display:flex; flex-direction:column; gap:5px;">
                        <label><i class="fas fa-calendar-year"></i> Filter by Year</label>
                        <select id="job_year_filter" class="form-control">
                            <option value="">-- All Years --</option>
                            <?php
                            $currentYear = date('Y');
                            $selectedYear = !empty($_SESSION['jobs_year']) ? $_SESSION['jobs_year'] : $currentYear;
                            
                            $year_stmt = $pdo->query("SELECT DISTINCT YEAR(job_date) as yr FROM jobs WHERE job_date IS NOT NULL ORDER BY yr DESC");
                            while($yr_data = $year_stmt->fetch(PDO::FETCH_ASSOC)) {
                                $selected = ($selectedYear == $yr_data['yr']) ? 'selected' : '';
                                echo '<option value="'.$yr_data['yr'].'" '.$selected.'>'.$yr_data['yr'].'</option>';
                            }
                            ?>
                        </select>
