.jobs-google-sheets-table { width: 100%; border-collapse: collapse; font-family: 'Segoe UI', 'Roboto', 'Arial', sans-serif; font-size: 13px; background: white; }
.jobs-google-sheets-table th { padding: 10px 8px; text-align: left; font-weight: 600; font-size: 13px; border-right: 1px solid rgba(255,255,255,0.2); background-color: #18224b; color: white; white-space: nowrap; position: relative; }
.jobs-google-sheets-table th.sortable { cursor: pointer; }
.jobs-google-sheets-table th.sortable::after { content: '⇅'; position: absolute; right: 6px; top: 50%; transform: translateY(-50%); opacity: 0.6; font-size: 11px; color: white; }
.jobs-google-sheets-table th.sortable.asc::after { content: '↑'; }
.jobs-google-sheets-table th.sortable.desc::after { content: '↓'; }
