    background: rgba(255,255,255,0.5);
}
.resize-handle::after {
    content: '';
    position: absolute;
    top: 0;
    right: -2px;
    bottom: 0;
    width: 5px;
    background: transparent;
}

.date-filter { background: white; border-radius: 12px; padding: 15px 20px; margin-bottom: 20px; display: flex; flex-wrap: wrap; align-items: flex-end; gap: 15px; box-shadow: 0 2px 5px rgba(0,0,0,0.05); border: 1px solid #e0e0e0; }
.date-filter-group { display: flex; flex-direction: column; gap: 5px; }
.date-filter-group label { font-size: 12px; color: #8e181e; font-weight: 600; }
.date-filter-group input, .date-filter-group select { padding: 8px 12px; border: 1px solid #e0e0e0; border-radius: 8px; font-size: 14px; background: white; }
.filter-actions { display: flex; gap: 10px; margin-left: auto; }
.status-badge { display: inline-block; padding: 4px 12px; border-radius: 20px; font-size: 0.7rem; font-weight: 600; white-space: nowrap; }
.status-badge.active { background: #e8f5e9; color: #4caf50; }
.status-badge.completed { background: #e3f2fd; color: #2196f3; }
.status-badge.cancelled { background: #ffebee; color: #f44336; }
.btn-primary { background:#8e181e; color:white; border:none; padding:8px 20px; border-radius:8px; cursor:pointer; display:inline-flex; align-items:center; gap:8px; text-decoration:none; font-size:0.85rem; }
.btn-primary:hover { background:#6b1217; }
.btn-danger { background:#ef5350; color:white; border:none; padding:5px 12px; border-radius:6px; cursor:pointer; text-decoration:none; font-size:0.75rem; }
.btn-warning { background:#ff9800; color:white; border:none; padding:5px 12px; border-radius:6px; cursor:pointer; font-size:0.75rem; }
.btn-info { background:#479ace; color:white; border:none; padding:5px 12px; border-radius:6px; cursor:pointer; font-size:0.75rem; }
.btn-success { background:#2196f3; color:white; border:none; padding:5px 12px; border-radius:6px; cursor:pointer; font-size:0.75rem; }
.search-highlight { background-color: #FFEB3B; color: #000; padding: 0 2px; border-radius: 3px; font-weight: bold; }
.search-info { background: #e3f2fd; padding: 10px 15px; border-radius: 8px; margin-bottom: 15px; border-left: 4px solid #2196f3; }
.col-filter.active-filter { border-color: #ff9800 !important; background: #fff8e1 !important; }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.jobs-google-sheets-table tbody tr { animation: fadeIn 0.3s; }

.bills-detail-table { width: 100%; border-collapse: collapse; margin-top: 10px; font-family: 'Segoe UI', 'Roboto', 'Arial', sans-serif; }
.bills-detail-table th { background: #18224b; color: white; padding: 10px 12px; font-size: 13px; text-align: left; }
.bills-detail-table td { padding: 10px 12px; border-bottom: 1px solid #e0e0e0; font-size: 13px; }

