    #jobModalBody .bills-detail-table tbody {
        display: table-row-group !important; visibility: visible !important;
    }
    #jobModalBody .bills-detail-table tr {
        display: table-row !important; visibility: visible !important;
    }
    #jobModalBody .bills-detail-table th,
    #jobModalBody .bills-detail-table td {
        display: table-cell !important; visibility: visible !important;
        padding: 3px 5px !important; font-size: 7pt !important;
