<script>
var currentPage = 1;
var totalPages = 1;
var totalRecords = 0;
var isLoadingMore = false;
var searchTimeout = null;
var allActiveFilters = {};
var selectedCsvFile = null;

// UPDATED columnMapping - column 26 now maps to created_by_name
var columnMapping = {
    0: 'job_number', 1: 'job_date', 2: 'original_documents_date',
    3: 'bonded_carrier', 4: 'do_collected_date', 5: 'customer_name',
    6: 'consignee', 7: 'bl_number', 8: 'container_number', 9: 'container_size',
    10: 'vessel_name', 11: 'vessel_arrival_date', 12: 'description',
    13: 'free_till', 14: 'port_of_loading', 15: 'port_of_discharge', 16: 'dry_port', 17: 'shipping_line',
    18: 'freight_forwarder_name', 19: 'depositor', 20: 'free_time',
    21: 'detention_tariff', 22: 'soc', 23: 'mobile_no', 24: 'mbl_number', 25: 'remarks', 26: 'status',
    27: 'created_by_name'
};

document.addEventListener('DOMContentLoaded', function() {
    loadJobs(true);
    initColumnFilters();
    initCsvDragDrop();
    initColumnResizing();
    initJobsSorting();
    
    document.addEventListener('click', function(e) {
        if (e.target && e.target.id === 'reloadAfterCsvBtn') {
            loadJobs(true);
            closeCsvUploadModal();
        }
    });
});

function initJobsSorting() {
    var headers = document.querySelectorAll('#jobsTable th.sortable');
    var currentSortColumn = null;
    var currentSortDirection = 'asc';
    
    headers.forEach(function(header) {
        header.addEventListener('click', function(e) {
            if(e.target.classList && (e.target.classList.contains('col-filter') || e.target.classList.contains('resize-handle'))) return;
            
            var column = parseInt(this.dataset.column);
            var table = this.closest('#jobsTable');
            var tbody = table.querySelector('tbody');
            var rows = Array.from(tbody.querySelectorAll('tr'));
            
            if (rows.length === 1 && rows[0].querySelector('td[colspan]')) return;
            
            headers.forEach(function(h) { h.classList.remove('asc', 'desc'); });
            
            if (currentSortColumn === column) {
                currentSortDirection = currentSortDirection === 'asc' ? 'desc' : 'asc';
            } else {
                currentSortColumn = column;
                currentSortDirection = 'asc';
            }
            
            this.classList.add(currentSortDirection);
            
            rows.sort(function(a, b) {
                var aValue = a.children[column] ? a.children[column].innerText.trim() : '';
                var bValue = b.children[column] ? b.children[column].innerText.trim() : '';
                
                var aNum = parseFloat(aValue.replace(/[^0-9.-]/g, ''));
                var bNum = parseFloat(bValue.replace(/[^0-9.-]/g, ''));
                
                if (!isNaN(aNum) && !isNaN(bNum)) {
                    return currentSortDirection === 'asc' ? aNum - bNum : bNum - aNum;
                }
                
                aValue = aValue.toLowerCase();
                bValue = bValue.toLowerCase();
                
                if (currentSortDirection === 'asc') {
                    return aValue.localeCompare(bValue);
                } else {
                    return bValue.localeCompare(aValue);
                }
            });
            
            rows.forEach(function(row) { tbody.appendChild(row); });
        });
    });
}

function initColumnResizing() {
    var table = document.getElementById('jobsTable');
    if (!table) return;
    
    var resizeHandles = table.querySelectorAll('.resize-handle');
    
    var currentHandle = null;
    var currentTh = null;
    var startX = 0;
    var startWidth = 0;
    
    resizeHandles.forEach(function(handle) {
        handle.addEventListener('mousedown', function(e) {
            e.preventDefault();
            e.stopPropagation();
            
            currentHandle = handle;
            currentHandle.classList.add('active');
            currentTh = handle.parentElement;
            startX = e.clientX;
            startWidth = currentTh.offsetWidth;
            
            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
            document.body.style.cursor = 'col-resize';
            document.body.style.userSelect = 'none';
        });
    });
    
    function onMouseMove(e) {
        if (!currentHandle || !currentTh) return;
        
        var diffX = e.clientX - startX;
        var newWidth = startWidth + diffX;
        
        if (newWidth < 50) newWidth = 50;
        if (newWidth > 500) newWidth = 500;
        
        currentTh.style.width = newWidth + 'px';
        currentTh.style.minWidth = newWidth + 'px';
    }
    
    function onMouseUp() {
        if (currentHandle) {
            currentHandle.classList.remove('active');
        }
        currentHandle = null;
        currentTh = null;
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
    }
}

function loadJobs(isInitial) {
    if(isInitial === undefined) isInitial = false;
    
    var globalSearch = document.getElementById('globalSearchInput').value.trim();
    var startDate = document.getElementById('job_start_date').value;
    var endDate = document.getElementById('job_end_date').value;
    var year = document.getElementById('job_year_filter').value;
    
    if(isInitial) {
        currentPage = 1;
        document.getElementById('jobsTableBody').innerHTML = '';
        document.getElementById('initialLoading').style.display = 'block';
        document.getElementById('loadMoreBtn').style.display = 'none';
        document.getElementById('noMoreJobs').style.display = 'none';
        document.getElementById('showingCount').textContent = '0';
        document.getElementById('totalRecordsCount').textContent = '0';
        document.getElementById('totalJobsCount').textContent = '0';
    } else {
        document.getElementById('loadMoreBtn').style.display = 'none';
        document.getElementById('loadingSpinner').style.display = 'block';
    }
    
    isLoadingMore = true;
    
    var params = 'page_num=' + currentPage;
    params += '&sort_column=job_number&sort_order=DESC';
    
    var filterString = '';
    var filterCount = 0;
    for(var col in allActiveFilters) {
        if(allActiveFilters[col]) {
            filterString += (filterCount > 0 ? '|' : '') + columnMapping[col] + ':' + allActiveFilters[col];
            filterCount++;
        }
    }
    
    if(filterString) params += '&column_filters=' + encodeURIComponent(filterString);
    if(globalSearch) params += '&search=' + encodeURIComponent(globalSearch);
    if(startDate) params += '&start_date=' + startDate;
    if(endDate) params += '&end_date=' + endDate;
    if(year) params += '&year=' + year;
    
    console.log('Loading jobs with params:', params);
    
    fetch('system.php?page=search-jobs&' + params)
        .then(response => response.json())
        .then(data => {
            console.log('Jobs response:', data);
            
            if(data.success) {
                if(isInitial) {
                    document.getElementById('initialLoading').style.display = 'none';
                    document.getElementById('jobsTableBody').innerHTML = '';
                }
                
                var globalSearchTerm = document.getElementById('globalSearchInput').value.trim();
                
                if(data.jobs && data.jobs.length > 0) {
                    data.jobs.sort(function(a, b) {
                        var numA = parseInt(a.job_number);
                        var numB = parseInt(b.job_number);
                        if (!isNaN(numA) && !isNaN(numB)) {
                            return numB - numA;
                        }
                        return (b.job_number || '').localeCompare(a.job_number || '');
                    });
                }
                
                if(data.jobs.length > 0) {
                    data.jobs.forEach(function(job) {
                        var row = createJobRow(job, globalSearchTerm);
                        document.getElementById('jobsTableBody').appendChild(row);
                    });
                    
                    currentPage = data.current_page;
                    totalPages = data.total_pages;
                    totalRecords = data.total_records;
                    
                    document.getElementById('showingCount').textContent = document.querySelectorAll('#jobsTableBody tr').length;
                    document.getElementById('totalRecordsCount').textContent = totalRecords;
                    document.getElementById('totalJobsCount').textContent = totalRecords;
                    
                    if(currentPage < totalPages) {
                        document.getElementById('loadMoreBtn').style.display = 'inline-flex';
                        document.getElementById('noMoreJobs').style.display = 'none';
                    } else {
                        document.getElementById('loadMoreBtn').style.display = 'none';
                        document.getElementById('noMoreJobs').style.display = 'block';
                    }
                    
                    updateSearchInfo();
                    
                } else if(isInitial) {
                    document.getElementById('initialLoading').style.display = 'none';
                    document.getElementById('jobsTableBody').innerHTML = 
                        '<tr><td colspan="28" style="text-align:center; padding:60px;">' +
                        '<i class="fas fa-search" style="font-size:48px; color:#ff9800;"></i>' +
                        '<p style="margin-top:10px; color:#666;">No jobs found matching your filter.</p>' +
                        '</td></tr>';
                    document.getElementById('showingCount').textContent = '0';
                    document.getElementById('totalRecordsCount').textContent = '0';
                    document.getElementById('totalJobsCount').textContent = '0';
                    updateSearchInfo();
                }
            } else {
                console.error('API returned success=false:', data);
                document.getElementById('initialLoading').style.display = 'none';
                document.getElementById('jobsTableBody').innerHTML = 
                    '<tr><td colspan="28" style="text-align:center; padding:60px;">' +
                    '<i class="fas fa-exclamation-triangle" style="font-size:48px; color:#f44336;"></i>' +
                    '<p style="margin-top:10px; color:#666;">Error loading jobs. Please try refreshing the page.</p>' +
                    '</td></tr>';
            }
            
            document.getElementById('loadingSpinner').style.display = 'none';
            isLoadingMore = false;
        })
        .catch(error => {
            console.error('Fetch Error:', error);
            document.getElementById('loadingSpinner').style.display = 'none';
            document.getElementById('initialLoading').style.display = 'none';
            document.getElementById('jobsTableBody').innerHTML = 
                '<tr><td colspan="28" style="text-align:center; padding:60px;">' +
                '<i class="fas fa-exclamation-triangle" style="font-size:48px; color:#f44336;"></i>' +
                '<p style="margin-top:10px; color:#666;">Network error. Please check your connection and try again.</p>' +
                '</td></tr>';
            isLoadingMore = false;
        });
}

function initColumnFilters() {
    var filters = document.querySelectorAll('.col-filter');
    filters.forEach(function(filter) {
        filter.addEventListener('input', function() {
            var colIndex = parseInt(this.dataset.col);
            var filterValue = this.value.trim();
            
            if(filterValue === '') {
                delete allActiveFilters[colIndex];
                this.classList.remove('active-filter');
            } else {
                allActiveFilters[colIndex] = filterValue;
                this.classList.add('active-filter');
            }
            
            clearTimeout(filter._timeout);
            filter._timeout = setTimeout(function() {
                loadJobs(true);
            }, 400);
        });
    });
}

function updateSearchInfo() {
    var globalSearch = document.getElementById('globalSearchInput').value.trim();
    var totalFilters = Object.keys(allActiveFilters).length;
    
    if(globalSearch || totalFilters > 0) {
        document.getElementById('searchInfoBar').style.display = 'flex';
        
        var termText = '';
        if(globalSearch && totalFilters > 0) {
            termText = '"' + globalSearch + '" + ' + totalFilters + ' column filter(s)';
        } else if(globalSearch) {
            termText = '"' + globalSearch + '"';
        } else {
            termText = totalFilters + ' column filter(s) active';
        }
        document.getElementById('searchTermDisplay').textContent = termText;
        document.getElementById('searchCountDisplay').textContent = totalRecords;
    } else {
        document.getElementById('searchInfoBar').style.display = 'none';
    }
}

function debounceGlobalSearch() {
    clearTimeout(searchTimeout);
    searchTimeout = setTimeout(function() {
        loadJobs(true);
    }, 500);
}

function clearSearch() {
    document.getElementById('globalSearchInput').value = '';
    document.querySelectorAll('.col-filter').forEach(function(f) {
        f.value = '';
        f.classList.remove('active-filter');
    });
    allActiveFilters = {};
    loadJobs(true);
}

function loadMoreJobs() {
    if(!isLoadingMore && currentPage < totalPages) {
        currentPage++;
        loadJobs(false);
    }
}

function applyDateFilters() { loadJobs(true); }

function clearAllFilters() {
    document.getElementById('job_start_date').value = '';
    document.getElementById('job_end_date').value = '';
    document.getElementById('job_year_filter').value = '';
    document.getElementById('globalSearchInput').value = '';
    document.querySelectorAll('.col-filter').forEach(function(f) {
        f.value = '';
        f.classList.remove('active-filter');
    });
    allActiveFilters = {};
    loadJobs(true);
}

// UPDATED createJobRow - now displays created_by_name instead of created_by
function createJobRow(job, searchTerm) {
    var tr = document.createElement('tr');
    tr.setAttribute('ondblclick', 'showJobWithBills(' + job.id + ')');
    tr.setAttribute('data-job-id', job.id);
    tr.style.cursor = 'pointer';
    
    var socClass = (job.soc == 'Yes') ? 'active' : 'cancelled';
    
    tr.innerHTML = 
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;"><strong>' + highlightText(job.job_number || '', searchTerm) + '</strong></td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.job_date ? formatDateStr(job.job_date) : '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.original_documents_date ? formatDateStr(job.original_documents_date) : '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.bonded_carrier || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.do_collected_date || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.customer_name || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.consignee || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.bl_number || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.container_number || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.container_size || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.vessel_name || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.vessel_arrival_date ? formatDateStr(job.vessel_arrival_date) : '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;" title="' + escapeHtml(job.description || '-') + '">' + highlightText((job.description || '-').substring(0, 50), searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.free_till || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.port_of_loading || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.port_of_discharge || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.dry_port || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.shipping_line || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.freight_forwarder_name || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.depositor || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.free_time || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.detention_tariff || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;"><span class="status-badge ' + socClass + '">' + highlightText(job.soc || 'No', searchTerm) + '</span></td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.mobile_no || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.mbl_number || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.remarks || '-', searchTerm) + '</td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;"><span class="status-badge ' + (job.status || 'active') + '">' + highlightText(job.status || 'active', searchTerm) + '</span></td>' +
        '<td style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">' + highlightText(job.created_by_name || '-', searchTerm) + '</td>' +
        '<td class="action-cell" style="padding: 8px 6px; border-bottom: 1px solid #e8eaed; white-space: nowrap; text-align: center;">' +
            '<button class="btn-info btn-sm" onclick="event.stopPropagation(); showJobWithBills(' + job.id + ')" title="View Details"><i class="fas fa-eye"></i></button> ' +
            '<button class="btn-warning btn-sm" onclick="event.stopPropagation(); editJob(' + job.id + ')" title="Edit Job"><i class="fas fa-edit"></i></button> ' +
            '<button class="btn-danger btn-sm" onclick="event.stopPropagation(); deleteJob(' + job.id + ')" title="Delete Job"><i class="fas fa-trash"></i></button> ' +
            '<button class="btn-primary btn-sm" onclick="event.stopPropagation(); checkAndCreateBill(' + job.id + ')" title="Create Bill"><i class="fas fa-file-invoice"></i></button>' +
        '</td>';
    
    return tr;
}

function highlightText(text, searchTerm) {
    if(!text) return '';
    if(!searchTerm) return escapeHtml(text);
    var escapedText = escapeHtml(text);
    var escapedSearch = searchTerm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    var regex = new RegExp('(' + escapedSearch + ')', 'gi');
    return escapedText.replace(regex, '<span class="search-highlight">$1</span>');
}

function formatDateStr(dateStr) {
    if(!dateStr) return '-';
    var d = new Date(dateStr);
    if(isNaN(d.getTime())) return dateStr;
    var day = d.getDate(); var month = d.getMonth() + 1; var year = d.getFullYear();
    return (day < 10 ? '0' : '') + day + '-' + (month < 10 ? '0' : '') + month + '-' + year;
}

function formatDateTimeStr(dateStr) {
    if(!dateStr) return '-';
    var d = new Date(dateStr);
    if(isNaN(d.getTime())) return dateStr;
    var day = d.getDate(); var month = d.getMonth() + 1; var year = d.getFullYear();
    var hours = d.getHours(); var minutes = d.getMinutes(); var ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12; hours = hours ? hours : 12;
    minutes = minutes < 10 ? '0' + minutes : minutes;
    return (day < 10 ? '0' : '') + day + '-' + (month < 10 ? '0' : '') + month + '-' + year + ' ' + hours + ':' + minutes + ' ' + ampm;
}

function escapeHtml(text) {
    if(!text) return '';
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
}

function openCsvUploadModal() {
    document.getElementById('csvUploadModal').style.display = 'flex';
    resetCsvUploadForm();
}

function closeCsvUploadModal() {
    document.getElementById('csvUploadModal').style.display = 'none';
    resetCsvUploadForm();
}

function resetCsvUploadForm() {
    document.getElementById('csvFileInput').value = '';
    document.getElementById('csvFileName').textContent = '';
    document.getElementById('csvUploadProgress').style.display = 'none';
    document.getElementById('csvProgressBar').style.width = '0%';
    document.getElementById('csvUploadStatus').textContent = '';
    document.getElementById('csvUploadResult').style.display = 'none';
    document.getElementById('csvUploadResult').innerHTML = '';
    document.getElementById('uploadCsvBtn').disabled = false;
    selectedCsvFile = null;
}

function handleCsvFileSelect(event) {
    var file = event.target.files[0];
    if (file) {
        if (!file.name.toLowerCase().endsWith('.csv')) {
            alert('Please select a CSV file only!');
            resetCsvUploadForm();
            return;
        }
        selectedCsvFile = file;
        document.getElementById('csvFileName').textContent = 'Selected: ' + file.name + ' (' + formatFileSize(file.size) + ')';
    }
}

function initCsvDragDrop() {
    var dropArea = document.getElementById('csvDropArea');
    if (!dropArea) return;
    
    ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(function(eventName) {
        dropArea.addEventListener(eventName, function(e) {
            e.preventDefault();
            e.stopPropagation();
        });
    });
    
    dropArea.addEventListener('dragenter', function() { 
        this.style.borderColor = '#2e7d32'; 
        this.style.background = '#e8f5e9'; 
    });
    
    dropArea.addEventListener('dragleave', function() { 
        this.style.borderColor = '#4caf50'; 
        this.style.background = ''; 
    });
    
    dropArea.addEventListener('drop', function(e) {
        this.style.borderColor = '#4caf50';
        this.style.background = '';
        var files = e.dataTransfer.files;
        if (files.length > 0) {
            var file = files[0];
            if (file.name.toLowerCase().endsWith('.csv')) {
                document.getElementById('csvFileInput').files = files;
                handleCsvFileSelect({target: {files: [file]}});
            } else {
                alert('Please drop a CSV file only!');
            }
        }
    });
}

function formatFileSize(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / 1048576).toFixed(1) + ' MB';
}

function downloadCsvTemplate() {
    var csvContent = "job_number,job_date,original_documents_date,bonded_carrier,do_collected_date,customer_name,consignee,bl_number,container_number,container_size,vessel_name,vessel_arrival_date,description,free_till,port_of_loading,port_of_discharge,dry_port,shipping_line,freight_forwarder_name,depositor,free_time,detention_tariff,soc,mobile_no,mbl_number,status,remarks\n";
    csvContent += "AUTO,2024-01-10,2024-01-12,Sample Carrier,2024-01-14,Sample Customer,Sample Consignee,BL123456,CONT987654,20ft,Sample Vessel,2024-01-15,Sample goods description,7 days free,Shanghai,Karachi,Lahore,Maersk Line,Sample Forwarder,Sample Depositor,7,$50/day,Yes,0300-1234567,MBL-001234,active,Sample remarks\n";
    
    var blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    var link = document.createElement('a');
    var url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', 'jobs_template.csv');
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

function uploadCsvFile() {
    if (!selectedCsvFile) {
        alert('Please select a CSV file first!');
        return;
    }
    
    var formData = new FormData();
    formData.append('csv_file', selectedCsvFile);
    
    document.getElementById('csvUploadProgress').style.display = 'block';
    document.getElementById('csvUploadResult').style.display = 'none';
    document.getElementById('uploadCsvBtn').disabled = true;
    
    var xhr = new XMLHttpRequest();
    xhr.open('POST', 'system.php?page=import-jobs-csv', true);
    
    xhr.upload.onprogress = function(e) {
        if (e.lengthComputable) {
            var percentComplete = Math.round((e.loaded / e.total) * 100);
            document.getElementById('csvProgressBar').style.width = percentComplete + '%';
            document.getElementById('csvUploadStatus').textContent = 'Uploading: ' + percentComplete + '%';
        }
    };
    
    xhr.onload = function() {
        document.getElementById('csvProgressBar').style.width = '100%';
        document.getElementById('csvUploadStatus').textContent = 'Processing...';
        
        console.log('Server Response:', xhr.responseText);
        
        var response;
        try {
            response = JSON.parse(xhr.responseText);
        } catch(e) {
            console.error('JSON Parse Error:', e);
            
            document.getElementById('csvUploadResult').innerHTML = 
                '<div style="background:#fff3e0; padding:15px; border-radius:8px; border-left:4px solid #ff9800;">' +
                '<strong><i class="fas fa-exclamation-triangle"></i> Server Error!</strong><br><br>' +
                '<p style="color:#e65100;">Server returned invalid response. Check PHP error log.</p>' +
                '<details style="margin-top:10px;">' +
                '<summary style="cursor:pointer; color:#ff9800; font-weight:600;">Click to see raw response</summary>' +
                '<div style="background:#fff; padding:10px; border:1px solid #ddd; border-radius:4px; max-height:300px; overflow-y:auto; font-family:monospace; font-size:11px; white-space:pre-wrap; word-break:break-all; margin-top:8px;">' +
                escapeHtml(xhr.responseText.substring(0, 3000)) +
                '</div></details></div>';
            
            document.getElementById('csvUploadResult').style.display = 'block';
            document.getElementById('csvUploadStatus').textContent = 'Error';
            document.getElementById('uploadCsvBtn').disabled = false;
            return;
        }
        
        if (response.success) {
            var resultHtml = 
                '<div style="background:#e8f5e9; padding:15px; border-radius:8px; border-left:4px solid #4caf50;">' +
                '<strong><i class="fas fa-check-circle"></i> Import Successful!</strong><br><br>' +
                '<table style="width:100%; font-size:13px;">' +
                '<tr><td><strong>Total rows:</strong></td><td>' + (response.total_rows || 0) + '</td></tr>' +
                '<tr><td><strong>Imported:</strong></td><td style="color:#4caf50; font-weight:bold;">' + (response.imported || 0) + ' jobs</td></tr>' +
                '<tr><td><strong>Skipped:</strong></td><td style="color:#ff9800;">' + (response.skipped || 0) + '</td></tr>';
            
            if (response.errors && response.errors > 0) {
                resultHtml += '<tr><td><strong>Errors:</strong></td><td style="color:#f44336;">' + response.errors + '</td></tr>';
            }
            
            resultHtml += '</table>';
            
            if (response.error_details && response.error_details.length > 0) {
                resultHtml += '<br><strong style="color:#f44336;">Error Details:</strong><br>';
                resultHtml += '<div style="max-height:150px; overflow-y:auto; font-size:12px; background:#fff3e0; padding:10px; border-radius:4px; margin-top:5px;">';
                response.error_details.forEach(function(err) {
                    resultHtml += '• ' + escapeHtml(String(err)) + '<br>';
                });
                resultHtml += '</div>';
            }
            
            resultHtml += '<br><button onclick="loadJobs(true); closeCsvUploadModal();" style="background:#8e181e; color:white; border:none; padding:10px 20px; border-radius:6px; cursor:pointer; font-size:14px; width:100%; margin-top:10px;"><i class="fas fa-sync-alt"></i> Refresh Jobs Table & Close</button>';
            
            resultHtml += '</div>';
            
            document.getElementById('csvUploadResult').innerHTML = resultHtml;
            document.getElementById('csvUploadStatus').textContent = 'Import complete! ' + (response.imported || 0) + ' jobs imported.';
            
            setTimeout(function() {
                console.log('Auto-reloading jobs after CSV import...');
                loadJobs(true);
            }, 500);
            
        } else {
            var errorHtml = 
                '<div style="background:#ffebee; padding:15px; border-radius:8px; border-left:4px solid #f44336;">' +
                '<strong><i class="fas fa-times-circle"></i> Import Failed!</strong><br><br>' +
                '<strong>Error:</strong> ' + escapeHtml(response.message || 'Unknown error');
            
            if (response.error_details && response.error_details.length > 0) {
                errorHtml += '<br><br><strong>Details:</strong><br>';
                errorHtml += '<div style="max-height:150px; overflow-y:auto; font-size:12px; background:#ffcdd2; padding:10px; border-radius:4px; margin-top:5px;">';
                response.error_details.forEach(function(err) {
                    errorHtml += '• ' + escapeHtml(String(err)) + '<br>';
                });
                errorHtml += '</div>';
            }
            
            errorHtml += '</div>';
            
            document.getElementById('csvUploadResult').innerHTML = errorHtml;
            document.getElementById('csvUploadStatus').textContent = 'Import failed';
        }
        
        document.getElementById('csvUploadResult').style.display = 'block';
        document.getElementById('uploadCsvBtn').disabled = false;
    };
    
    xhr.onerror = function() {
        document.getElementById('csvUploadResult').innerHTML = 
            '<div style="background:#ffebee; padding:15px; border-radius:8px; border-left:4px solid #f44336;">' +
            '<strong><i class="fas fa-times-circle"></i> Network Error</strong><br><br>' +
            '<p>Could not connect to server.</p></div>';
        document.getElementById('csvUploadResult').style.display = 'block';
        document.getElementById('csvUploadStatus').textContent = 'Network error';
        document.getElementById('uploadCsvBtn').disabled = false;
    };
    
    xhr.send(formData);
}

function exportJobs(type) {
    var startDate = document.getElementById('job_start_date').value;
    var endDate = document.getElementById('job_end_date').value;
    if(!startDate || !endDate) { alert('Please select date range first'); return; }
    var form = document.createElement('form');
    form.method = 'POST'; form.action = 'system.php?page=export-jobs-batch';
    form.innerHTML = '<input type="hidden" name="start_date" value="'+startDate+'"><input type="hidden" name="end_date" value="'+endDate+'"><input type="hidden" name="export_type" value="'+type+'">';
    document.body.appendChild(form); form.submit(); document.body.removeChild(form);
}

function exportJobsFolder() {
    var startDate = document.getElementById('job_start_date').value;
    var endDate = document.getElementById('job_end_date').value;
    if(!startDate || !endDate) { alert('Please select date range first'); return; }
