        fetch('system.php?page=get-job-bills&job_id=' + jobId).then(r => r.json()).then(data => {
            let html = '<div style="display:grid; grid-template-columns:repeat(2,1fr); gap:15px;">';
            
            html += '<div><strong>Job Number:</strong><br>' + escapeHtml(job.job_number || '-') + '</div>';
            html += '<div><strong>Job Creation Dt:</strong><br>' + (job.job_date ? formatDateStr(job.job_date) : '-') + '</div>';
            html += '<div><strong>Original Documents Received On:</strong><br>' + (job.original_documents_date ? formatDateStr(job.original_documents_date) : '-') + '</div>';
            html += '<div><strong>D/O Collected On:</strong><br>' + escapeHtml(job.do_collected_date || '-') + '</div>';
            html += '<div><strong>Customer Name:</strong><br>' + escapeHtml(job.customer_name || '-') + '</div>';
            html += '<div><strong>Consignee:</strong><br>' + escapeHtml(job.consignee || '-') + '</div>';
            html += '<div><strong>BL Number:</strong><br>' + escapeHtml(job.bl_number || '-') + '</div>';
            html += '<div><strong>Container Number:</strong><br>' + escapeHtml(job.container_number || '-') + '</div>';
            html += '<div><strong>Container Size:</strong><br>' + escapeHtml(job.container_size || '-') + '</div>';
            html += '<div><strong>Port of Discharge:</strong><br>' + escapeHtml(job.port_of_discharge || '-') + '</div>';
            html += '<div><strong>Dry Port:</strong><br>' + escapeHtml(job.dry_port || '-') + '</div>';
            html += '<div><strong>Port of Loading:</strong><br>' + escapeHtml(job.port_of_loading || '-') + '</div>';
            html += '<div><strong>SOC:</strong><br>' + escapeHtml(job.soc || 'No') + '</div>';
            html += '<div><strong>Vessel Name:</strong><br>' + escapeHtml(job.vessel_name || '-') + '</div>';
            html += '<div><strong>Vessel Arrival Date:</strong><br>' + (job.vessel_arrival_date ? formatDateStr(job.vessel_arrival_date) : '-') + '</div>';
            html += '<div><strong>Description:</strong><br>' + escapeHtml(job.description || '-') + '</div>';
            html += '<div><strong>Free till:</strong><br>' + escapeHtml(job.free_till || '-') + '</div>';
            html += '<div><strong>Shipping Line:</strong><br>' + escapeHtml(job.shipping_line || '-') + '</div>';
            html += '<div><strong>Freight Forwarder Name:</strong><br>' + escapeHtml(job.freight_forwarder_name || '-') + '</div>';
            html += '<div><strong>Depositor:</strong><br>' + escapeHtml(job.depositor || '-') + '</div>';
            html += '<div><strong>Detention Free Period:</strong><br>' + escapeHtml(job.free_time || '-') + '</div>';
            html += '<div><strong>Detention Tariff:</strong><br>' + escapeHtml(job.detention_tariff || '-') + '</div>';
            html += '<div><strong>Mobile No:</strong><br>' + escapeHtml(job.mobile_no || '-') + '</div>';
            html += '<div><strong>MBL#:</strong><br>' + escapeHtml(job.mbl_number || '-') + '</div>';
            html += '<div><strong>Description:</strong><br>' + escapeHtml(job.description || '-') + '</div>';
            html += '<div><strong>Bonded Carrier Name:</strong><br>' + escapeHtml(job.bonded_carrier || '-') + '</div>';
            html += '<div><strong>Status:</strong><br><span class="status-badge ' + (job.status || 'active') + '">' + escapeHtml(job.status || 'active') + '</span></div>';
            
            html += '<div style="grid-column: 1 / -1; background:#f9f9f9; padding:12px; border-radius:8px; border:1px solid #e0e0e0;">';
            html += '<strong style="color:#8e181e;"><i class="fas fa-sticky-note"></i> Remarks:</strong><br>';
            html += '<span style="font-size:14px;">' + escapeHtml(job.remarks || 'No remarks') + '</span>';
            html += '</div>';
            
            html += '</div>';
            
            if (data && data.bills && data.bills.length > 0) {
                html += '<div style="margin-top:20px; border-top:2px solid #e0e0e0; padding-top:15px;">';
                html += '<h4 style="color:#8e181e;"><i class="fas fa-file-invoice"></i> Bills (' + data.bills.length + ')</h4>';
                html += '<div style="overflow-x:auto;">';
                html += '<table class="bills-detail-table" style="width:100%; border-collapse:collapse; margin-top:10px;">';
                html += '<thead><tr style="background:#18224b; color:white;">';
                html += '<th style="padding:10px 12px; border:1px solid #2c3a6b;">Bill #</th>';
                html += '<th style="padding:10px 12px; border:1px solid #2c3a6b;">Bill Type</th>';
                html += '<th style="padding:10px 12px; border:1px solid #2c3a6b;">Customer Name</th>';
                html += '<th style="padding:10px 12px; border:1px solid #2c3a6b;">Amount</th>';
                html += '<th style="padding:10px 12px; border:1px solid #2c3a6b;">Creation Date & Time</th>';
                html += '</tr></thead><tbody>';
                
                for (let i = 0; i < data.bills.length; i++) {
                    let bill = data.bills[i];
                    let billAmount = bill.total_amount || bill.amount || '0';
                    let billType = bill.bill_type || '-';
                    let billCustomer = job.customer_name || '-';
                    let billCreatedAt = bill.created_at || bill.creation_date || bill.bill_date || null;
                    
                    html += '<tr style="' + (i % 2 === 0 ? 'background:#fafafa;' : 'background:white;') + '">';
                    html += '<td style="padding:10px 12px; border:1px solid #e0e0e0;">' + escapeHtml(bill.bill_number || '-') + '</td>';
                    html += '<td style="padding:10px 12px; border:1px solid #e0e0e0;">' + escapeHtml(billType) + '</td>';
                    html += '<td style="padding:10px 12px; border:1px solid #e0e0e0;">' + escapeHtml(billCustomer) + '</td>';
                    html += '<td style="padding:10px 12px; border:1px solid #e0e0e0;">' + escapeHtml(String(billAmount)) + '</td>';
                    html += '<td style="padding:10px 12px; border:1px solid #e0e0e0;">' + (billCreatedAt ? formatDateTimeStr(billCreatedAt) : '-') + '</td>';
                    html += '</tr>';
                }
                html += '</tbody></table></div></div>';
            } else {
                html += '<div style="margin-top:20px; border-top:2px solid #e0e0e0; padding-top:15px; text-align:center; color:#666;">';
                html += '<i class="fas fa-info-circle"></i> No bills found for this job.';
                html += '</div>';
            }
            
            document.getElementById('jobModalBody').innerHTML = html;
            document.getElementById('jobModal').style.display = 'flex';
        }).catch(err => {
            console.error('Bills fetch error:', err);
            showJobBasicInfo(job);
        });
    }).catch(err => {
        console.error('Job fetch error:', err);
        alert('Error loading job details. Please try again.');
    });
}

function showJobBasicInfo(job) {
    let html = '<div style="display:grid; grid-template-columns:repeat(2,1fr); gap:15px;">';
    html += '<div><strong>Job Number:</strong><br>' + escapeHtml(job.job_number || '-') + '</div>';
    html += '<div><strong>Job Creation Dt:</strong><br>' + (job.job_date ? formatDateStr(job.job_date) : '-') + '</div>';
    html += '<div><strong>Customer Name:</strong><br>' + escapeHtml(job.customer_name || '-') + '</div>';
    html += '<div><strong>Consignee:</strong><br>' + escapeHtml(job.consignee || '-') + '</div>';
    html += '<div><strong>BL Number:</strong><br>' + escapeHtml(job.bl_number || '-') + '</div>';
    html += '<div><strong>Container Number:</strong><br>' + escapeHtml(job.container_number || '-') + '</div>';
    html += '<div><strong>Status:</strong><br><span class="status-badge ' + (job.status || 'active') + '">' + escapeHtml(job.status || 'active') + '</span></div>';
    html += '</div>';
    html += '<div style="margin-top:20px; border-top:2px solid #e0e0e0; padding-top:15px; text-align:center; color:#f44336;">';
    html += '<i class="fas fa-exclamation-circle"></i> Could not load bills. Please try again.';
    html += '</div>';
    document.getElementById('jobModalBody').innerHTML = html;
    document.getElementById('jobModal').style.display = 'flex';
}

