function deleteJob(id) { 
    if(confirm('Delete this job and all its bills?')) { 
        window.location.href = 'system.php?page=delete-job&id=' + id; 
    } 
}

function checkAndCreateBill(jobId) { 
    fetch('system.php?page=check-existing-bills&job_id=' + jobId).then(r => r.json()).then(data => { 
        if(data.has_bills) { 
            console.log(data.bills);
            pendingJobId = jobId; 
            let billsHtml = '<p>This job already has bills.</p><ul>'; 
            for(let i = 0; i < data.bills.length; i++) { 
                billsHtml += '<li>' + escapeHtml(data.bills[i].bill_number) + ' (' + escapeHtml(data.bills[i].bill_type) + ')</li>'; 
            } 
            billsHtml += '</ul><p>Create another?</p>'; 
            document.getElementById('existingBillsBody').innerHTML = billsHtml; 
            document.getElementById('existingBillsModal').style.display = 'flex'; 
        } else { 
            window.location.href = 'system.php?page=create-bill&job_id=' + jobId; 
        } 
    }); 
}

var pendingJobId = null;
function proceedToCreateBill() { 
    if(pendingJobId) { 
        window.location.href = 'system.php?page=create-bill&job_id=' + pendingJobId; 
    } 
    closeExistingBillsModal(); 
}

function closeJobModal() { document.getElementById('jobModal').style.display = 'none'; }
function closeEditJobModal() { document.getElementById('editJobModal').style.display = 'none'; }
function closeExistingBillsModal() { document.getElementById('existingBillsModal').style.display = 'none'; }
function toggleUserDropdown() { document.getElementById('userDropdown').classList.toggle('show'); }
function openProfileModal() { document.getElementById('profileModal').style.display = 'flex'; document.getElementById('userDropdown').classList.remove('show'); }
function closeProfileModal() { document.getElementById('profileModal').style.display = 'none'; }

window.onclick = function(e) { 
    if(e.target.classList && e.target.classList.contains('modal')) { 
        e.target.style.display = 'none'; 
    } 
    if(!e.target.closest('.user-avatar') && !e.target.closest('.user-dropdown')) { 
        var dropdown = document.getElementById('userDropdown'); 
        if(dropdown) dropdown.classList.remove('show'); 
    } 
}

(function() {
    const sidebar = document.querySelector('.sidebar');
    const body = document.body;
    const toggleBtn = document.getElementById('sidebarToggleBtn');
    if(!sidebar || !toggleBtn) return;
    toggleBtn.addEventListener('click', function() {
        sidebar.classList.toggle('collapsed');
        if(sidebar.classList.contains('collapsed')) { 
            body.classList.add('sidebar-collapsed'); 
            document.cookie = "sidebar_collapsed=true; path=/"; 
        } else { 
            body.classList.remove('sidebar-collapsed'); 
            document.cookie = "sidebar_collapsed=false; path=/"; 
        }
    });
    if(document.cookie.indexOf('sidebar_collapsed=true') !== -1) { 
        sidebar.classList.add('collapsed'); 
        body.classList.add('sidebar-collapsed'); 
    }
})();


</script>

