// Get distinct D/O Collected values from 2026 jobs only
/**
 * Renders a searchable "combobox" form-group: single input, styled dropdown,
 * type-to-filter, free text if nothing matches. Replaces datalist + "_text" pairs.
 */
function renderCombobox(string $name, string $label, array $options, string $placeholder = '', bool $textarea = false): void {
    $options = array_values(array_filter(array_unique(array_map('trim', $options)), fn($v) => $v !== ''));
    sort($options);
    $id = 'combobox_' . $name;
    ?>
    <div class="form-group combobox" data-combobox="<?php echo htmlspecialchars($name); ?>">
        <label><?php echo htmlspecialchars($label); ?></label>
        <?php if ($textarea): ?>
            <textarea
                id="<?php echo $id; ?>_input"
                name="<?php echo htmlspecialchars($name); ?>"
                class="form-control combobox-input"
                rows="2"
                placeholder="<?php echo htmlspecialchars($placeholder); ?>"
                autocomplete="off"
            ></textarea>
        <?php else: ?>
            <input
                type="text"
                id="<?php echo $id; ?>_input"
                name="<?php echo htmlspecialchars($name); ?>"
                class="form-control combobox-input"
                placeholder="<?php echo htmlspecialchars($placeholder); ?>"
                autocomplete="off"
            >
        <?php endif; ?>
        <ul class="combobox-list is-hidden" id="<?php echo $id; ?>_list"></ul>
    </div>
    <script>
        (window.__comboboxData = window.__comboboxData || []).push({
            inputId: '<?php echo $id; ?>_input',
            listId: '<?php echo $id; ?>_list',
            options: <?php echo json_encode($options); ?>
        });
    </script>
    <?php
}
