<script>
var jobId = <?php echo $job_id; ?>;
var billItems = [];
var draggedRow = null;

// ============ EDITABLE LABEL FUNCTION ============
function makeEditable(element) {
    if(element.classList.contains('editing')) return;
    
    var currentText = element.innerText;
    var input = document.createElement('input');
    input.type = 'text';
    input.value = currentText;
    input.style.width = (currentText.length + 2) * 8 + 'px';
    input.style.minWidth = '100px';
    input.style.fontWeight = '600';
    input.style.fontSize = '14px';
    input.style.border = 'none';
    input.style.outline = 'none';
    input.style.background = 'transparent';
    input.style.padding = '0';
    
    element.innerHTML = '';
    element.appendChild(input);
    element.classList.add('editing');
    
    input.focus();
    input.select();
    
    function saveLabel() {
        var newText = input.value.trim();
        if(newText === '') newText = 'Advance Amount';
        element.innerHTML = newText;
        element.classList.remove('editing');
        document.getElementById('advanceLabelHidden').value = newText;
        console.log('Label saved to hidden field: ' + newText);
    }
    
    input.onblur = function() {
        saveLabel();
    };
    
    input.onkeypress = function(e) {
        if(e.key === 'Enter') {
            saveLabel();
        }
    };
}

// ============ FORM SUBMIT ============
document.getElementById('billForm').addEventListener('submit', function(e) {
    var labelSpan = document.querySelector('#advanceLabel .editable-label');
    if(labelSpan) {
        if(labelSpan.classList.contains('editing')) {
            var input = labelSpan.querySelector('input');
            if(input) {
                var newText = input.value.trim();
                if(newText === '') newText = 'Advance Amount';
                document.getElementById('advanceLabelHidden').value = newText;
                labelSpan.innerHTML = newText;
                labelSpan.classList.remove('editing');
            }
        } else {
            var currentLabelText = labelSpan.innerText || 'Advance Amount';
            document.getElementById('advanceLabelHidden').value = currentLabelText;
        }
    }
    console.log('Submitting label: ' + document.getElementById('advanceLabelHidden').value);
});

// ============ BILL HEADINGS (from Masters > Bill Headings) ============
// { forwarding: [{heading, receipt_status}, ...], detention: [...] } — active only, in sort order
var billHeadings = <?php echo json_encode($billHeadingDefs, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?>;
var allHeadings = [];
var currentBillType = null;

function getHeadingDef(heading) {
    var defs = billHeadings[currentBillType] || [];
    for (var i = 0; i < defs.length; i++) {
        if (defs[i].heading === heading) return defs[i];
    }
    return null;
}

// ============ INIT FUNCTION ============
function changeBillType() {
    var select = document.getElementById('bill_type');
    var type = select.value;
    var hasAmounts = billItems.some(item => String(item.amount || '').trim() !== '');
    if (currentBillType !== null && hasAmounts && !confirm('Changing the bill type will replace the current items and their amounts. Continue?')) {
        select.value = currentBillType;
        return;
    }
    currentBillType = type;

    var defs = billHeadings[type] || [];
    allHeadings = defs.map(d => d.heading);
    billItems = defs.map(d => ({
        heading: d.heading,
        status: d.receipt_status,
        amount: ''
    }));
    updateItemDropdown();
    renderTable();
}

function updateItemDropdown() {
    var sel = document.getElementById('itemSelect');
    var used = billItems.map(i => i.heading);
    var avail = allHeadings.filter(h => !used.includes(h));

    sel.innerHTML = '<option value="">-- Select Item Heading --</option>' +
                    '<option value="__new__">➕ Add New Item...</option>';
    avail.forEach(h => {
        sel.innerHTML += '<option value="' + escapeHtml(h) + '">' + escapeHtml(h) + '</option>';
    });
}

function handleItemSelectChange() {
    var sel = document.getElementById('itemSelect');
    var customInput = document.getElementById('customHeadingInput');
    if(sel.value === '__new__') {
        customInput.style.display = 'block';
        sel.style.display = 'none';
        customInput.focus();
    } else {
        customInput.style.display = 'none';
        sel.style.display = '';
        var def = getHeadingDef(sel.value);
        if (def) document.getElementById('receiptStatus').value = def.receipt_status;
    }
}

// ============ ADD ITEM FUNCTION ============
function addItem() {
    var sel = document.getElementById('itemSelect');
    var customInput = document.getElementById('customHeadingInput');
    var heading;

    if(sel.style.display === 'none' || sel.value === '__new__') {
        // One-off heading for this bill only; permanent headings are added in Masters > Bill Headings
        heading = customInput.value.trim();
        if(!heading) {
            alert('Please enter a custom heading!');
            return;
        }
        customInput.style.display = 'none';
        sel.style.display = '';
        sel.value = '';
        customInput.value = '';
    } else {
        heading = sel.value;
        if(!heading) {
            alert('Please select an item heading!');
            return;
        }
    }

    var status = document.getElementById('receiptStatus').value;
    var amount = document.getElementById('itemAmount').value;

    billItems.push({
        heading: heading,
        status: status,
        amount: amount
    });

    document.getElementById('itemAmount').value = '';

    updateItemDropdown();
    renderTable();
}

// ============ RENDER TABLE (UPDATED - amount input type="text" for any text support) ============
function renderTable() {
    var tbody = document.getElementById('itemsBody');
    
    if(billItems.length === 0) {
        tbody.innerHTML = '<tr class="empty-table-state"><td colspan="6"><i class="fas fa-inbox"></i><p>No items added yet</p></td></tr>';
        document.getElementById('itemCounter').textContent = '(0 items)';
        calcTotal();
        return;
    }
    
    document.getElementById('itemCounter').textContent = '(' + billItems.length + ' items)';
    tbody.innerHTML = billItems.map((item, i) => {
        console.log(item.status);
        return '<tr class="draggable-row" ' +
            'draggable="true" ' +
            'data-index="' + i + '" ' +
            'ondragstart="dragStart(event)" ' +
            'ondragend="dragEnd(event)" ' +
            'ondragover="dragOver(event)" ' +
            'ondrop="drop(event)">' +
            
            '<td class="drag-handle-cell">⋮⋮</td>' +
            '<td style="text-align:center;"><span class="row-number">' + (i+1) + '</span></td>' +
            '<td class="item-select-cell">' +
                '<select name="heading[]" onchange="updateHeading(' + i + ', this.value)" style="width:100%;">' +
                    getAllOptions(item.heading) +
                '</select>' +
            '</td>' +
            '<td class="item-select-cell">' +
                '<select name="receipt_status[]" onchange="updateStatus(' + i + ', this.value)">' +
                    '<option value="Receipted"' + (item.status === 'Receipted' ? ' selected' : '') + '>✅ Receipted</option>' +
                    '<option value="Unreceipted"' + (item.status === 'Unreceipted' ? ' selected' : '') + '>⏳ Unreceipted</option>' +
                '</select>' +
            '</td>' +
            '<td class="item-input-cell">' +
                '<input type="text" name="amount[]" value="' + escapeHtml(item.amount) + '" ' +
                'onchange="updateAmount(' + i + ', this.value)" ' +
                'oninput="updateAmount(' + i + ', this.value); calcTotal();" placeholder="0.00 or text" style="text-align:right;">' +
            '</td>' +
            '<td>' +
                '<button type="button" class="btn-delete-row" onclick="deleteItem(' + i + ')" title="Remove">' +
                    '<i class="fas fa-times"></i>' +
                '</button>' +
            '</td>' +
        '</tr>';
    }).join('');
    
    calcTotal();
}

function getAllOptions(selectedHeading) {
    // Keep one-off headings (not in the master list) selectable on their own row
    var options = allHeadings.includes(selectedHeading) ? allHeadings : [selectedHeading].concat(allHeadings);
    return options.map(h =>
        '<option value="' + escapeHtml(h) + '"' + (h === selectedHeading ? ' selected' : '') + '>' + escapeHtml(h) + '</option>'
    ).join('');
}

// ============ UPDATE FUNCTIONS ============
function updateHeading(index, value) {
    billItems[index].heading = value;
    updateItemDropdown();
}

function updateStatus(index, value) {
    billItems[index].status = value;
}

function updateAmount(index, value) {
    billItems[index].amount = value;
}

function deleteItem(index) {
    billItems.splice(index, 1);
    updateItemDropdown();
    renderTable();
}

// ============ DRAG & DROP ============
function dragStart(e) {
    var row = e.target.closest('.draggable-row');
    if(!row) return;
    draggedRow = row;
    row.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', row.dataset.index);
}

function dragEnd(e) {
    var row = e.target.closest('.draggable-row');
    if(row) row.classList.remove('dragging');
    document.querySelectorAll('.draggable-row').forEach(r => r.classList.remove('drag-over'));
    draggedRow = null;
}

function dragOver(e) {
    e.preventDefault();
    var row = e.target.closest('.draggable-row');
    if(row && row !== draggedRow) {
        row.classList.add('drag-over');
    }
}

function drop(e) {
    e.preventDefault();
    document.querySelectorAll('.draggable-row').forEach(r => r.classList.remove('drag-over'));
    
    var targetRow = e.target.closest('.draggable-row');
    if(!targetRow || !draggedRow || targetRow === draggedRow) return;
    
    var fromIndex = parseInt(draggedRow.dataset.index);
    var toIndex = parseInt(targetRow.dataset.index);
    
    var item = billItems.splice(fromIndex, 1)[0];
    billItems.splice(toIndex, 0, item);
    
    renderTable();
    draggedRow = null;
}

// ============ UPDATED: SIRF ALPHABET TEXT KO TOTAL MEIN IGNORE KARO ==========
function calcTotal() {
    var total = 0;
    document.querySelectorAll('#itemsBody input[name="amount[]"]').forEach(inp => {
        var val = inp.value.trim();
        // Check if value contains only alphabets and spaces
        if (/^[a-zA-Z\s]+$/.test(val)) {
            total += 0; // Text amounts don't add to total
        } else {
            total += parseFloat(val) || 0;
        }
    });
    document.getElementById('totalAmount').value = total.toFixed(2);
    calcBalance();
}
// ==========================================================================

function calcBalance() {
    var total = parseFloat(document.getElementById('totalAmount').value) || 0;
    var advance = parseFloat(document.getElementById('advanceAmount').value) || 0;
    var balance = total - advance;
    document.getElementById('balanceAmount').value = balance.toFixed(2);
    document.getElementById('balanceWords').value = numToWords(balance) + ' Rupees Only';
}

function numToWords(n) {
    if(n == 0) return 'Zero';
    var o = ['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];
    var t = ['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];
    function c(n) { if(n<20) return o[n]; if(n<100) return t[Math.floor(n/10)]+(n%10?' '+o[n%10]:''); if(n<1000) return o[Math.floor(n/100)]+' Hundred'+(n%100?' '+c(n%100):''); if(n<100000) return c(Math.floor(n/1000))+' Thousand'+(n%1000?' '+c(n%1000):''); if(n<10000000) return c(Math.floor(n/100000))+' Lakh'+(n%100000?' '+c(n%100000):''); return c(Math.floor(n/10000000))+' Crore'+(n%10000000?' '+c(n%10000000):''); }
    return c(Math.floor(n));
}

function escapeHtml(t) {
    if(!t) return '';
    return String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
}

