document.addEventListener('DOMContentLoaded', function() {
    changeBillType();
});

// ============ USER & SIDEBAR ============
function toggleUserDropdown() { document.getElementById('userDropdown').classList.toggle('show'); }
function openProfileModal() { document.getElementById('profileModal').style.display = 'flex'; }
function closeProfileModal() { document.getElementById('profileModal').style.display = 'none'; }
window.onclick = function(e) {
    if(e.target.classList.contains('modal')) e.target.style.display = 'none';
    if(!e.target.closest('.user-avatar') && !e.target.closest('.user-dropdown')) document.getElementById('userDropdown').classList.remove('show');
};
(function() {
    var sb = document.querySelector('.sidebar'), bd = document.body, btn = document.getElementById('sidebarToggleBtn');
    if(!sb || !btn) return;
    btn.addEventListener('click', function() { sb.classList.toggle('collapsed'); bd.classList.toggle('sidebar-collapsed'); document.cookie = "sidebar_collapsed=" + sb.classList.contains('collapsed') + "; path=/"; });
    if(document.cookie.indexOf('sidebar_collapsed=true') !== -1) { sb.classList.add('collapsed'); bd.classList.add('sidebar-collapsed'); }
})();
</script>


