<?php elseif ($page == 'view-bill' && isset($bill)): ?>

<?php

$bill_items = [];
if (isset($bill['id'])) {
    $stmt_items = $pdo->prepare("SELECT * FROM bill_items WHERE bill_id = ? ORDER BY sort_order ASC");
    $stmt_items->execute([$bill['id']]);
    $bill_items = $stmt_items->fetchAll();
    
    // ========== SORT BILL ITEMS: RECEIPTED FIRST, THEN UNRECEIPTED ==========
    usort($bill_items, function($a, $b) {
        $aReceipted = (strtolower($a['receipt_status'] ?? '') == 'receipted') ? 0 : 1;
        $bReceipted = (strtolower($b['receipt_status'] ?? '') == 'receipted') ? 0 : 1;
        
        if ($aReceipted == $bReceipted) {
            return 0;
        }
        return $aReceipted - $bReceipted;
    });
    // ========== END SORT ==========
}

// ========== FETCH CREATED BY: BILL CREATOR FROM bills TABLE ==========
$createdByName = 'N/A';
if (!empty($bill['created_by'])) {
    // bills.created_by contains user ID, get full_name from users table
    $stmtCreator = $pdo->prepare("SELECT full_name FROM users WHERE id = ?");
    $stmtCreator->execute([$bill['created_by']]);
    $fullName = $stmtCreator->fetchColumn();
    if (!empty($fullName)) {
        $createdByName = $fullName;
    }
}
// ========== END FETCH CREATED BY ==========

// Handle save shipment details and regenerate PDF
if (isset($_POST['save_shipment']) && isset($_POST['bill_id'])) {
    $bill_id = $_POST['bill_id'];
    $igm = $_POST['igm'] ?? '';
    $index_no = $_POST['index_no'] ?? '';
    $loading_date = $_POST['loading_date'] ?? '';
    
    // Update bills table using BILL ID
    $stmt = $pdo->prepare("UPDATE bills SET igm_number = ?, index_number = ?, loading_date = ? WHERE id = ?");
    $stmt->execute([$igm, $index_no, $loading_date, $bill_id]);
    
    // ========== CHANGE #1: Update all other bills with same job_id ==========
    $stmt_job = $pdo->prepare("SELECT job_id FROM bills WHERE id = ?");
    $stmt_job->execute([$bill_id]);
    $job_id = $stmt_job->fetchColumn();
    
    if ($job_id) {
        $stmt_update_all = $pdo->prepare("UPDATE bills SET igm_number = ?, index_number = ?, loading_date = ? WHERE job_id = ? AND id != ?");
        $stmt_update_all->execute([$igm, $index_no, $loading_date, $job_id, $bill_id]);
    }
    // ========== END CHANGE #1 ==========
    
    // ========== NEW: Handle bill items update ==========
    if (isset($_POST['item_id']) && is_array($_POST['item_id'])) {
        $updateStmt = $pdo->prepare("UPDATE bill_items SET amount = ? WHERE id = ? AND bill_id = ?");
        foreach ($_POST['item_id'] as $index => $itemId) {
            if (!empty($itemId)) {
                $newAmount = $_POST['item_amount'][$index] ?? '';
                if (is_numeric($newAmount) && $newAmount !== '') {
                    $newAmount = (float)$newAmount;
                }
                $updateStmt->execute([$newAmount, $itemId, $bill_id]);
            }
        }
        
        // Recalculate total_amount, advance_amount, balance_amount
        $stmt_total = $pdo->prepare("SELECT SUM(amount) as total FROM bill_items WHERE bill_id = ? AND amount REGEXP '^[0-9.]+$'");
        $stmt_total->execute([$bill_id]);
        $total_amount = $stmt_total->fetchColumn() ?? 0;
        
        $advance_amount = $bill['advance_amount'] ?? 0;
        $balance_amount = $total_amount - $advance_amount;
        
        $balance_words = numberToWords($balance_amount);
        
        $stmt_update_bill = $pdo->prepare("UPDATE bills SET total_amount = ?, balance_amount = ?, balance_words = ? WHERE id = ?");
        $stmt_update_bill->execute([$total_amount, $balance_amount, $balance_words, $bill_id]);
    }
    // ========== END NEW ==========
    
    // Fetch complete bill data using BILL ID
    $stmt = $pdo->prepare("SELECT b.*, j.job_date, j.vessel_arrival_date, j.vessel_name,
        j.bl_number, j.container_number, j.container_size, j.dry_port, j.port_of_discharge,
        j.shipping_line, j.free_time, j.soc, j.description, j.free_till,
        j.bonded_carrier, j.freight_forwarder_name, j.ntn, j.st_no
        FROM bills b LEFT JOIN jobs j ON b.job_id = j.id WHERE b.id = ?");
    $stmt->execute([$bill_id]);
    $updated_bill = $stmt->fetch();
    
    if ($updated_bill) {
        // Refresh bill items after update
        $stmt_items = $pdo->prepare("SELECT * FROM bill_items WHERE bill_id = ? ORDER BY sort_order");
        $stmt_items->execute([$bill_id]);
        $items = $stmt_items->fetchAll();
        
        // ========== SORT BILL ITEMS: RECEIPTED FIRST, THEN UNRECEIPTED ==========
        usort($items, function($a, $b) {
            $aReceipted = (strtolower($a['receipt_status'] ?? '') == 'receipted') ? 0 : 1;
            $bReceipted = (strtolower($b['receipt_status'] ?? '') == 'receipted') ? 0 : 1;
            
            if ($aReceipted == $bReceipted) {
                return 0;
            }
            return $aReceipted - $bReceipted;
        });
        // ========== END SORT ==========
        
        // Update createdByName: bill creator from bills.created_by
        if (!empty($updated_bill['created_by'])) {
            $stmtCreator2 = $pdo->prepare("SELECT full_name FROM users WHERE id = ?");
            $stmtCreator2->execute([$updated_bill['created_by']]);
            $fullName2 = $stmtCreator2->fetchColumn();
            if (!empty($fullName2)) {
                $createdByName = $fullName2;
            }
        }
        
        // Generate new PDF - overwrite existing file automatically
        $year = date('Y', strtotime($updated_bill['created_at'] ?? 'now'));
        $new_pdf_path = saveInvoiceHTML($updated_bill, $items, $year, $updated_bill['consignee'], $updated_bill['customer_name'], $updated_bill);
        
        // Update pdf_path in database only if changed
        $old_pdf_path = $updated_bill['pdf_path'] ?? '';
        if ($new_pdf_path != $old_pdf_path) {
            $stmt_update = $pdo->prepare("UPDATE bills SET pdf_path = ? WHERE id = ?");
            $stmt_update->execute([$new_pdf_path, $bill_id]);
        }
        
        // ========== SET FLAG TO COPY TO INVOICES ==========
        $_SESSION['copy_to_invoices'] = $bill_id;
        // ========== END FLAG ==========
        
        $_SESSION['message'] = "Shipment details and items saved successfully!";
    }
    
    // Refresh page using BILL ID
    header("Location: system.php?page=view-bill&id=" . $bill_id);
    exit();
}

// ========== NEW: Handle AJAX auto-save for individual amount ==========
if (isset($_POST['ajax_save_amount']) && isset($_POST['item_id']) && isset($_POST['amount']) && isset($_POST['bill_id'])) {
    $item_id = $_POST['item_id'];
    $newAmount = $_POST['amount'];
    $bill_id = $_POST['bill_id'];
    
    if (is_numeric($newAmount) && $newAmount !== '') {
        $newAmount = (float)$newAmount;
    }
    
    $stmt = $pdo->prepare("UPDATE bill_items SET amount = ? WHERE id = ? AND bill_id = ?");
    $stmt->execute([$newAmount, $item_id, $bill_id]);
    
    $stmt_total = $pdo->prepare("SELECT SUM(amount) as total FROM bill_items WHERE bill_id = ? AND amount REGEXP '^[0-9.]+$'");
    $stmt_total->execute([$bill_id]);
    $total_amount = $stmt_total->fetchColumn() ?? 0;
    
    $stmt_adv = $pdo->prepare("SELECT advance_amount FROM bills WHERE id = ?");
    $stmt_adv->execute([$bill_id]);
    $advance_amount = $stmt_adv->fetchColumn() ?? 0;
    
    $balance_amount = $total_amount - $advance_amount;
    $balance_words = numberToWords($balance_amount);
    
    $stmt_update = $pdo->prepare("UPDATE bills SET total_amount = ?, balance_amount = ?, balance_words = ? WHERE id = ?");
    $stmt_update->execute([$total_amount, $balance_amount, $balance_words, $bill_id]);
    
    header('Content-Type: application/json');
    echo json_encode([
        'success' => true,
        'total_amount' => number_format($total_amount, 2),
        'balance_amount' => number_format($balance_amount, 2),
        'balance_words' => $balance_words . ' Only',
        'advance_amount' => number_format($advance_amount, 2)
    ]);
    exit();
}
// ========== END AJAX HANDLER ==========

// ========== CHANGE #2: Auto-fill IGM/Index/Loading Date from other bills with same job_id ==========
if (empty($bill['igm_number']) && empty($bill['index_number']) && empty($bill['loading_date']) && !empty($bill['job_id'])) {
    $stmt_existing = $pdo->prepare("SELECT igm_number, index_number, loading_date FROM bills WHERE job_id = ? AND igm_number IS NOT NULL AND igm_number != '' AND index_number IS NOT NULL AND index_number != '' AND loading_date IS NOT NULL AND loading_date != '' ORDER BY id DESC LIMIT 1");
    $stmt_existing->execute([$bill['job_id']]);
    $existing_data = $stmt_existing->fetch();
    
    if ($existing_data) {
        $stmt_update_current = $pdo->prepare("UPDATE bills SET igm_number = ?, index_number = ?, loading_date = ? WHERE id = ?");
        $stmt_update_current->execute([$existing_data['igm_number'], $existing_data['index_number'], $existing_data['loading_date'], $bill['id']]);
        
        $bill['igm_number'] = $existing_data['igm_number'];
        $bill['index_number'] = $existing_data['index_number'];
        $bill['loading_date'] = $existing_data['loading_date'];
    }
}
// ========== END CHANGE #2 ==========

$debug_free_till = $bill['free_till'] ?? 'NOT SET IN BILL ARRAY';
$direct_free_till = '-';
if (!empty($bill['job_id'])) {
    $stmt_check = $pdo->prepare("SELECT free_till FROM jobs WHERE id = ?");
    $stmt_check->execute([$bill['job_id']]);
    $direct_free_till = $stmt_check->fetchColumn();
    if ($direct_free_till === false || $direct_free_till === null || $direct_free_till === '') {
        $direct_free_till = '- (No data in jobs table)';
    }
}
