<script>
// ========== AUTO-SAVE FUNCTION ==========
function autoSaveAmount(inputElement) {
    const itemId = inputElement.dataset.itemId;
    const billId = inputElement.dataset.billId;
    const newValue = inputElement.value.trim();
    const originalValue = inputElement.dataset.originalValue;
    
    if (newValue === originalValue) {
        return;
    }
    
    inputElement.classList.add('auto-save-saving');
    
    const formData = new FormData();
    formData.append('ajax_save_amount', '1');
    formData.append('item_id', itemId);
    formData.append('amount', newValue);
    formData.append('bill_id', billId);
    
    fetch('system.php?page=view-bill&id=' + billId, {
        method: 'POST',
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            document.getElementById('displayTotal').textContent = 'PKR ' + data.total_amount.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
            document.getElementById('displayBalance').textContent = 'PKR ' + data.balance_amount.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
            document.getElementById('displayAdvance').textContent = '(' + data.advance_amount.replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ')';
            document.getElementById('displayWords').textContent = data.balance_words;
            
            inputElement.dataset.originalValue = newValue;
            
            const statusDiv = document.getElementById('autoSaveStatus');
            statusDiv.style.display = 'block';
            statusDiv.style.opacity = '1';
            setTimeout(() => {
                statusDiv.style.opacity = '0';
                statusDiv.style.transition = 'opacity 0.3s';
                setTimeout(() => {
                    statusDiv.style.display = 'none';
                    statusDiv.style.transition = '';
                }, 300);
            }, 1500);
        }
    })
    .catch(error => {
        console.error('Auto-save error:', error);
    })
    .finally(() => {
        inputElement.classList.remove('auto-save-saving');
    });
}

// ========== ATTACH AUTO-SAVE TO ALL AMOUNT INPUTS ==========
document.addEventListener('DOMContentLoaded', function() {
    const amountInputs = document.querySelectorAll('.auto-save-amount');
    
    amountInputs.forEach(input => {
        input.addEventListener('keydown', function(e) {
            if (e.key === 'Enter') {
                e.preventDefault();
                this.blur();
            }
        });
        
        input.addEventListener('blur', function() {
            const newValue = this.value.trim();
            const originalValue = this.dataset.originalValue;
            
            if (newValue !== originalValue) {
                autoSaveAmount(this);
            }
        });
    });
    
    updateTotals();
});

// ========== UPDATE TOTALS FUNCTION (REAL-TIME) ==========
function updateTotals() {
    const amountInputs = document.querySelectorAll('.amount-input');
    let total = 0;
    
    amountInputs.forEach(input => {
        let val = input.value.trim();
        
        if (val !== '' && !isNaN(val) && !/^[a-zA-Z\s]+$/.test(val)) {
            total += parseFloat(val);
        }
    });
    
    const advanceAmount = <?php echo $bill['advance_amount'] ?? 0; ?>;
    const balance = total - advanceAmount;
    
    document.getElementById('displayTotal').textContent = 'PKR ' + total.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    document.getElementById('displayAdvance').textContent = advanceAmount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    document.getElementById('displayBalance').textContent = 'PKR ' + balance.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    
    const wordsElement = document.getElementById('displayWords');
    if (wordsElement) {
        wordsElement.textContent = numberToWordsSimple(balance) + ' Only';
    }
}

// ========== SIMPLE NUMBER TO WORDS ==========
function numberToWordsSimple(num) {
    if (num === 0) return 'Zero';
    
    const ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
    const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
    
    function convert(n) {
        if (n < 20) return ones[n];
        if (n < 100) return tens[Math.floor(n / 10)] + (n % 10 !== 0 ? ' ' + ones[n % 10] : '');
        if (n < 1000) return ones[Math.floor(n / 100)] + ' Hundred' + (n % 100 !== 0 ? ' and ' + convert(n % 100) : '');
        if (n < 100000) return convert(Math.floor(n / 1000)) + ' Thousand' + (n % 1000 !== 0 ? ' ' + convert(n % 1000) : '');
        if (n < 10000000) return convert(Math.floor(n / 100000)) + ' Lac' + (n % 100000 !== 0 ? ' ' + convert(n % 100000) : '');
        return convert(Math.floor(n / 10000000)) + ' Crore' + (n % 10000000 !== 0 ? ' ' + convert(n % 10000000) : '');
    }
    
    return convert(Math.abs(Math.round(num)));
}

setTimeout(function() {
    var successMsg = document.getElementById('successMessage');
    var errorMsg = document.getElementById('errorMessage');
    if (successMsg) {
        successMsg.style.transition = 'opacity 0.5s';
        successMsg.style.opacity = '0';
        setTimeout(function() { if (successMsg.parentNode) { successMsg.parentNode.removeChild(successMsg); } }, 500);
    }
    if (errorMsg) {
        errorMsg.style.transition = 'opacity 0.5s';
        errorMsg.style.opacity = '0';
        setTimeout(function() { if (errorMsg.parentNode) { errorMsg.parentNode.removeChild(errorMsg); } }, 500);
    }
}, 3000);

(function() { 
    const sidebar = document.querySelector('.sidebar'); 
    const body = document.body; 
    const toggleBtn = document.getElementById('sidebarToggleBtn'); 
    if (!sidebar || !toggleBtn) return; 
    function toggleSidebar() { 
        sidebar.classList.toggle('collapsed'); 
        if (sidebar.classList.contains('collapsed')) { 
            body.classList.add('sidebar-collapsed'); 
            document.cookie = "sidebar_collapsed=true; path=/"; 
        } else { 
            body.classList.remove('sidebar-collapsed'); 
            document.cookie = "sidebar_collapsed=false; path=/"; 
        } 
    } 
    toggleBtn.addEventListener('click', toggleSidebar); 
    if (document.cookie.indexOf('sidebar_collapsed=true') !== -1) { 
        sidebar.classList.add('collapsed'); 
        body.classList.add('sidebar-collapsed'); 
    } else { 
        sidebar.classList.remove('collapsed'); 
        body.classList.remove('sidebar-collapsed'); 
    } 
})();

// ========== PDF GENERATION FUNCTION ==========
async function generatePDFFromScreen() {
    const btn = document.getElementById('pdfBtn');
    const originalHTML = btn.innerHTML;
    const loadingOverlay = document.getElementById('pdfLoadingOverlay');
    
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Generating...';
    btn.disabled = true;
    loadingOverlay.style.display = 'block';
    
    await new Promise(resolve => requestAnimationFrame(() => setTimeout(resolve, 100)));
    
    try {
        const noPrintInputs = document.querySelectorAll('.no-print-input');
        const printShowsTable = document.querySelectorAll('.print-show-table');
        const printShows = document.querySelectorAll('.print-show');
        const noPrintElements = document.querySelectorAll('.no-print');
        
        noPrintInputs.forEach(input => { input.style.display = 'none'; });
        printShowsTable.forEach(span => { span.style.display = 'inline'; });
        printShows.forEach(span => {
            span.style.setProperty('display', 'block', 'important');
            span.style.width = '100%';
            span.style.textAlign = 'center';
        });
        noPrintElements.forEach(el => { el.style.display = 'none'; });
        
        await new Promise(resolve => setTimeout(resolve, 200));
        
        const invoiceElement = document.querySelector('.invoice-wrapper');
        
        const canvas = await html2canvas(invoiceElement, {
            scale: 3,
            useCORS: true,
            allowTaint: true,
            backgroundColor: '#ffffff',
            logging: false,
            width: 794,
            height: 1123
        });
        
        noPrintInputs.forEach(input => { input.style.display = 'inline-block'; });
        printShows.forEach(span => { span.style.display = 'none'; });
        noPrintElements.forEach(el => { el.style.display = ''; });
        
        const { jsPDF } = window.jspdf;
        const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
        
        const pageWidth = 210;
        const pageHeight = 297;
        const imgWidth = pageWidth;
        const imgHeight = pageHeight;
        const imgData = canvas.toDataURL('image/jpeg', 0.95);
        
        pdf.addImage(imgData, 'JPEG', 0, 0, imgWidth, imgHeight);
        
        loadingOverlay.style.display = 'none';
        
        const billNumber = '<?php echo $bill["bill_number"] ?? "bill"; ?>';
        const billType = '<?php echo strtolower(str_replace(" ", "_", trim($bill["bill_type"] ?? "bill"))); ?>';
        pdf.save(billType + '_' + billNumber + '.pdf');
        
    } catch (error) {
        console.error('PDF Error:', error);
        loadingOverlay.style.display = 'none';
        alert('Error generating PDF. Please try again.');
        document.querySelectorAll('.no-print-input').forEach(input => { input.style.display = 'inline-block'; });
        document.querySelectorAll('.print-show').forEach(span => { span.style.display = 'none'; });
        document.querySelectorAll('.no-print').forEach(el => { el.style.display = ''; });
    }
    
    btn.innerHTML = originalHTML;
    btn.disabled = false;
}

