<?php
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['image_data']) && isset($_POST['bill_id'])) {
    $bill_id = $_POST['bill_id'];
    $image_data = $_POST['image_data'];
    
    // Remove the data:image/jpeg;base64, prefix
    $image_data = str_replace('data:image/jpeg;base64,', '', $image_data);
    $image_data = str_replace(' ', '+', $image_data);
    $image_data = base64_decode($image_data);
    
    // Get bill details for folder structure
    $stmt = $pdo->prepare("SELECT b.* FROM bills b WHERE b.id = ?");
    $stmt->execute([$bill_id]);
    $bill = $stmt->fetch();
    
    if ($bill) {
        // Get job number
        $job_number = null;
        if (!empty($bill['job_id'])) {
            $stmtJobNo = $pdo->prepare("SELECT job_number FROM jobs WHERE id = ?");
            $stmtJobNo->execute([$bill['job_id']]);
            $job_number = $stmtJobNo->fetchColumn();
            if (empty($job_number)) {
                $job_number = $bill['job_id'];
            }
        } else {
            $job_number = 'no_job';
        }
        
        // Create folder structure
        $year = date('Y', strtotime($bill['created_at'] ?? 'now'));
        $invoices_base = __DIR__ . '/invoices/';
        $year_folder = $invoices_base . $year . '/';
        if (!is_dir($year_folder)) { mkdir($year_folder, 0777, true); }
        
        $consignee_name = $bill['consignee'] ?? 'Unknown';
        $consignee_folder = $year_folder . $consignee_name . '/';
        if (!is_dir($consignee_folder)) { mkdir($consignee_folder, 0777, true); }
        
        $customer_name = $bill['customer_name'] ?? 'Unknown';
        $agent_folder = $consignee_folder . $customer_name . '/';
        if (!is_dir($agent_folder)) { mkdir($agent_folder, 0777, true); }
        
        $job_folder = $agent_folder . $job_number . '/';
        if (!is_dir($job_folder)) { mkdir($job_folder, 0777, true); }
        
        // Determine filename
        $bill_type = $bill['bill_type'] ?? '';
        $original_filename = $bill['bill_number'] . '.pdf';
        $bill_type_lower = strtolower(trim($bill_type));
        
        if ($bill_type_lower == 'forwarding' || strpos($bill_type_lower, 'forwarding') !== false) {
            $filename = 'Forwarding-' . $original_filename;
        } elseif ($bill_type_lower == 'detention' || strpos($bill_type_lower, 'detention') !== false) {
            $filename = 'Detention-' . $original_filename;
        } else {
            $filename = $original_filename;
        }
        
        // Save as PDF using Dompdf
        require_once(__DIR__ . '/dompdf/autoload.inc.php');
        
        $html = '<!DOCTYPE html>
        <html>
        <head>
            <meta charset="UTF-8">
            <style>
                @page { size: A4; margin: 0; }
                body { margin: 0; padding: 0; }
                img { width: 210mm; height: 297mm; }
            </style>
        </head>
        <body>
            <img src="data:image/jpeg;base64,' . base64_encode($image_data) . '">
        </body>
        </html>';
        
        $options = new \Dompdf\Options();
        $options->set('isHtml5ParserEnabled', true);
        $options->set('isRemoteEnabled', true);
        
        $dompdf = new \Dompdf\Dompdf($options);
        $dompdf->loadHtml($html);
        $dompdf->setPaper('A4', 'portrait');
        $dompdf->render();
        
        $pdf_output = $dompdf->output();
        $full_path = $job_folder . $filename;
        file_put_contents($full_path, $pdf_output);
        
        echo json_encode(['success' => true, 'path' => $full_path]);
    } else {
        echo json_encode(['success' => false, 'error' => 'Bill not found']);
    }
} else {
    echo json_encode(['success' => false, 'error' => 'Invalid request']);
}
exit;
?>


