<script>
var originalItems = <?php echo json_encode($original_items); ?>;
var forwardingHeadings = <?php echo json_encode($forwardingCombinedHeadings); ?>;
var detentionHeadings = <?php echo json_encode($detentionCombinedHeadings); ?>;

function updateHeadings() {
    var billType = document.getElementById('bill_type').value;
    var headings = billType == 'forwarding' ? forwardingHeadings : detentionHeadings;
    var selects = document.querySelectorAll('.heading-select');
    for(var k = 0; k < selects.length; k++) {
        var currentValue = selects[k].value;
        selects[k].innerHTML = '<option value="">Select heading...</option>';
        for(var l = 0; l < headings.length; l++) {
            var option = document.createElement('option');
            option.value = headings[l];
            option.text = headings[l];
            if(currentValue == headings[l]) option.selected = true;
            selects[k].appendChild(option);
        }
    }
}

function addRowWithData(headingValue, statusValue, amountValue) {
    var tbody = document.getElementById('itemsBody');
    
    // Remove empty state if exists
    var emptyState = tbody.querySelector('.empty-table-state');
    if(emptyState) emptyState.remove();
    
    var newRow = document.createElement('tr');
    newRow.className = 'draggable-row';
    
    var billType = document.getElementById('bill_type').value;
    var headings = billType == 'forwarding' ? forwardingHeadings : detentionHeadings;
    
    var headingHtml = '<td class="item-select-cell">' +
        '<select name="heading[]" class="heading-select" style="width:100%;">' +
        '<option value="">Select heading...</option>';
    for(var k = 0; k < headings.length; k++) {
        var selected = (headings[k] == headingValue) ? 'selected' : '';
        headingHtml += '<option value="' + headings[k] + '" ' + selected + '>' + headings[k] + '</option>';
    }
    headingHtml += '</select>' +
        '<input type="text" name="heading_text[]" class="custom-heading-input" placeholder="Or enter custom heading" value="' + (headingValue && !headings.includes(headingValue) ? headingValue : '') + '">' +
        '</td>';
    
    var statusHtml = '<td class="item-select-cell">' +
        '<select name="receipt_status[]" class="form-control" style="width:100%; padding:8px; border:1px solid #e2e8f0; border-radius:8px;">' +
        '<option value="Receipted"' + (statusValue == 'Receipted' ? ' selected' : '') + '>✅ Receipted</option>' +
        '<option value="Unreceipted"' + (statusValue == 'Unreceipted' ? ' selected' : '') + '>⏳ Unreceipted</option>' +
        '</select></td>';
    
    var amountHtml = '<td class="item-input-cell">' +
        '<input type="text" name="amount[]" onkeyup="calculateTotal()" placeholder="0.00" value="' + (amountValue ? amountValue : '') + '">' +
        '</td>';
    
    var actionHtml = '<td style="text-align:center;">' +
        '<button type="button" class="btn-delete-row" onclick="removeRow(this)" title="Remove">' +
        '<i class="fas fa-times"></i>' +
        '</button></td>';
    
    newRow.innerHTML = headingHtml + statusHtml + amountHtml + actionHtml;
    tbody.appendChild(newRow);
    
    updateItemCounter();
}

function addRow() {
    var lastStatus = 'Unreceipted'; // Default if no rows exist
    console.log(lastStatus);

    var tbody = document.getElementById('itemsBody');
    var rows = tbody.querySelectorAll('tr.draggable-row');

    if (rows.length > 0) {
        var lastSelect = rows[rows.length - 1].querySelector('select[name="receipt_status[]"]');
        if (lastSelect) {
            lastStatus = lastSelect.value;
        }
    }

    addRowWithData('', lastStatus, '');
}

function removeRow(btn) {
    var rows = document.querySelectorAll('#itemsBody tr.draggable-row');
    if(rows.length > 1) {
        btn.closest('tr').remove();
        calculateTotal();
        updateItemCounter();
        
        // Show empty state if no rows
        if(document.querySelectorAll('#itemsBody tr.draggable-row').length === 0) {
            document.getElementById('itemsBody').innerHTML = '<tr class="empty-table-state"><td colspan="4"><i class="fas fa-inbox"></i><p>No items added yet</p></td></tr>';
        }
    } else {
        alert("At least one row is required!");
    }
}

function updateItemCounter() {
    var count = document.querySelectorAll('#itemsBody tr.draggable-row').length;
    var counter = document.getElementById('itemCounter');
    if(counter) {
        counter.textContent = '(' + count + ' items)';
    }
}

function calculateTotal() {
    var amounts = document.querySelectorAll('#itemsBody input[name="amount[]"]');
    var total = 0;
    for(var i = 0; i < amounts.length; i++) {
        var val = parseFloat(amounts[i].value);
        if(!isNaN(val)) total += val;
    }
    var totalField = document.getElementById('totalAmount');
    if(totalField) totalField.value = total.toFixed(2);
    calculateBalance();
}

function calculateBalance() {
    var total = parseFloat(document.getElementById('totalAmount')?.value) || 0;
    var advance = parseFloat(document.getElementById('advanceAmount')?.value) || 0;
    var balance = total - advance;
    var balanceField = document.getElementById('balanceAmount');
    if(balanceField) balanceField.value = balance.toFixed(2);
    var wordsField = document.getElementById('balanceWords');
    if(wordsField) {
        var words = numberToWords(balance);
        wordsField.value = words + " Rupees Only";
    }
}

function numberToWords(n) {
    if(n==0) return "Zero";
    var o=["","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve","Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"];
    var t=["","","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"];
    function c(n) {
        if(n<20) return o[n];
        if(n<100) return t[Math.floor(n/10)]+(n%10?" "+o[n%10]:"");
        if(n<1000) return o[Math.floor(n/100)]+" Hundred"+(n%100?" "+c(n%100):"");
        if(n<100000) return c(Math.floor(n/1000))+" Thousand"+(n%1000?" "+c(n%1000):"");
        if(n<10000000) return c(Math.floor(n/100000))+" Lakh"+(n%100000?" "+c(n%100000):"");
        return c(Math.floor(n/10000000))+" Crore"+(n%10000000?" "+c(n%10000000):"");
    }
    return c(Math.floor(n));
}

document.addEventListener('DOMContentLoaded', function() {
    if(originalItems && originalItems.length > 0) {
        for(var i = 0; i < originalItems.length; i++) {
            addRowWithData(originalItems[i].heading, originalItems[i].receipt_status, originalItems[i].amount);
        }
    } else {
        addRow();
    }
    calculateTotal();
    updateHeadings();
    updateItemCounter();
});

function toggleUserDropdown() { var dropdown = document.getElementById('userDropdown'); dropdown.classList.toggle('show'); }
function openProfileModal() { document.getElementById('profileModal').style.display = 'flex'; document.getElementById('userDropdown').classList.remove('show'); }
function closeProfileModal() { document.getElementById('profileModal').style.display = 'none'; }
window.onclick = function(e) { if(e.target.classList && e.target.classList.contains('modal')) { e.target.style.display = 'none'; } if(!e.target.closest('.user-avatar') && !e.target.closest('.user-dropdown')) { var dropdown = document.getElementById('userDropdown'); if(dropdown) dropdown.classList.remove('show'); } }
(function() { const sidebar = document.querySelector('.sidebar'); const body = document.body; const toggleBtn = document.getElementById('sidebarToggleBtn'); if (!sidebar || !toggleBtn) return; function toggleSidebar() { sidebar.classList.toggle('collapsed'); if (sidebar.classList.contains('collapsed')) { body.classList.add('sidebar-collapsed'); document.cookie = "sidebar_collapsed=true; path=/"; } else { body.classList.remove('sidebar-collapsed'); document.cookie = "sidebar_collapsed=false; path=/"; } } toggleBtn.addEventListener('click', toggleSidebar); if (document.cookie.indexOf('sidebar_collapsed=true') !== -1) { sidebar.classList.add('collapsed'); body.classList.add('sidebar-collapsed'); } else { sidebar.classList.remove('collapsed'); body.classList.remove('sidebar-collapsed'); } })();
</script>

