<script>
// CSS.escape polyfill
if (!CSS.escape) {
    CSS.escape = function(value) {
        return String(value).replace(/([^\w-])/g, '\\$1');
    };
}

let csvDataCache = [];
let currentOffset = 20;
let limit = 20;
let totalMasters = <?php echo $totalCount; ?>;
let currentType = '<?php echo $type; ?>';

function toggleConsigneeFields() {
    var typeSelect = document.getElementById('masterType');
    var extraFields = document.getElementById('consigneeExtraFields');
    if(typeSelect && extraFields) {
        if(typeSelect.value === 'consignee') {
            extraFields.style.display = 'block';
        } else {
            extraFields.style.display = 'none';
        }
    }
}

function openCSVUploadModal() {
    document.getElementById('csvUploadModal').style.display = 'flex';
    document.getElementById('csvFile').value = '';
    document.getElementById('csvPreview').style.display = 'none';
    csvDataCache = [];
}

function closeCSVUploadModal() {
    document.getElementById('csvUploadModal').style.display = 'none';
}

document.getElementById('csvFile').addEventListener('change', function(e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(event) {
        const content = event.target.result;
        const lines = content.split('\n');
        const previewData = [];
        for (let i = 0; i < lines.length && i < 10; i++) {
            if (lines[i].trim() === '') continue;
            const columns = lines[i].split(',');
            if (columns.length >= 2) {
                previewData.push({ code: columns[0].trim(), name: columns[1].trim() });
            }
        }
        csvDataCache = [];
        for (let i = 0; i < lines.length; i++) {
            if (lines[i].trim() === '') continue;
            const columns = lines[i].split(',');
            if (columns.length >= 2) {
                csvDataCache.push({ code: columns[0].trim(), name: columns[1].trim() });
            }
        }
        const previewBody = document.getElementById('previewBody');
        previewBody.innerHTML = '';
        previewData.forEach(item => {
            const row = previewBody.insertRow();
            row.insertCell(0).innerHTML = item.code;
            row.insertCell(1).innerHTML = item.name;
        });
        document.getElementById('csvPreview').style.display = 'block';
    };
    reader.readAsText(file);
});

function uploadCSV() {
    if (csvDataCache.length === 0) {
        alert('Please select a CSV file first');
        return;
    }
    const masterType = document.getElementById('csvMasterType').value;
    const uploadBtn = document.getElementById('uploadBtn');
    const progressDiv = document.getElementById('uploadProgress');
    uploadBtn.disabled = true;
    progressDiv.style.display = 'block';
    let errors = [];
    function uploadNext(index) {
        if (index >= csvDataCache.length) {
            document.getElementById('progressBar').style.width = '100%';
            document.getElementById('progressBar').innerHTML = '100%';
            setTimeout(() => {
                if (errors.length > 0) {
                    alert('Upload completed with ' + errors.length + ' errors:\n' + errors.join('\n'));
                } else {
                    alert('Successfully uploaded ' + csvDataCache.length + ' records!');
                }
                location.reload();
            }, 500);
            return;
        }
        const item = csvDataCache[index];
        const percent = Math.round((index / csvDataCache.length) * 100);
        document.getElementById('progressBar').style.width = percent + '%';
        document.getElementById('progressBar').innerHTML = percent + '%';
        fetch('system.php?page=add-master', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ type: masterType, code: item.code, name: item.name, is_active: 1 })
        })
        .then(response => response.json())
        .then(data => {
            if (data.success === false) {
                errors.push('Row ' + (index+1) + ': ' + (data.message || 'Error'));
            }
            uploadNext(index + 1);
        })
        .catch(error => {
            errors.push('Row ' + (index+1) + ': Network error');
            uploadNext(index + 1);
        });
    }
    uploadNext(0);
}

function openMasterModal() { 
    document.getElementById('masterModalTitle').innerText = 'Add New Item'; 
    document.getElementById('masterId').value = ''; 
    document.getElementById('masterOldName').value = '';
    document.getElementById('masterCode').value = ''; 
    document.getElementById('masterName').value = ''; 
    document.getElementById('masterNTN').value = ''; 
    document.getElementById('masterSTNo').value = ''; 
    document.getElementById('masterStatus').value = '1'; 
    toggleConsigneeFields();
    document.getElementById('masterModal').style.display = 'flex'; 
}

function editMaster(id, code, name, status, ntn, st_no) { 
    document.getElementById('masterModalTitle').innerText = 'Edit Item'; 
    document.getElementById('masterId').value = id; 
    document.getElementById('masterOldName').value = name;
    document.getElementById('masterCode').value = code; 
    document.getElementById('masterName').value = name; 
    document.getElementById('masterStatus').value = status; 
    if(ntn !== undefined && ntn !== null) {
        document.getElementById('masterNTN').value = ntn || ''; 
        document.getElementById('masterSTNo').value = st_no || ''; 
    } else {
        document.getElementById('masterNTN').value = ''; 
        document.getElementById('masterSTNo').value = ''; 
    }
    toggleConsigneeFields();
    document.getElementById('masterModal').style.display = 'flex'; 
}

function saveMaster() { 
    let id = document.getElementById('masterId').value; 
    let t = document.getElementById('masterType').value; 
    let n = document.getElementById('masterName').value; 
    let s = document.getElementById('masterStatus').value; 
    let ntn = document.getElementById('masterNTN').value; 
    let st_no = document.getElementById('masterSTNo').value; 
    let oldName = document.getElementById('masterOldName').value || '';
    
    // Auto-generate code from name
    let c = document.getElementById('masterCode').value;
    if (!c) {
        c = n.trim().replace(/\s+/g, '_').toUpperCase();
        document.getElementById('masterCode').value = c;
    }
    
    let url = id ? 'system.php?page=update-master' : 'system.php?page=add-master'; 
    
    let formData = { 
        id: id, 
        type: t, 
        code: c, 
        name: n, 
        is_active: s,
        ntn: ntn,
        st_no: st_no,
        old_name: oldName
    };
    
    if (id && oldName !== n && t !== 'consignee') {
        if(confirm('Name changed from "' + oldName + '" to "' + n + '". Update all related jobs?')) {
            formData.update_jobs = true;
            formData.old_name = oldName;
        }
    }
    
    fetch(url, { 
        method: 'POST', 
        headers: { 'Content-Type': 'application/json' }, 
        body: JSON.stringify(formData) 
    })
    .then(response => response.json())
    .then(data => {
        if(data.success) {
            if (data.master) {
                if (id) {
                    let oldRow = document.querySelector(`tr[data-id="${CSS.escape(id)}"]`);
                    if (oldRow) {
                        let newRow = createMasterRow(data.master);
                        oldRow.parentNode.replaceChild(newRow, oldRow);
                    } else {
                        location.reload();
                    }
                } else {
                    let newRow = createMasterRow(data.master);
                    let tbody = document.getElementById('mastersTbody');
                    let emptyRow = tbody.querySelector('td[colspan]');
                    if (emptyRow) {
                        emptyRow.parentElement.remove();
                    }
                    tbody.insertBefore(newRow, tbody.firstChild);
                    totalMasters++;
                    document.getElementById('loadMoreInfo').innerText = 'Showing ' + Math.min(currentOffset + 1, totalMasters) + ' of ' + totalMasters;
                }
                closeMasterModal();
            } else {
                location.reload();
            }
        } else {
            alert(data.message || 'Error saving record');
        }
    })
    .catch(error => {
        alert('Network error occurred');
        console.error(error);
    });
}

function createMasterRow(master) {
    let tr = document.createElement('tr');
    tr.setAttribute('data-id', master.id);
    tr.setAttribute('data-type', currentType);
    tr.setAttribute('data-code', master.code || '');
    tr.setAttribute('data-name', master.name || '');
    tr.setAttribute('data-status', master.is_active || 1);
    tr.setAttribute('data-ntn', master.ntn || '');
    tr.setAttribute('data-stno', master.st_no || '');
    tr.setAttribute('data-jobcount', master.job_count || 0);
    tr.setAttribute('data-linkedjobs', master.linked_jobs || '');
    
    function esc(s) { return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;'); }
    let name = esc(master.name);
    let ntn = esc(master.ntn || '');
    let st_no = esc(master.st_no || '');
    let isActive = master.is_active ? 'active' : 'cancelled';
    let statusText = master.is_active ? 'Active' : 'Inactive';

    let ntnCell = '', stnoCell = '';
    if (currentType === 'consignee') {
        ntnCell = `<td style="padding: 10px 8px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">${ntn}</td>`;
        stnoCell = `<td style="padding: 10px 8px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;">${st_no}</td>`;
    }

    let actionsHtml = `
        <button class="btn-warning btn-sm edit-row-btn" title="Edit" style="padding: 4px 8px; font-size: 11px; margin: 0 2px; border-radius: 4px; border: none; cursor: pointer; background:#ff9800; color:white;"><i class="fas fa-edit"></i></button>
        <button class="btn-danger btn-sm delete-row-btn" title="Delete" style="padding: 4px 8px; font-size: 11px; margin: 0 2px; border-radius: 4px; border: none; cursor: pointer; background:#dc3545; color:white;"><i class="fas fa-trash"></i></button>`;

    tr.innerHTML = `
        <td style="padding: 10px 8px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;"><strong>${name}</strong></td>
        ${currentType === 'consignee' ? ntnCell + stnoCell : ''}
        <td style="padding: 10px 8px; border-bottom: 1px solid #e8eaed; border-right: 1px solid #e8eaed;"><span class="status-badge ${isActive}">${statusText}</span></td>
        <td class="action-cell" style="padding: 10px 8px; border-bottom: 1px solid #e8eaed; white-space: nowrap; text-align: center;">${actionsHtml}</td>
    `;
    return tr;
}

function deleteMaster(id) { 
    let row = document.querySelector(`tr[data-id="${CSS.escape(id)}"]`);
    let name = row ? row.getAttribute('data-name') : '';
    let jobCount = row ? parseInt(row.getAttribute('data-jobcount')) || 0 : 0;
    let type = currentType;
    
    let confirmMsg = 'Delete this item?';
    if (jobCount > 0) {
        confirmMsg = `"${name}" is used in ${jobCount} job(s).\n\nDelete it and clear from all jobs?`;
    }
    
    if(confirm(confirmMsg)) { 
        let url = 'system.php?page=delete-master&id=' + encodeURIComponent(id) + '&type=' + encodeURIComponent(type);
        if (name) {
            url += '&name=' + encodeURIComponent(name);
        }
        fetch(url)
            .then(response => response.json())
            .then(data => {
                alert(data.message || (data.success ? 'Deleted successfully' : 'Error'));
                if(data.success) location.reload();
            })
            .catch(error => {
                alert('Network error occurred');
                console.error(error);
            });
    } 
}

function deleteMasterConsignee(id, masterName, jobCount, linkedJobs) {
    if(jobCount > 0) {
        let message = 'Cannot delete "' + masterName + '"!\n\n';
        message += 'This consignee is used in ' + jobCount + ' job(s):\n';
        if(linkedJobs) {
            let jobs = linkedJobs.split(', ');
            if(jobs.length <= 5) {
                message += linkedJobs;
            } else {
                message += jobs.slice(0, 5).join(', ') + ' ...and ' + (jobs.length - 5) + ' more';
            }
        }
        message += '\n\nPlease unlink or reassign those jobs first.';
        alert(message);
        return;
    }
    if(confirm('Delete this consignee?')) { 
        let url = 'system.php?page=delete-master&id=' + encodeURIComponent(id) + '&type=consignee&name=' + encodeURIComponent(masterName);
        fetch(url)
            .then(response => response.json())
            .then(data => {
                alert(data.message || (data.success ? 'Deleted successfully' : 'Error'));
                if(data.success) location.reload();
            })
            .catch(error => {
                alert('Network error occurred');
                console.error(error);
            });
    } 
}

function deleteJobByNumber(jobNumber) {
    if (!confirm('Permanently delete job ' + jobNumber + '?')) return;
    fetch('system.php?page=delete-job', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ job_number: jobNumber })
    })
    .then(r => r.json())
    .then(data => {
        if(data.success) {
            alert('Job deleted successfully');
        } else {
            alert(data.message || 'Delete failed');
        }
    });
}

function updateJobsConsignee(oldName, newName) {
    fetch('system.php?page=update-jobs-consignee', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ old_name: oldName, new_name: newName })
    })
    .then(response => response.json())
    .then(data => {
        if(data.success) {
            alert(data.message);
            location.reload();
        } else {
            alert('Error updating jobs: ' + data.message);
            location.reload();
        }
    })
    .catch(error => {
        alert('Network error occurred');
        location.reload();
    });
}

function closeMasterModal() { 
    document.getElementById('masterModal').style.display = 'none'; 
}

function loadMoreMasters() {
    const btn = document.getElementById('loadMoreBtn');
    btn.disabled = true;
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Loading...';
    fetch(`system.php?page=load-more-masters&type=${currentType}&limit=${limit}&offset=${currentOffset}`)
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            let tbody = document.getElementById('mastersTbody');
            data.masters.forEach(master => {
                let tr = createMasterRow(master);
                tbody.appendChild(tr);
            });
            currentOffset += data.masters.length;
            document.getElementById('loadMoreInfo').innerHTML = 'Showing ' + currentOffset + ' of ' + totalMasters;
            if (currentOffset >= totalMasters) {
                document.getElementById('loadMoreContainer').style.display = 'none';
            } else {
                btn.disabled = false;
                btn.innerHTML = '<i class="fas fa-chevron-down"></i> Load More';
            }
        } else {
            alert(data.message || 'Error loading more');
            btn.disabled = false;
            btn.innerHTML = '<i class="fas fa-chevron-down"></i> Load More';
        }
    })
    .catch(error => {
        alert('Network error');
        btn.disabled = false;
        btn.innerHTML = '<i class="fas fa-chevron-down"></i> Load More';
    });
}

function escapeHtml(text) {
    if (!text) return '';
    return String(text).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
}

function globalSearchMasters() {
    let input = document.getElementById('globalMasterSearch');
    let filter = input.value.toLowerCase();
    let table = document.getElementById('mastersTable');
    let rows = table.getElementsByTagName('tr');
    for(let i=2; i<rows.length; i++) {
        rows[i].style.display = rows[i].textContent.toLowerCase().includes(filter) ? '' : 'none';
    }
}

function initMasterColumnFilters() {
    var filters = document.querySelectorAll('#mastersTable .col-filter');
    filters.forEach(function(filter) {
        filter.addEventListener('keyup', function() {
            var colIndex = parseInt(this.dataset.col);
            var filterValue = this.value.toLowerCase();
            var table = document.getElementById('mastersTable');
            var rows = table.querySelectorAll('tbody tr');
            for(var i=0; i<rows.length; i++) {
                var row = rows[i];
                if(row.querySelector('td[colspan]')) continue;
                var cell = row.children[colIndex];
                if(cell) row.style.display = cell.textContent.toLowerCase().includes(filterValue) ? '' : 'none';
            }
        });
    });
}

function initMastersSorting() {
    var headers = document.querySelectorAll('#mastersTable th.sortable');
    var currentSortColumn = null;
    var currentSortDirection = 'asc';
    headers.forEach(function(header) {
        header.addEventListener('click', function(e) {
            if(e.target.classList && e.target.classList.contains('col-filter')) return;
            var column = parseInt(this.dataset.column);
            var table = this.closest('#mastersTable');
            var tbody = table.querySelector('tbody');
            var rows = Array.from(tbody.querySelectorAll('tr'));
            if(rows.length === 1 && rows[0].querySelector('td[colspan]')) return;
            headers.forEach(h => h.classList.remove('asc','desc'));
            if(currentSortColumn === column) {
                currentSortDirection = currentSortDirection === 'asc' ? 'desc' : 'asc';
            } else {
                currentSortColumn = column;
                currentSortDirection = 'asc';
            }
            this.classList.add(currentSortDirection);
            rows.sort(function(a,b) {
                var aVal = a.children[column] ? a.children[column].innerText.trim() : '';
                var bVal = b.children[column] ? b.children[column].innerText.trim() : '';
                var aNum = parseFloat(aVal.replace(/[^0-9.-]/g,''));
                var bNum = parseFloat(bVal.replace(/[^0-9.-]/g,''));
                if(!isNaN(aNum) && !isNaN(bNum)) return currentSortDirection==='asc' ? aNum-bNum : bNum-aNum;
                return currentSortDirection==='asc' ? aVal.toLowerCase().localeCompare(bVal.toLowerCase()) : bVal.toLowerCase().localeCompare(aVal.toLowerCase());
            });
            rows.forEach(row => tbody.appendChild(row));
        });
    });
}

// ============ BILL HEADINGS MASTER ============
function openBillHeadingModal(row) {
    document.getElementById('billHeadingModalTitle').innerText = row ? 'Edit Bill Heading' : 'Add Bill Heading';
    document.getElementById('bhId').value = row ? row.getAttribute('data-id') : '';
    document.getElementById('bhHeading').value = row ? row.getAttribute('data-heading') : '';
    document.getElementById('bhBillType').value = row ? row.getAttribute('data-billtype') : 'forwarding';
    document.getElementById('bhReceiptStatus').value = row ? row.getAttribute('data-receipt') : 'Receipted';
    document.getElementById('bhSortOrder').value = row ? row.getAttribute('data-sort') : '';
    document.getElementById('bhStatus').value = row ? row.getAttribute('data-status') : '1';
    document.getElementById('billHeadingModal').style.display = 'flex';
    document.getElementById('bhHeading').focus();
}

function closeBillHeadingModal() {
    document.getElementById('billHeadingModal').style.display = 'none';
}

function saveBillHeading() {
    var heading = document.getElementById('bhHeading').value.trim();
    if (!heading) {
        alert('Please enter a heading');
        return;
    }
    fetch('system.php?page=save-bill-heading', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            id: document.getElementById('bhId').value,
            heading: heading,
            bill_type: document.getElementById('bhBillType').value,
            receipt_status: document.getElementById('bhReceiptStatus').value,
            sort_order: document.getElementById('bhSortOrder').value,
            is_active: document.getElementById('bhStatus').value === '1'
        })
    })
    .then(r => r.json())
    .then(data => {
        if (data.success) location.reload();
        else alert(data.message || 'Error saving heading');
    })
    .catch(() => alert('Network error occurred'));
}

function deleteBillHeading(row) {
    if (!confirm('Delete "' + row.getAttribute('data-heading') + '"?\n\nExisting bills keep their items. To hide it from new bills only, edit it and set Status to Inactive.')) return;
    fetch('system.php?page=delete-bill-heading', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: row.getAttribute('data-id') })
    })
    .then(r => r.json())
    .then(data => {
        if (data.success) location.reload();
        else alert(data.message || 'Error deleting heading');
    })
    .catch(() => alert('Network error occurred'));
}

document.addEventListener('click', function(e) {
    var editBtn = e.target.closest('.bh-edit-btn');
    if (editBtn) openBillHeadingModal(editBtn.closest('tr'));
    var deleteBtn = e.target.closest('.bh-delete-btn');
    if (deleteBtn) deleteBillHeading(deleteBtn.closest('tr'));
});

// Event delegation for edit and delete buttons
document.addEventListener('click', function(e) {
    if (e.target.closest('.edit-row-btn')) {
        let btn = e.target.closest('.edit-row-btn');
        let row = btn.closest('tr');
        if (!row) return;
        
        let id = row.getAttribute('data-id');
        let code = row.getAttribute('data-code');
        let name = row.getAttribute('data-name');
        let status = parseInt(row.getAttribute('data-status')) || 1;
        let ntn = row.getAttribute('data-ntn') || '';
        let stno = row.getAttribute('data-stno') || '';
        
        if (currentType === 'consignee') {
            editMaster(id, code, name, status, ntn, stno);
        } else {
            editMaster(id, code, name, status);
        }
    }
    
    if (e.target.closest('.delete-row-btn')) {
        let btn = e.target.closest('.delete-row-btn');
        let row = btn.closest('tr');
        if (!row) return;
        
        let id = row.getAttribute('data-id');
        let name = row.getAttribute('data-name');
        let jobCount = parseInt(row.getAttribute('data-jobcount')) || 0;
        let linkedJobs = row.getAttribute('data-linkedjobs') || '';
        
        if (currentType === 'consignee') {
            deleteMasterConsignee(id, name, jobCount, linkedJobs);
        } else {
            deleteMaster(id);
        }
    }
});

document.addEventListener('DOMContentLoaded', function() {
    initMastersSorting();
    initMasterColumnFilters();
    toggleConsigneeFields();
});

function toggleUserDropdown() { document.getElementById('userDropdown').classList.toggle('show'); }
function openProfileModal() { document.getElementById('profileModal').style.display='flex'; document.getElementById('userDropdown').classList.remove('show'); }
