function initClearanceSorting() {
    var headers = document.querySelectorAll('#clearanceTable th.sortable');
    var currentSortColumn = null;
    var currentSortDirection = 'asc';
    headers.forEach(function(header) {
        header.addEventListener('click', function(e) {
            if(e.target.classList && (e.target.classList.contains('col-filter') || e.target.classList.contains('resize-handle'))) return;
            var column = parseInt(this.dataset.column);
            var table = this.closest('#clearanceTable');
            var tbody = table.querySelector('tbody');
            var rows = Array.from(tbody.querySelectorAll('tr'));
            if (rows.length === 1 && rows[0].querySelector('td[colspan]')) return;
            headers.forEach(function(h) { h.classList.remove('asc', 'desc'); });
            if (currentSortColumn === column) { currentSortDirection = currentSortDirection === 'asc' ? 'desc' : 'asc'; }
            else { currentSortColumn = column; currentSortDirection = 'asc'; }
            this.classList.add(currentSortDirection);
            rows.sort(function(a, b) {
                var aValue = a.children[column] ? a.children[column].innerText.trim() : '';
                var bValue = b.children[column] ? b.children[column].innerText.trim() : '';
                var aNum = parseFloat(aValue.replace(/[^0-9.-]/g, ''));
                var bNum = parseFloat(bValue.replace(/[^0-9.-]/g, ''));
                if (!isNaN(aNum) && !isNaN(bNum)) { return currentSortDirection === 'asc' ? aNum - bNum : bNum - aNum; }
                aValue = aValue.toLowerCase(); bValue = bValue.toLowerCase();
                if (currentSortDirection === 'asc') { return aValue.localeCompare(bValue); }
                else { return bValue.localeCompare(aValue); }
            });
            rows.forEach(function(row) { tbody.appendChild(row); });
        });
    });
}

function initClearanceColumnResizing() {
    var table = document.getElementById('clearanceTable');
    if (!table) return;
    var resizeHandles = table.querySelectorAll('.resize-handle');
    var currentHandle = null, currentTh = null, startX = 0, startWidth = 0;
    resizeHandles.forEach(function(handle) {
        handle.addEventListener('mousedown', function(e) {
            e.preventDefault(); e.stopPropagation();
            currentHandle = handle; currentHandle.classList.add('active');
            currentTh = handle.parentElement; startX = e.clientX; startWidth = currentTh.offsetWidth;
            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
            document.body.style.cursor = 'col-resize'; document.body.style.userSelect = 'none';
        });
    });
    function onMouseMove(e) {
        if (!currentHandle || !currentTh) return;
        var diffX = e.clientX - startX;
        var newWidth = startWidth + diffX;
        if (newWidth < 50) newWidth = 50;
        if (newWidth > 500) newWidth = 500;
        currentTh.style.width = newWidth + 'px'; currentTh.style.minWidth = newWidth + 'px';
    }
    function onMouseUp() {
        if (currentHandle) { currentHandle.classList.remove('active'); }
        currentHandle = null; currentTh = null;
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
        document.body.style.cursor = ''; document.body.style.userSelect = '';
    }
}

function initClearanceFilters() {
    var filters = document.querySelectorAll('#clearanceTable .col-filter');
    filters.forEach(function(filter) {
        filter.addEventListener('keyup', function() {
            var colIndex = parseInt(this.dataset.col);
            var filterValue = this.value.toLowerCase().trim();
            if (filterValue === '') { this.classList.remove('active-filter'); }
            else { this.classList.add('active-filter'); }
            var table = document.getElementById('clearanceTable');
            var rows = table.querySelectorAll('tbody tr');
            for(var i = 0; i < rows.length; i++) {
                var row = rows[i];
                if(row.querySelector('td[colspan]')) continue;
                var cell = row.children[colIndex];
                if(cell) { var cellText = cell.textContent.toLowerCase(); row.style.display = cellText.includes(filterValue) ? '' : 'none'; }
            }
        });
    });
}

document.addEventListener('DOMContentLoaded', function() {
    initClearanceSorting();
    initClearanceColumnResizing();
    initClearanceFilters();
    if(document.getElementById('clearance_number')) generateAndSetClearanceNumber();
});

window.onclick = function(e) {
    if(e.target.classList && e.target.classList.contains('modal')) e.target.style.display = 'none';
    if(!e.target.closest('.user-avatar') && !e.target.closest('.user-dropdown')) { var dropdown = document.getElementById('userDropdown'); if(dropdown) dropdown.classList.remove('show'); }
}

(function() { 
    const sidebar = document.querySelector('.sidebar'); const body = document.body; const toggleBtn = document.getElementById('sidebarToggleBtn'); 
    if (!sidebar || !toggleBtn) return; 
    function toggleSidebar() { 
        sidebar.classList.toggle('collapsed'); 
        if (sidebar.classList.contains('collapsed')) { body.classList.add('sidebar-collapsed'); document.cookie = "sidebar_collapsed=true; path=/"; } 
        else { body.classList.remove('sidebar-collapsed'); document.cookie = "sidebar_collapsed=false; path=/"; } 
    } 
    toggleBtn.addEventListener('click', toggleSidebar); 
    if (document.cookie.indexOf('sidebar_collapsed=true') !== -1) { sidebar.classList.add('collapsed'); body.classList.add('sidebar-collapsed'); } 
    else { sidebar.classList.remove('collapsed'); body.classList.remove('sidebar-collapsed'); } 
})();
</script>

