<script>
// Add new data row to the form
function addNewDataRow() {
    const tbody = document.getElementById('addRowTbody');
    const firstRow = tbody.querySelector('.add-data-row');
    const newRow = firstRow.cloneNode(true);
    
    // Clear all input values in the new row
    const inputs = newRow.querySelectorAll('input');
    inputs.forEach(input => {
        input.value = '';
    });
    
    // Reset selects
    const selects = newRow.querySelectorAll('select');
    selects.forEach(select => {
        if (select.classList.contains('newYearSelect')) {
            select.value = '';
        } else if (select.classList.contains('newJobSelect')) {
            select.innerHTML = '<option value="">-- First select year --</option>';
            select.disabled = true;
        } else if (select.classList.contains('newStatus')) {
            select.value = 'Pending';
        } else if (select.classList.contains('newSoc')) {
            select.value = 'No';
        }
    });
    
    // Show the remove button
    const removeBtn = newRow.querySelector('.remove-row-btn');
    if (removeBtn) {
        removeBtn.style.display = 'inline-block';
    }
    
    tbody.appendChild(newRow);
    
    // Update remove buttons visibility
    updateRemoveButtons();
    
    // Focus on the year select of the new row - CURSOR stays in add table
    const yearSelect = newRow.querySelector('.newYearSelect');
    if (yearSelect) {
        yearSelect.focus();
    }
}

// Remove a row from the add form
function removeAddRow(btn) {
    const tbody = document.getElementById('addRowTbody');
    const rows = tbody.querySelectorAll('.add-data-row');
    if (rows.length <= 1) {
        return;
    }
    const row = btn.closest('tr');
    row.remove();
    updateRemoveButtons();
}

// Update remove buttons visibility
function updateRemoveButtons() {
    const tbody = document.getElementById('addRowTbody');
    const rows = tbody.querySelectorAll('.add-data-row');
    const removeBtns = tbody.querySelectorAll('.remove-row-btn');
    
    if (rows.length <= 1) {
        removeBtns.forEach(btn => btn.style.display = 'none');
    } else {
        removeBtns.forEach(btn => btn.style.display = 'inline-block');
    }
}

// Year dropdown inside add form – loads jobs for selected year
function loadJobsByYear(yearSelect) {
    const year = yearSelect.value;
    const row = yearSelect.closest('tr');
    const jobSelect = row.querySelector('.newJobSelect');
    
    if (!year) {
        jobSelect.innerHTML = '<option value="">-- First select year --</option>';
        jobSelect.disabled = true;
        return;
    }
    jobSelect.disabled = true;
    jobSelect.innerHTML = '<option value="">Loading jobs...</option>';
    
    fetch(`system.php?page=get-jobs-by-year&year=${year}`)
        .then(response => response.json())
        .then(data => {
            if (data.success && data.jobs) {
                jobSelect.innerHTML = '<option value="">-- Select Job --</option>';
                data.jobs.forEach(job => {
                    const option = document.createElement('option');
                    option.value = job.id;
                    option.textContent = job.job_number;
                    option.setAttribute('data-customer-name', job.customer_name || '');
                    option.setAttribute('data-bonded-carrier', job.bonded_carrier || '');
                    option.setAttribute('data-consignee', job.consignee || '');
                    option.setAttribute('data-dry-port', job.dry_port || '');
                    option.setAttribute('data-container-size', job.container_size || '');
                    option.setAttribute('data-container-number', job.container_number || '');
                    option.setAttribute('data-shipping-line', job.shipping_line || '');
                    option.setAttribute('data-vessel-arrival', job.vessel_arrival_date || '');
                    option.setAttribute('data-soc', job.soc || 'No');
                    jobSelect.appendChild(option);
                });
                jobSelect.disabled = false;
            } else {
                jobSelect.innerHTML = '<option value="">-- No jobs --</option>';
                jobSelect.disabled = true;
            }
        })
        .catch(error => {
            console.error('Error loading jobs:', error);
            jobSelect.innerHTML = '<option value="">-- Error loading --</option>';
            jobSelect.disabled = true;
        });
}

// Auto-fill row fields when job is selected
function autoFillRow(jobSelect) {
    const selectedOption = jobSelect.options[jobSelect.selectedIndex];
    const row = jobSelect.closest('tr');
    
    if (selectedOption && selectedOption.value) {
        row.querySelector('.newClearingAgent').value = selectedOption.getAttribute('data-customer-name') || '';
        row.querySelector('.newBondedCarrier').value = selectedOption.getAttribute('data-bonded-carrier') || '';
        row.querySelector('.newImporter').value = selectedOption.getAttribute('data-consignee') || '';
        row.querySelector('.newDryPort').value = selectedOption.getAttribute('data-dry-port') || '';
        row.querySelector('.newContainerSize').value = selectedOption.getAttribute('data-container-size') || '';
        row.querySelector('.newContainerNo').value = selectedOption.getAttribute('data-container-number') || '';
        row.querySelector('.newShippingLine').value = selectedOption.getAttribute('data-shipping-line') || '';
        row.querySelector('.newVesselArrival').value = selectedOption.getAttribute('data-vessel-arrival') || '';
        row.querySelector('.newSoc').value = selectedOption.getAttribute('data-soc') || 'No';
    }
}

function toggleAddTable() {
    const container = document.getElementById('addNewRowContainer');
    const addBtn = document.getElementById('addNewRowBtn');
    
    if (container.style.display === 'none' || !container.style.display) {
        container.style.display = 'block';
        addBtn.innerHTML = '<i class="fas fa-times"></i> Close Form';
        addBtn.style.background = '#dc3545';
        
        // Reset all rows to just one empty row
        const tbody = document.getElementById('addRowTbody');
        const firstRow = tbody.querySelector('.add-data-row');
        
        // Remove all rows except the first one
        const allRows = tbody.querySelectorAll('.add-data-row');
        for (let i = 1; i < allRows.length; i++) {
            allRows[i].remove();
        }
        
        // Reset the first row
        const inputs = firstRow.querySelectorAll('input');
        inputs.forEach(input => input.value = '');
        const selects = firstRow.querySelectorAll('select');
        selects.forEach(select => {
            if (select.classList.contains('newYearSelect')) {
                select.value = '';
            } else if (select.classList.contains('newJobSelect')) {
                select.innerHTML = '<option value="">-- First select year --</option>';
                select.disabled = true;
            } else if (select.classList.contains('newStatus')) {
                select.value = 'Pending';
            } else if (select.classList.contains('newSoc')) {
                select.value = 'No';
            }
        });
        
        // Hide remove button on first row
        const removeBtn = firstRow.querySelector('.remove-row-btn');
        if (removeBtn) removeBtn.style.display = 'none';
        
        // Focus on year select of first row
        const yearSelect = firstRow.querySelector('.newYearSelect');
        if (yearSelect) {
            setTimeout(() => yearSelect.focus(), 300);
        }
    } else {
        container.style.display = 'none';
        addBtn.innerHTML = '<i class="fas fa-plus-circle"></i> Add New Row';
        addBtn.style.background = '#8e181e';
    }
}

// Save all rows one by one using existing endpoint
async function saveAllRows() {
    const tbody = document.getElementById('addRowTbody');
    const rows = tbody.querySelectorAll('.add-data-row');
    
    // Validate all rows first
    let hasError = false;
    const allRowData = [];
    
    for (let i = 0; i < rows.length; i++) {
        const row = rows[i];
        const jobSelect = row.querySelector('.newJobSelect');
        const jobId = jobSelect.value;
        
        if (!jobId) {
            // Highlight the empty job select
            jobSelect.style.border = '2px solid red';
            setTimeout(() => { jobSelect.style.border = '1px solid #c8e6c9'; }, 2000);
            hasError = true;
            break;
        }
        
        // Get file creation date - sirf date, time nahi
        let createdAt = row.querySelector('.newCreatedAt').value;
        if (!createdAt) {
            // Agar date select nahi ki to aaj ki date use karein
            const now = new Date();
            createdAt = now.toISOString().slice(0, 10);
        }
        
        const formData = new FormData();
        formData.append('id', '');
        formData.append('job_id', jobId);
        formData.append('clearing_agent', row.querySelector('.newClearingAgent').value);
        formData.append('bonded_carrier', row.querySelector('.newBondedCarrier').value);
        formData.append('importer', row.querySelector('.newImporter').value);
        formData.append('dry_port', row.querySelector('.newDryPort').value);
        formData.append('container_size', row.querySelector('.newContainerSize').value);
        formData.append('container_no', row.querySelector('.newContainerNo').value);
        formData.append('shipping_line', row.querySelector('.newShippingLine').value);
        formData.append('free_days', row.querySelector('.newFreeDays').value);
        formData.append('vessel_arrival', row.querySelector('.newVesselArrival').value);
        formData.append('loading_date', row.querySelector('.newLoadingDate').value);
        formData.append('created_at', createdAt);
        formData.append('lahore_arrival', row.querySelector('.newLahoreArrival').value);
        formData.append('status', row.querySelector('.newStatus').value);
        formData.append('vehicles_no', row.querySelector('.newVehiclesNo').value);
        formData.append('trucker_cell', row.querySelector('.newTruckerCell').value);
        formData.append('soc', row.querySelector('.newSoc').value);
        
        allRowData.push(formData);
    }
    
    if (hasError || allRowData.length === 0) return;
    
    const saveBtn = document.querySelector('.save-all-btn');
    const originalText = saveBtn.innerHTML;
    saveBtn.disabled = true;
    
    // Save each row one by one silently
    for (let i = 0; i < allRowData.length; i++) {
        saveBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving ' + (i + 1) + '/' + allRowData.length + '...';
        
        try {
            await fetch('system.php?page=save-loading-file-ajax', {
                method: 'POST',
                body: allRowData[i]
            });
        } catch (error) {
            console.error('Error saving row ' + (i + 1) + ':', error);
        }
    }
    
    // Save complete - page reload
    saveBtn.innerHTML = '<i class="fas fa-check"></i> Saved! Reloading...';
    setTimeout(() => {
        window.location.href = 'system.php?page=loading-files#pageTop';
        window.location.reload();
    }, 300);
}

function editLoadingRow(id) {
    fetch(`system.php?page=get-loading-file&id=${id}`)
        .then(response => response.json())
        .then(data => {
            document.getElementById('edit_id').value = data.id;
            document.getElementById('edit_job_id').value = data.job_id;
            document.getElementById('edit_clearing_agent').value = data.clearing_agent || '';
            document.getElementById('edit_bonded_carrier').value = data.bonded_carrier || '';
            document.getElementById('edit_importer').value = data.importer || '';
            document.getElementById('edit_dry_port').value = data.dry_port || '';
            document.getElementById('edit_container_size').value = data.container_size || '';
            document.getElementById('edit_container_no').value = data.container_no || '';
            document.getElementById('edit_shipping_line').value = data.shipping_line || '';
            document.getElementById('edit_free_days').value = data.free_days || '';
            document.getElementById('edit_vessel_arrival').value = data.vessel_arrival || '';
            document.getElementById('edit_loading_date').value = data.loading_date || '';
            document.getElementById('edit_lahore_arrival').value = data.lahore_arrival || '';
            document.getElementById('edit_status').value = data.status || 'Pending';
            document.getElementById('edit_vehicles_no').value = data.vehicles_no || '';
            document.getElementById('edit_trucker_cell').value = data.trucker_cell || '';
            document.getElementById('edit_soc').value = data.soc || 'No';
            document.getElementById('editLoadingModal').style.display = 'flex';
        });
}

function closeEditModal() {
    document.getElementById('editLoadingModal').style.display = 'none';
}

function deleteLoading(id) {
    if (confirm('Are you sure you want to delete this record?')) {
        fetch(`system.php?page=delete-loading-file-ajax&id=${id}`)
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    location.reload();
                } else {
                    alert('Error deleting record');
                }
            });
    }
}

function applyLoadingDateFilter() { 
    let startDate = document.getElementById('loading_start_date').value; 
    let endDate = document.getElementById('loading_end_date').value; 
    if(startDate && endDate) { 
        window.location.href = 'system.php?page=loading-files&start_date=' + startDate + '&end_date=' + endDate; 
    } else { 
        alert('Please select both start and end dates'); 
    } 
}

function clearLoadingDateFilter() { 
    window.location.href = 'system.php?page=loading-files'; 
}

function searchLoading() {
    let input = document.getElementById('loadingSearch');
    let filter = input.value.toLowerCase();
    let tables = document.querySelectorAll('#groupedTablesContainer .jobs-google-sheets-table');
    
    tables.forEach(table => {
        let rows = table.querySelectorAll('tbody tr');
        let hasVisible = false;
        rows.forEach(row => {
            let text = row.textContent.toLowerCase();
            if (text.includes(filter)) {
                row.style.display = '';
                hasVisible = true;
            } else {
                row.style.display = 'none';
            }
        });
        let card = table.closest('.card');
        if (card) {
            card.style.display = hasVisible ? '' : 'none';
        }
    });
}

function toggleUserDropdown() { var dropdown = document.getElementById('userDropdown'); if(dropdown) dropdown.classList.toggle('show'); }
function openProfileModal() { document.getElementById('profileModal').style.display = 'flex'; var dropdown = document.getElementById('userDropdown'); if(dropdown) dropdown.classList.remove('show'); }
function closeProfileModal() { document.getElementById('profileModal').style.display = 'none'; }

window.onclick = function(e) {
    if(e.target.classList && e.target.classList.contains('modal')) e.target.style.display = 'none';
    if(!e.target.closest('.user-avatar') && !e.target.closest('.user-dropdown')) {
        var dropdown = document.getElementById('userDropdown');
        if(dropdown) dropdown.classList.remove('show');
    }
}

(function() { 
    const sidebar = document.querySelector('.sidebar'); 
    const body = document.body; 
    const toggleBtn = document.getElementById('sidebarToggleBtn'); 
    if (!sidebar || !toggleBtn) return; 
    function toggleSidebar() { 
        sidebar.classList.toggle('collapsed'); 
        if (sidebar.classList.contains('collapsed')) { 
            body.classList.add('sidebar-collapsed'); 
            document.cookie = "sidebar_collapsed=true; path=/"; 
        } else { 
            body.classList.remove('sidebar-collapsed'); 
            document.cookie = "sidebar_collapsed=false; path=/"; 
        } 
    } 
    toggleBtn.addEventListener('click', toggleSidebar); 
    if (document.cookie.indexOf('sidebar_collapsed=true') !== -1) { 
        sidebar.classList.add('collapsed'); 
        body.classList.add('sidebar-collapsed'); 
    } else { 
        sidebar.classList.remove('collapsed'); 
        body.classList.remove('sidebar-collapsed'); 
    } 
})();

// Page load hone par cursor top par set karein
document.addEventListener('DOMContentLoaded', function() {
    const pageTop = document.getElementById('pageTop');
    if (pageTop) {
        pageTop.scrollIntoView({ behavior: 'auto', block: 'start' });
    } else {
        const mainContent = document.getElementById('mainContentTop');
        if (mainContent) {
            mainContent.scrollIntoView({ behavior: 'auto', block: 'start' });
        } else {
            window.scrollTo({ top: 0, behavior: 'auto' });
        }
    }
});
</script>

