function searchFolders() {
    var input = document.getElementById('folderSearch');
    var filter = input.value.toLowerCase();
    var folderCards = document.querySelectorAll('.folder-card');
    var searchResults = document.getElementById('searchResults');
    var folderCount = document.getElementById('folderCount');

    var visibleCount = 0;

    folderCards.forEach(function(card) {
        var folderName = card.getAttribute('data-folder-name').toLowerCase();

        if (folderName.indexOf(filter) > -1) {
            card.style.display = '';
            visibleCount++;
        } else {
            card.style.display = 'none';
        }
    });

    // Update badge count
    folderCount.textContent = visibleCount;

    if (filter.length > 0) {
        searchResults.innerHTML =
            'Found ' + visibleCount + ' folder(s) matching "' + filter + '"';
    } else {
        searchResults.innerHTML = '';
    }
}

