<?php elseif ($page == 'view-invoice' && isset($_GET['path'])): ?>
<?php
error_reporting(E_ALL);
ini_set('display_errors', 1);

$invoice_path = $_GET['path'];
$full_path = __DIR__ . '/invoices/' . $invoice_path;

if (!file_exists($full_path)) {
    echo '<h2>File not found: ' . htmlspecialchars($invoice_path) . '</h2>';
    echo '<a href="system.php?page=invoices">Back to Invoices</a>';
    exit;
}

// Extract bill ID from filename: Forwarding-BILL-001-15.pdf -> 15
$filename = basename($invoice_path);
$filename_no_ext = pathinfo($filename, PATHINFO_FILENAME);

// Try to extract bill ID from filename (format: PREFIX-BILLNUMBER-ID.pdf)
$bill_id = null;
if (preg_match('/-(\d+)$/', $filename_no_ext, $matches)) {
    $bill_id = $matches[1];
}

// If can't extract from filename, try to find by bill number
$bill = null;
if ($bill_id) {
    // ========== FIXED QUERY: Explicitly select consignee and customer_name from jobs ==========
    $stmt = $pdo->prepare("SELECT b.*, j.consignee as job_consignee, j.customer_name as job_customer_name, j.job_date, j.vessel_arrival_date, j.vessel_name,
        j.bl_number, j.container_number, j.container_size, j.dry_port, j.port_of_discharge,
        j.shipping_line, j.free_time, j.soc, j.description, j.free_till,
        j.bonded_carrier, j.freight_forwarder_name, j.ntn, j.st_no, j.job_number
        FROM bills b LEFT JOIN jobs j ON b.job_id = j.id WHERE b.id = ?");
    $stmt->execute([$bill_id]);
    $bill = $stmt->fetch();
    
    // If customer_name is empty in bill, use the one from jobs
    if ($bill && empty($bill['customer_name'])) {
        $bill['customer_name'] = $bill['job_customer_name'] ?? '';
    }
    
    // If consignee is empty in bill, use the one from jobs
    if ($bill && empty($bill['consignee'])) {
        $bill['consignee'] = $bill['job_consignee'] ?? '';
    }
}

// Fallback: try by bill_number
if (!$bill) {
    $bill_number = preg_replace('/^(Forwarding-|Detention-|Revised-|Original-)/i', '', $filename_no_ext);
    $bill_number = preg_replace('/-\d+$/', '', $bill_number);
    
    $stmt = $pdo->prepare("SELECT b.*, j.consignee as job_consignee, j.customer_name as job_customer_name, j.job_date, j.vessel_arrival_date, j.vessel_name,
        j.bl_number, j.container_number, j.container_size, j.dry_port, j.port_of_discharge,
        j.shipping_line, j.free_time, j.soc, j.description, j.free_till,
        j.bonded_carrier, j.freight_forwarder_name, j.ntn, j.st_no, j.job_number
        FROM bills b LEFT JOIN jobs j ON b.job_id = j.id WHERE b.bill_number = ?");
    $stmt->execute([$bill_number]);
    $bill = $stmt->fetch();
    
    if ($bill && empty($bill['customer_name'])) {
        $bill['customer_name'] = $bill['job_customer_name'] ?? '';
    }
    
    if ($bill && empty($bill['consignee'])) {
        $bill['consignee'] = $bill['job_consignee'] ?? '';
    }
}

if (!$bill) {
    echo '<div style="padding:20px; background:#fff3cd; margin:20px;">';
    echo '<h3>Bill not found in database</h3>';
    echo '<p>Filename: ' . htmlspecialchars($filename) . '</p>';
    echo '<p>Extracted Bill ID: ' . ($bill_id ?? 'N/A') . '</p>';
    echo '<p>Extracted Bill Number: ' . ($bill_number ?? 'N/A') . '</p>';
    
    // Debug: Show recent bills
    $allBills = $pdo->query("SELECT id, bill_number, customer_name FROM bills ORDER BY id DESC LIMIT 10")->fetchAll();
    echo '<p><strong>Recent bills in database:</strong></p><ul>';
    foreach($allBills as $b) {
        echo '<li>ID: ' . $b['id'] . ' | Bill#: ' . htmlspecialchars($b['bill_number']) . ' | Customer: ' . htmlspecialchars($b['customer_name']) . '</li>';
    }
    echo '</ul>';
    echo '<a href="system.php?page=invoices">Back to Invoices</a>';
    echo '</div>';
    exit;
}

// DIRECT DATABASE CHECK FOR CUSTOMER NAME - Multiple fallbacks
if (empty($bill['customer_name']) && !empty($bill['id'])) {
    // First try: Direct check in bills table
    $checkStmt = $pdo->prepare("SELECT customer_name FROM bills WHERE id = ?");
    $checkStmt->execute([$bill['id']]);
    $directBillCustomer = $checkStmt->fetchColumn();
    if ($directBillCustomer && !empty($directBillCustomer)) {
        $bill['customer_name'] = $directBillCustomer;
    } else {
        // Second try: Check in jobs table through bill's job_id
        $jobStmt = $pdo->prepare("SELECT j.customer_name FROM jobs j JOIN bills b ON b.job_id = j.id WHERE b.id = ?");
        $jobStmt->execute([$bill['id']]);
        $jobCustomer = $jobStmt->fetchColumn();
        if ($jobCustomer && !empty($jobCustomer)) {
            $bill['customer_name'] = $jobCustomer;
        } else {
            // Third try: Get job_id first then check jobs table
            $jobIdStmt = $pdo->prepare("SELECT job_id FROM bills WHERE id = ?");
            $jobIdStmt->execute([$bill['id']]);
            $jobId = $jobIdStmt->fetchColumn();
            if ($jobId) {
                $directJobStmt = $pdo->prepare("SELECT customer_name FROM jobs WHERE id = ?");
                $directJobStmt->execute([$jobId]);
                $directJobCustomer = $directJobStmt->fetchColumn();
                if ($directJobCustomer && !empty($directJobCustomer)) {
                    $bill['customer_name'] = $directJobCustomer;
                }
            }
        }
    }
}

// Same check for consignee
if (empty($bill['consignee']) && !empty($bill['id'])) {
    $checkConsigneeStmt = $pdo->prepare("SELECT consignee FROM bills WHERE id = ?");
    $checkConsigneeStmt->execute([$bill['id']]);
    $directBillConsignee = $checkConsigneeStmt->fetchColumn();
    if ($directBillConsignee && !empty($directBillConsignee)) {
        $bill['consignee'] = $directBillConsignee;
    } else {
        $jobConsigneeStmt = $pdo->prepare("SELECT j.consignee FROM jobs j JOIN bills b ON b.job_id = j.id WHERE b.id = ?");
        $jobConsigneeStmt->execute([$bill['id']]);
        $jobConsignee = $jobConsigneeStmt->fetchColumn();
        if ($jobConsignee && !empty($jobConsignee)) {
            $bill['consignee'] = $jobConsignee;
        }
    }
}

// GET BILL ITEMS
$stmt_items = $pdo->prepare("SELECT * FROM bill_items WHERE bill_id = ? ORDER BY sort_order ASC");
$stmt_items->execute([$bill['id']]);
$bill_items = $stmt_items->fetchAll();

// Fetch consignee NTN and ST No for icons
$consigneeNtn = '';
$consigneeStNo = '';
if (!empty($bill['consignee'])) {
    $stmtConsignee = $pdo->prepare("SELECT ntn, st_no FROM masters WHERE type = 'consignee' AND name = ? LIMIT 1");
    $stmtConsignee->execute([$bill['consignee']]);
    $consigneeData = $stmtConsignee->fetch();
    if ($consigneeData) {
        $consigneeNtn = $consigneeData['ntn'] ?? '';
        $consigneeStNo = $consigneeData['st_no'] ?? '';
    }
}

// Free time calculation
$freeTimeRemaining = '';
if (!empty($bill['free_time']) && !empty($bill['vessel_arrival_date'])) {
    $freeTimeDays = intval($bill['free_time']);
    $vesselArrival = new DateTime($bill['vessel_arrival_date']);
    $freeTimeEnd = clone $vesselArrival;
    $freeTimeEnd->modify("+{$freeTimeDays} days");
    $today = new DateTime();
    $remaining = $today->diff($freeTimeEnd);
    $remainingDays = $remaining->days;
    $freeTimeRemaining = ($today > $freeTimeEnd) ? $remainingDays . " day(s) ago" : $remainingDays . " day(s) remaining";
}

$freeTillValue = $bill['free_till'] ?? '';
if (empty($freeTillValue) && !empty($bill['job_id'])) {
    $stmtFt = $pdo->prepare("SELECT free_till FROM jobs WHERE id = ?");
    $stmtFt->execute([$bill['job_id']]);
    $freeTillValue = $stmtFt->fetchColumn();
}
if (empty($freeTillValue)) $freeTillValue = '-';
