<script>
function openUserModal() { document.getElementById('userModal').style.display = 'flex'; }
function closeUserModal() { document.getElementById('userModal').style.display = 'none'; }

function openEditUserModal(id, n, e, p, r) { 
    document.getElementById('edit_user_id').value = id; 
    document.getElementById('edit_full_name').value = n; 
    document.getElementById('edit_email').value = e; 
    document.getElementById('edit_phone').value = p; 
    document.getElementById('edit_role').value = r; 
    document.getElementById('editUserModal').style.display = 'flex'; 
}
function closeEditUserModal() { document.getElementById('editUserModal').style.display = 'none'; }

// NEW: Password change functions
function openChangePasswordModal(userId, fullName) {
    document.getElementById('change_pwd_user_id').value = userId;
    document.getElementById('change_pwd_user_name').textContent = fullName;
    document.getElementById('new_password').value = '';
    document.getElementById('confirm_password').value = '';
    document.getElementById('changeUserPasswordModal').style.display = 'flex';
}
function closeChangePasswordModal() { document.getElementById('changeUserPasswordModal').style.display = 'none'; }

function globalSearchUsers() {
    let input = document.getElementById('globalUserSearch');
    let filter = input.value.toLowerCase();
    let table = document.getElementById('usersTable');
    let rows = table.getElementsByTagName('tr');
    for(let i = 2; i < rows.length; i++) {
        let text = rows[i].textContent.toLowerCase();
        rows[i].style.display = text.includes(filter) ? '' : 'none';
    }
}

function initUserColumnFilters() {
    var filters = document.querySelectorAll('#usersTable .col-filter');
    filters.forEach(function(filter) {
        filter.addEventListener('keyup', function() {
            var colIndex = parseInt(this.dataset.col);
            var filterValue = this.value.toLowerCase();
            var table = document.getElementById('usersTable');
            var rows = table.querySelectorAll('tbody tr');
            
            for(var i = 0; i < rows.length; i++) {
                var row = rows[i];
                if(row.querySelector('td[colspan]')) continue;
                var cell = row.children[colIndex];
                if(cell) {
                    var cellText = cell.textContent.toLowerCase();
                    row.style.display = cellText.includes(filterValue) ? '' : 'none';
                }
            }
        });
    });
}

function initUsersSorting() {
    var headers = document.querySelectorAll('#usersTable th.sortable');
    var currentSortColumn = null;
    var currentSortDirection = 'asc';
    
    headers.forEach(function(header) {
        header.addEventListener('click', function(e) {
            if(e.target.classList && e.target.classList.contains('col-filter')) return;
            
            var column = parseInt(this.dataset.column);
            var table = this.closest('#usersTable');
            var tbody = table.querySelector('tbody');
            var rows = Array.from(tbody.querySelectorAll('tr'));
            
            if (rows.length === 1 && rows[0].querySelector('td[colspan]')) return;
            
            headers.forEach(function(h) {
                h.classList.remove('asc', 'desc');
            });
            
            if (currentSortColumn === column) {
                currentSortDirection = currentSortDirection === 'asc' ? 'desc' : 'asc';
            } else {
                currentSortColumn = column;
                currentSortDirection = 'asc';
            }
            
            this.classList.add(currentSortDirection);
            
            rows.sort(function(a, b) {
                var aValue = a.children[column] ? a.children[column].innerText.trim() : '';
                var bValue = b.children[column] ? b.children[column].innerText.trim() : '';
                
                var aNum = parseFloat(aValue.replace(/[^0-9.-]/g, ''));
                var bNum = parseFloat(bValue.replace(/[^0-9.-]/g, ''));
                
                if (!isNaN(aNum) && !isNaN(bNum)) {
                    return currentSortDirection === 'asc' ? aNum - bNum : bNum - aNum;
                }
                
                aValue = aValue.toLowerCase();
                bValue = bValue.toLowerCase();
                
                if (currentSortDirection === 'asc') {
                    return aValue.localeCompare(bValue);
                } else {
                    return bValue.localeCompare(aValue);
                }
            });
            
            rows.forEach(function(row) {
                tbody.appendChild(row);
            });
        });
    });
}

document.addEventListener('DOMContentLoaded', function() {
    initUsersSorting();
    initUserColumnFilters();
});

function toggleUserDropdown() { var dropdown = document.getElementById('userDropdown'); dropdown.classList.toggle('show'); }
function openProfileModal() { document.getElementById('profileModal').style.display = 'flex'; document.getElementById('userDropdown').classList.remove('show'); }
function closeProfileModal() { document.getElementById('profileModal').style.display = 'none'; }

window.onclick = function(e) { 
    if(e.target.classList && e.target.classList.contains('modal')) { 
        e.target.style.display = 'none'; 
    } 
    if(!e.target.closest('.user-avatar') && !e.target.closest('.user-dropdown')) { 
        var dropdown = document.getElementById('userDropdown'); 
        if(dropdown) dropdown.classList.remove('show'); 
    } 
}

(function() { 
    const sidebar = document.querySelector('.sidebar'); 
    const body = document.body; 
    const toggleBtn = document.getElementById('sidebarToggleBtn'); 
    if (!sidebar || !toggleBtn) return; 
    function toggleSidebar() { 
        sidebar.classList.toggle('collapsed'); 
        if (sidebar.classList.contains('collapsed')) { 
            body.classList.add('sidebar-collapsed'); 
            document.cookie = "sidebar_collapsed=true; path=/"; 
        } else { 
            body.classList.remove('sidebar-collapsed'); 
            document.cookie = "sidebar_collapsed=false; path=/"; 
        } 
    } 
    toggleBtn.addEventListener('click', toggleSidebar); 
    if (document.cookie.indexOf('sidebar_collapsed=true') !== -1) { 
        sidebar.classList.add('collapsed'); 
        body.classList.add('sidebar-collapsed'); 
    } else { 
        sidebar.classList.remove('collapsed'); 
        body.classList.remove('sidebar-collapsed'); 
    } 
})();
</script>

