<script>
// ==================== JOBS SCRIPTS ====================
function toggleCustomerJobs(customerId) {
    var jobsRow = document.getElementById('jobs_' + customerId);
    var icon = document.getElementById('icon_' + customerId);
    if (jobsRow.classList.contains('show')) { jobsRow.classList.remove('show'); icon.classList.remove('expanded'); }
    else { jobsRow.classList.add('show'); icon.classList.add('expanded'); }
}
function toggleCustomerCheckbox(customerId, isChecked) {
    document.querySelectorAll('.job-' + customerId).forEach(function(cb) { cb.checked = isChecked; });
    updateSelectedCount(); updateSelectAllCheckbox();
}
function updateJobCheckboxStatus(customerId) {
    var checkboxes = document.querySelectorAll('.job-' + customerId);
    var customerCheckbox = document.querySelector('.customer-checkbox[data-customer-id="' + customerId + '"]');
    if (customerCheckbox && checkboxes.length > 0) {
        var allChecked = true, anyChecked = false;
        checkboxes.forEach(function(cb) { if (cb.checked) anyChecked = true; else allChecked = false; });
        if (allChecked) { customerCheckbox.checked = true; customerCheckbox.indeterminate = false; }
        else if (anyChecked) { customerCheckbox.checked = false; customerCheckbox.indeterminate = true; }
        else { customerCheckbox.checked = false; customerCheckbox.indeterminate = false; }
    }
    updateSelectedCount(); updateSelectAllCheckbox();
}
function grantCustomerJobs(customerName, jobIds) { if (!confirm('Grant permission for ALL jobs of customer "' + customerName + '"?')) return; processBatch('grant', jobIds); }
function revokeCustomerJobs(customerName, jobIds) { if (!confirm('Revoke permission for ALL jobs of customer "' + customerName + '"?')) return; processBatch('revoke', jobIds); }

var columnFilters = {}, filterTimeout = null;
function applyColumnFilters() {
    clearTimeout(filterTimeout);
    filterTimeout = setTimeout(function() {
        var filters = document.querySelectorAll('#jobsTab .col-filter'), activeFilterCount = 0;
        columnFilters = {};
        filters.forEach(function(filter) {
            var colIndex = parseInt(filter.dataset.col), filterValue = filter.value.trim().toLowerCase();
            if (filterValue !== '') { columnFilters[colIndex] = filterValue; filter.classList.add('active-filter'); activeFilterCount++; }
            else { filter.classList.remove('active-filter'); }
        });
        document.getElementById('activeFilterCount').textContent = activeFilterCount;
        document.getElementById('searchInfoBar').style.display = activeFilterCount > 0 ? 'flex' : 'none';
        filterTableRows(); updateSelectedCount(); updateSelectAllCheckbox();
    }, 300);
}
function filterTableRows() {
    var rows = document.querySelectorAll('#permissionsTableBody tr.customer-group-row'), visibleCount = 0;
    rows.forEach(function(row) {
        var showRow = true;
        for (var colIndex in columnFilters) {
            var filterValue = columnFilters[colIndex];
            var cellClass = parseInt(colIndex) === 1 ? 'col-customer' : 'col-permission';
            var cell = row.querySelector('.' + cellClass);
            if (cell) {
                var cellText = cell.textContent.trim().toLowerCase();
                cell.innerHTML = cell.innerHTML.replace(/<span class="search-highlight">(.*?)<\/span>/g, '$1');
                if (!cellText.includes(filterValue)) { showRow = false; break; }
                else if (filterValue !== '') { var regex = new RegExp('(' + escapeRegex(filterValue) + ')', 'gi'); cell.innerHTML = cell.innerHTML.replace(regex, '<span class="search-highlight">$1</span>'); }
            }
        }
        var customerId = row.dataset.customerId, detailRow = document.getElementById('jobs_' + customerId);
        if (showRow) { row.style.display = ''; if (detailRow) { detailRow.style.display = detailRow.classList.contains('show') ? '' : 'none'; } visibleCount++; }
        else { row.style.display = 'none'; if (detailRow) detailRow.style.display = 'none'; }
    });
    document.getElementById('filteredCountDisplay').textContent = visibleCount + ' customer(s) visible';
}
function escapeRegex(string) { return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function clearAllFilters() {
    document.querySelectorAll('#jobsTab .col-filter').forEach(function(f) { f.value = ''; f.classList.remove('active-filter'); });
    columnFilters = {}; document.getElementById('searchInfoBar').style.display = 'none'; document.getElementById('activeFilterCount').textContent = '0';
    document.querySelectorAll('#permissionsTableBody tr.customer-group-row').forEach(function(row) {
        row.style.display = ''; row.innerHTML = row.innerHTML.replace(/<span class="search-highlight">(.*?)<\/span>/g, '$1');
        var detailRow = document.getElementById('jobs_' + row.dataset.customerId);
        if (detailRow && !detailRow.classList.contains('show')) detailRow.style.display = 'none';
    });
    var totalCustomers = document.querySelectorAll('#permissionsTableBody tr.customer-group-row').length;
    document.getElementById('filteredCountDisplay').textContent = totalCustomers + ' customer(s) visible';
    updateSelectedCount(); updateSelectAllCheckbox();
}
function updateSelectedCount() { document.getElementById('selectedCount').innerHTML = document.querySelectorAll('#jobsTab .job-checkbox:checked').length + ' job(s) selected'; }
function updateSelectAllCheckbox() {
    var selectAll = document.getElementById('selectAllCheckbox'), all = document.querySelectorAll('#jobsTab .job-checkbox'), checked = document.querySelectorAll('#jobsTab .job-checkbox:checked');
    if (all.length === 0) { selectAll.checked = false; selectAll.indeterminate = false; }
    else if (checked.length === 0) { selectAll.checked = false; selectAll.indeterminate = false; }
    else if (checked.length === all.length) { selectAll.checked = true; selectAll.indeterminate = false; }
    else { selectAll.checked = false; selectAll.indeterminate = true; }
}
function toggleSelectAll() { document.querySelectorAll('#jobsTab .job-checkbox').forEach(function(cb) { cb.checked = true; }); document.querySelectorAll('#jobsTab .customer-checkbox').forEach(function(cb) { cb.checked = true; cb.indeterminate = false; }); updateSelectedCount(); updateSelectAllCheckbox(); }
function deselectAll() { document.querySelectorAll('#jobsTab .job-checkbox').forEach(function(cb) { cb.checked = false; }); document.querySelectorAll('#jobsTab .customer-checkbox').forEach(function(cb) { cb.checked = false; cb.indeterminate = false; }); updateSelectedCount(); updateSelectAllCheckbox(); }
function toggleSelectAllFromCheckbox() { var s = document.getElementById('selectAllCheckbox'); document.querySelectorAll('#jobsTab .job-checkbox').forEach(function(cb) { cb.checked = s.checked; }); document.querySelectorAll('#jobsTab .customer-checkbox').forEach(function(cb) { cb.checked = s.checked; cb.indeterminate = false; }); updateSelectedCount(); }
async function bulkGrantPermissions() { var ids = Array.from(document.querySelectorAll('#jobsTab .job-checkbox:checked')).map(cb => cb.value); if(ids.length===0){alert('Please select at least one job!');return;} if(!confirm('Grant permissions for '+ids.length+' selected job(s)?'))return; await processBatch('grant', ids); }
async function bulkRevokePermissions() { var ids = Array.from(document.querySelectorAll('#jobsTab .job-checkbox:checked')).map(cb => cb.value); if(ids.length===0){alert('Please select at least one job!');return;} if(!confirm('Revoke permissions for '+ids.length+' selected job(s)?'))return; await processBatch('revoke', ids); }

async function processBatch(action, allJobIds) {
    var userId = document.querySelector('input[name="user_id"]').value, batchSize = 500, totalBatches = Math.ceil(allJobIds.length / batchSize), totalProcessed = 0, totalSuccess = 0;
    var overlay = document.createElement('div'); overlay.className = 'loading-overlay'; overlay.id = 'loadingOverlay';
    var loadingBox = document.createElement('div'); loadingBox.className = 'loading-box';
    var actionText = action === 'grant' ? 'Granting' : 'Revoking';
    loadingBox.innerHTML = '<h3 style="margin-bottom:15px;color:#333;"><i class="fas fa-spinner fa-spin"></i> ' + actionText + ' Permissions...</h3><div class="progress-container"><div class="progress-bar" id="progressBar">0%</div></div><p id="progressText" style="color:#666;">Preparing batches...</p><p style="color:#999;font-size:12px;">Total jobs: ' + allJobIds.length + ' | Batch size: ' + batchSize + '</p>';
    overlay.appendChild(loadingBox); document.body.appendChild(overlay);
    var buttons = document.querySelectorAll('button, a.btn-danger, a.btn-success');
    buttons.forEach(function(btn) { btn.disabled = true; if(btn.style) btn.style.pointerEvents = 'none'; });
    for (var i = 0; i < totalBatches; i++) {
        var batch = allJobIds.slice(i * batchSize, (i + 1) * batchSize);
        var formData = new FormData(); formData.append('user_id', userId); batch.forEach(function(id) { formData.append('job_ids[]', id); });
        var url = action === 'grant' ? 'system.php?page=bulk-grant-permissions' : 'system.php?page=bulk-revoke-permissions';
        try {
            var response = await fetch(url, { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest' } });
            var result = await response.json();
            if (result.success) { totalProcessed += result.total; totalSuccess += (action === 'grant' ? result.granted : result.revoked); var pct = Math.round(((i + 1) / totalBatches) * 100); document.getElementById('progressBar').style.width = pct + '%'; document.getElementById('progressBar').innerHTML = pct + '%'; document.getElementById('progressText').innerHTML = 'Processing batch ' + (i + 1) + ' of ' + totalBatches + '...<br><strong>' + totalSuccess + '</strong> ' + action + 'ed'; }
        } catch (error) { console.error('Batch error:', error); }
    }
    setTimeout(function() { document.body.removeChild(overlay); buttons.forEach(function(btn) { btn.disabled = false; if(btn.style) btn.style.pointerEvents = ''; }); alert('Operation completed!\nSuccessfully ' + action + 'ed: ' + totalSuccess + ' out of ' + allJobIds.length + ' job(s)'); location.reload(); }, 500);
}

