        for (var colIndex in columnFiltersClearance) { var fv = columnFiltersClearance[colIndex], cc = parseInt(colIndex) === 1 ? 'col-shipper-clearance' : 'col-permission-clearance', cell = row.querySelector('.' + cc); if (cell) { var cellText = cell.textContent.trim().toLowerCase(); cell.innerHTML = cell.innerHTML.replace(/<span class="search-highlight">(.*?)<\/span>/g, '$1'); if (!cellText.includes(fv)) { showRow = false; break; } else if (fv !== '') { var regex = new RegExp('(' + escapeRegexClearance(fv) + ')', 'gi'); cell.innerHTML = cell.innerHTML.replace(regex, '<span class="search-highlight">$1</span>'); } } }
        var shipperId = row.dataset.shipperId, detailRow = document.getElementById('records_' + shipperId);
