function clearAllFiltersClearance() {
    document.querySelectorAll('.col-filter-clearance').forEach(function(f) { f.value = ''; f.classList.remove('active-filter'); });
    columnFiltersClearance = {}; document.getElementById('searchInfoBarClearance').style.display = 'none'; document.getElementById('activeFilterCountClearance').textContent = '0';
    document.querySelectorAll('#permissionsTableBodyClearance tr.shipper-group-row').forEach(function(row) { row.style.display = ''; row.innerHTML = row.innerHTML.replace(/<span class="search-highlight">(.*?)<\/span>/g, '$1'); var dr = document.getElementById('records_' + row.dataset.shipperId); if (dr && !dr.classList.contains('show')) dr.style.display = 'none'; });
    var totalShippers = document.querySelectorAll('#permissionsTableBodyClearance tr.shipper-group-row').length;
