function deselectAllClearance() { document.querySelectorAll('.clearance-checkbox').forEach(function(cb) { cb.checked = false; }); document.querySelectorAll('.shipper-checkbox').forEach(function(cb) { cb.checked = false; cb.indeterminate = false; }); updateSelectedCountClearance(); updateSelectAllCheckboxClearance(); }
