async function bulkGrantClearancePermissions() { var ids = Array.from(document.querySelectorAll('.clearance-checkbox:checked')).map(cb => cb.value); if(ids.length===0){alert('Please select at least one record!');return;} if(!confirm('Grant permissions for '+ids.length+' selected record(s)?'))return; await processBatchClearance('grant', ids); }
