<script>
(function() { const sidebar = document.querySelector('.sidebar'); const body = document.body; const toggleBtn = document.getElementById('sidebarToggleBtn'); if (!sidebar || !toggleBtn) return; function toggleSidebar() { sidebar.classList.toggle('collapsed'); if (sidebar.classList.contains('collapsed')) { body.classList.add('sidebar-collapsed'); document.cookie = "sidebar_collapsed=true; path=/"; } else { body.classList.remove('sidebar-collapsed'); document.cookie = "sidebar_collapsed=false; path=/"; } } toggleBtn.addEventListener('click', toggleSidebar); if (document.cookie.indexOf('sidebar_collapsed=true') !== -1) { sidebar.classList.add('collapsed'); body.classList.add('sidebar-collapsed'); } else { sidebar.classList.remove('collapsed'); body.classList.remove('sidebar-collapsed'); } })();
function toggleSidebarMobile() { const sidebar = document.querySelector('.sidebar'); if(sidebar) sidebar.classList.toggle('open'); }
document.addEventListener('keydown', function(e) { if(e.ctrlKey && e.key === 's') { e.preventDefault(); let btn = document.querySelector('#jobForm .btn-primary[type="submit"], #billForm .btn-primary[type="submit"], #revisedBillForm .btn-primary[type="submit"], #clearanceForm .btn-primary[type="submit"], #loadingForm .btn-primary[type="submit"]'); if(btn) btn.click(); } if(e.ctrlKey && e.key === 'p') { e.preventDefault(); window.print(); } if(e.ctrlKey && e.key === 'n') { e.preventDefault(); window.location.href = 'system.php?page=create-job'; } if(e.ctrlKey && e.key === 'b') { e.preventDefault(); window.location.href = 'system.php?page=bills'; } if(e.ctrlKey && e.key === 'j') { e.preventDefault(); window.location.href = 'system.php?page=jobs'; } if(e.ctrlKey && e.key === 'd') { e.preventDefault(); window.location.href = 'system.php?page=dashboard'; } if(e.key === 'Backspace' && !e.target.matches('input, textarea, select')) { e.preventDefault(); window.history.back(); } });

// ============================================================
// SIDEBAR KEYBOARD NAVIGATION (Alt+S to focus, arrows to move)
// ============================================================
(function() {
    let sidebarActive = false;
    let sidebarItems = [];
    let currentIndex = -1;

    function getSidebarItems() {
        return Array.from(document.querySelectorAll('.sidebar-nav .nav-item'));
    }

    function clearSidebarHighlight() {
        sidebarItems.forEach(item => item.classList.remove('sidebar-keyboard-active'));
    }

    function highlightSidebarItem(index) {
        clearSidebarHighlight();
        if (sidebarItems[index]) {
            sidebarItems[index].classList.add('sidebar-keyboard-active');
            sidebarItems[index].scrollIntoView({ block: 'nearest', behavior: 'smooth' });
        }
    }

    function activateSidebar() {
        sidebarItems = getSidebarItems();
        if (sidebarItems.length === 0) return;
        
        // Scroll sidebar into view (if needed)
        const sidebar = document.querySelector('.sidebar');
        if (sidebar) sidebar.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        
        // Start with first item
        currentIndex = 0;
        highlightSidebarItem(currentIndex);
        sidebarActive = true;
        
        // Show a small hint (optional)
        let hint = document.querySelector('#sidebar-nav-hint');
        if (!hint) {
            hint = document.createElement('div');
            hint.id = 'sidebar-nav-hint';
            hint.style.cssText = 'position:fixed; bottom:10px; left:10px; background:#333; color:#ff0; padding:4px 10px; border-radius:20px; font-size:11px; z-index:9999;';
            hint.textContent = 'Sidebar navigation active: ↑↓ to move, Enter to select, Esc to exit';
            document.body.appendChild(hint);
        }
        hint.style.display = 'block';
        setTimeout(() => { if (hint) hint.style.opacity = '0.6'; }, 3000);
    }

    function deactivateSidebar() {
        sidebarActive = false;
        clearSidebarHighlight();
        currentIndex = -1;
        const hint = document.querySelector('#sidebar-nav-hint');
        if (hint) hint.style.display = 'none';
    }

    function moveSidebar(delta) {
        if (!sidebarActive) return false;
        if (sidebarItems.length === 0) {
            deactivateSidebar();
            return false;
        }
        let newIndex = currentIndex + delta;
        if (newIndex < 0) newIndex = 0;
        if (newIndex >= sidebarItems.length) newIndex = sidebarItems.length - 1;
        if (newIndex !== currentIndex) {
            currentIndex = newIndex;
            highlightSidebarItem(currentIndex);
        }
        return true;
    }

    function clickCurrentItem() {
        if (sidebarActive && currentIndex >= 0 && sidebarItems[currentIndex]) {
            const link = sidebarItems[currentIndex];
            // Trigger navigation
            if (link.tagName === 'A') {
                link.click();
            }
            deactivateSidebar();
        }
    }

    // Keyboard event listener (with priority for sidebar when active)
    document.addEventListener('keydown', function(e) {
        // Shortcut: Alt+S (or Ctrl+Shift+S) - you can change key here
        if ((e.altKey && e.key === 's') || (e.ctrlKey && e.shiftKey && e.key === 'S')) {
            e.preventDefault();
            activateSidebar();
            return;
        }
        
        // If sidebar is active, handle arrows and Enter/Esc
        if (sidebarActive) {
            if (e.key === 'ArrowUp') {
                e.preventDefault();
                moveSidebar(-1);
            } else if (e.key === 'ArrowDown') {
                e.preventDefault();
                moveSidebar(1);
            } else if (e.key === 'Enter') {
                e.preventDefault();
                clickCurrentItem();
            } else if (e.key === 'Escape' || e.key === 'Tab') {
                deactivateSidebar();
            }
        }
    });

    // When user clicks on any sidebar item manually, reset tracking
    document.addEventListener('click', function(e) {
        const item = e.target.closest('.sidebar-nav .nav-item');
        if (item) {
            deactivateSidebar();
        }
    });

    // Rescan sidebar items when DOM changes (e.g., after page load)
    const observer = new MutationObserver(() => {
        if (sidebarActive) {
            sidebarItems = getSidebarItems();
            if (currentIndex >= sidebarItems.length) currentIndex = sidebarItems.length - 1;
            if (currentIndex >= 0) highlightSidebarItem(currentIndex);
        }
    });
    observer.observe(document.body, { childList: true, subtree: true });
})();

// Style for highlighted sidebar item
if (!document.querySelector('#sidebar-nav-style')) {
    const style = document.createElement('style');
    style.id = 'sidebar-nav-style';
    style.textContent = `
        .sidebar-nav .nav-item.sidebar-keyboard-active {
            background: rgba(255,255,255,0.3);
            border-left: 3px solid #ffc107;
            box-shadow: inset 0 0 0 1px rgba(255,255,255,0.2);
        }
    `;
    document.head.appendChild(style);
}

// ============================================================
// FORM NAVIGATION: Arrow keys (↑↓) to move between fields
// + Shortcuts: Ctrl+Shift+F (first field), Ctrl+Shift+L (last field)
// ============================================================
(function() {
    // Get all focusable form elements (input, select, textarea, button)
    function getFormFields(form) {
        if (!form) return [];
        const focusable = Array.from(form.querySelectorAll('input:not([type="hidden"]), select, textarea, button'));
        // Filter visible and not disabled
        return focusable.filter(field => field.offsetParent !== null && !field.disabled);
    }

    let currentForm = null;
    let formFields = [];
    let currentFieldIndex = -1;

    function findCurrentForm() {
        // Look for the most visible form on page
        const forms = document.querySelectorAll('form');
        for (let form of forms) {
            if (form.offsetParent !== null) {
                return form;
            }
        }
        return null;
    }

    function updateFormFields() {
        const newForm = findCurrentForm();
        if (newForm !== currentForm) {
            currentForm = newForm;
            if (currentForm) {
                formFields = getFormFields(currentForm);
                currentFieldIndex = formFields.indexOf(document.activeElement);
            } else {
                formFields = [];
                currentFieldIndex = -1;
            }
        } else if (currentForm) {
            // Re-scan fields in case DOM changed
            formFields = getFormFields(currentForm);
            currentFieldIndex = formFields.indexOf(document.activeElement);
        }
    }

    function moveToNextField(delta) {
        updateFormFields();
        if (formFields.length === 0) return false;
        
        let newIndex = currentFieldIndex + delta;
        if (newIndex < 0) newIndex = 0;
        if (newIndex >= formFields.length) newIndex = formFields.length - 1;
        
        if (newIndex !== currentFieldIndex) {
            formFields[newIndex].focus();
            return true;
        }
        return false;
    }

    function focusFirstField() {
        updateFormFields();
        if (formFields.length > 0) {
            formFields[0].focus();
        }
    }

    function focusLastField() {
        updateFormFields();
        if (formFields.length > 0) {
            formFields[formFields.length - 1].focus();
        }
    }

    function submitFormWithEnter(e) {
        // Allow Ctrl+Enter to submit
        if (e.ctrlKey && e.key === 'Enter') {
            e.preventDefault();
            if (currentForm) {
                const submitBtn = currentForm.querySelector('button[type="submit"], input[type="submit"]');
                if (submitBtn) submitBtn.click();
                else currentForm.submit();
            }
        }
    }

    // Keyboard handler
    document.addEventListener('keydown', function(e) {
        const active = document.activeElement;
        const isInputLike = active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' || active.tagName === 'SELECT');
        
        // For arrow up/down: only navigate if cursor is at beginning/end? Actually simpler: 
        // If no text selection and caret position is at extreme? But to keep simple:
        // We'll allow navigation only when the active field is not a textarea? Or always allow but conflict with cursor movement?
        // Better: Use Alt+Arrow to force navigation, or just use Tab? User specifically asked for arrow keys.
        // Let's implement: If field is input/textarea and there is selected text, arrow keys work normally.
        // Otherwise, if no selection, arrow keys move to next/prev field.
        if (isInputLike && (e.key === 'ArrowUp' || e.key === 'ArrowDown')) {
            const hasSelection = active.selectionStart !== active.selectionEnd;
            if (!hasSelection) {
                e.preventDefault();
                moveToNextField(e.key === 'ArrowDown' ? 1 : -1);
                return;
            }
        }
        
        // Shortcuts
        if (e.ctrlKey && e.shiftKey && e.key === 'F') {
            e.preventDefault();
            focusFirstField();
        }
        if (e.ctrlKey && e.shiftKey && e.key === 'L') {
            e.preventDefault();
            focusLastField();
        }
        
        // Ctrl+Enter submit
        if (e.ctrlKey && e.key === 'Enter') {
            submitFormWithEnter(e);
        }
    });
    
    // When focusing a field, update current index
    document.addEventListener('focusin', function() {
        updateFormFields();
    });
    
    // Initial scan
    setTimeout(updateFormFields, 100);
})();


// ============================================================
// CTRL+S GLOBAL SAVE - Works on ANY form (Create Job, Bill, Edit, etc.)
// ============================================================
(function() {
    function findActiveForm() {
        // Priority 1: Form that has a submit button visible
        const forms = document.querySelectorAll('form');
        for (let form of forms) {
            if (form.offsetParent !== null) { // visible form
                // Check if it has a submit button or save button
                const submitBtn = form.querySelector('button[type="submit"], input[type="submit"], .btn-primary[type="submit"]');
                if (submitBtn && submitBtn.offsetParent !== null) {
                    return form;
                }
            }
        }
        // Fallback: any visible form
        for (let form of forms) {
            if (form.offsetParent !== null) return form;
        }
        return null;
    }

    function submitForm(form) {
        if (!form) return false;
        
        // Try to find submit button and click it (preserves validation)
        const submitBtn = form.querySelector('button[type="submit"], input[type="submit"], .btn-primary, .btn-success');
        if (submitBtn && submitBtn.click) {
            submitBtn.click();
            return true;
        }
        // Last resort: native submit
        if (form.submit) {
            form.submit();
            return true;
        }
        return false;
    }

    document.addEventListener('keydown', function(e) {
        if (e.ctrlKey && e.key === 's') {
            e.preventDefault();
            const form = findActiveForm();
            if (form) {
                submitForm(form);
                // Visual feedback
                const btn = form.querySelector('button[type="submit"], .btn-primary');
                if (btn) {
                    const originalText = btn.innerHTML;
                    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';
                    setTimeout(() => { btn.innerHTML = originalText; }, 2000);
                }
            } else {
                console.warn('No visible form found to save');
                // Optional: alert or visual feedback
                const msg = document.createElement('div');
                msg.textContent = 'No form found to save!';
                msg.style.cssText = 'position:fixed; bottom:20px; right:20px; background:#f44336; color:white; padding:8px 16px; border-radius:8px; z-index:9999;';
                document.body.appendChild(msg);
                setTimeout(() => msg.remove(), 2000);
            }
        }
    });
})();

// ============================================================
// AUTO-REFRESH (Real-time sync across laptops)
// ============================================================
(function() {
    let refreshInterval = null;
    let refreshEnabled = false;
    let lastDataHash = '';
    
    // Detect current page from URL
    function getCurrentPage() {
        const urlParams = new URLSearchParams(window.location.search);
        const page = urlParams.get('page');
        return page;
    }
    
    // Generate a simple hash of table data to detect changes
    function getTableHash() {
        let tables = document.querySelectorAll('.jobs-google-sheets-table tbody, #billsTable tbody, .clearance-google-table tbody, #clearanceTable tbody, .loading-table tbody');
        if (tables.length === 0) return '';
        let text = '';
        for (let tbody of tables) {
            text += tbody.innerText;
        }
        let hash = 0;
        for (let i = 0; i < text.length; i++) {
            hash = ((hash << 5) - hash) + text.charCodeAt(i);
            hash |= 0;
        }
        return hash.toString();
    }
    
    // Refresh data based on current page
    function refreshPageData() {
        const page = getCurrentPage();
        if (!page) return;
        
        // Get current filters (if any)
        const startDate = document.getElementById('job_start_date')?.value || '';
        const endDate = document.getElementById('job_end_date')?.value || '';
        const search = document.getElementById('globalSearchInput')?.value || '';
        
        let url = '';
        if (page === 'jobs') {
            url = `system.php?page=search-jobs&page_num=1&search=${encodeURIComponent(search)}&start_date=${startDate}&end_date=${endDate}`;
            fetch(url)
                .then(res => res.json())
                .then(data => {
                    if (data.success && data.jobs) {
                        const newHash = getTableHash();
                        const oldHash = lastDataHash;
                        if (newHash !== oldHash) {
                            // Data changed – refresh jobs table
                            const tbody = document.getElementById('jobsTableBody');
                            if (tbody) {
                                let html = '';
                                data.jobs.forEach(job => {
                                    html += createJobRow(job, '').outerHTML;
                                });
                                tbody.innerHTML = html;
                                document.getElementById('totalJobsCount').innerText = data.total_records;
                                document.getElementById('showingCount').innerText = data.jobs.length;
                                document.getElementById('totalRecordsCount').innerText = data.total_records;
                                lastDataHash = getTableHash();
                                showNotification('Data updated automatically');
                            }
                        }
                    }
                })
                .catch(err => console.warn('Auto-refresh error:', err));
        }
        else if (page === 'bills') {
            url = `system.php?page=bills&start_date=${startDate}&end_date=${endDate}&ajax=1`;
            // Note: you need to modify bills page to return JSON when ?ajax=1 is passed
            // For now, we'll just reload the page? Better to implement JSON endpoint
            // Simpler: reload page if needed, but user wants no reload. I'll skip bills for now but can be extended.
            console.log('Bills auto-refresh not fully implemented yet – but you can extend similarly');
        }
        else if (page === 'karachi-clearance') {
            // Similar implementation – use existing getKarachiClearance endpoint
            const start = document.getElementById('clearance_start_date')?.value || '';
            const end = document.getElementById('clearance_end_date')?.value || '';
            const search = document.getElementById('clearanceSearch')?.value || '';
            fetch(`system.php?page=karachi-clearance&ajax=1&search=${encodeURIComponent(search)}&start_date=${start}&end_date=${end}`)
                .then(res => res.json())
                .then(data => {
                    if (data.success) {
                        const newHash = getTableHash();
                        if (newHash !== lastDataHash) {
                            // Update clearance table
                            const tbody = document.querySelector('#clearanceTable tbody');
                            if (tbody && data.records) {
                                let html = '';
                                data.records.forEach(rec => {
                                    html += `<tr ondblclick="viewClearance(${rec.id})">
                                        <td><strong>${escapeHtml(rec.karachi_clearance_number)}</strong></td>
                                        <td>${rec.date ? formatDateStr(rec.date) : '-'}</td>
                                        <td>${escapeHtml(rec.shipper || '-')}</td>
                                        <td>${escapeHtml(rec.on_account || '-')}</td>
                                        <td>${escapeHtml(rec.clearing_agent || '-')}</td>
                                        <td>${escapeHtml(rec.importer_name || '-')}</td>
                                        <td>${escapeHtml(rec.bl_no || '-')}</td>
                                        <td>${escapeHtml(rec.container_no || '-')}</td>
                                        <td>${escapeHtml((rec.description || '-').substring(0,40))}</td>
                                        <td>${escapeHtml(rec.vessel_name || '-')}</td>
                                        <td>${rec.eta ? formatDateStr(rec.eta) : '-'}</td>
                                        <td><span class="status-badge ${rec.soc=='Yes'?'active':'cancelled'}">${rec.soc||'No'}</span></td>
                                        <td><span class="status-badge ${rec.status||'active'}">${rec.status||'active'}</span></td>
                                        <td class="action-cell">...</td>
                                    </tr>`;
                                });
                                tbody.innerHTML = html;
                                lastDataHash = newHash;
                                showNotification('Clearance records updated');
                            }
                        }
                    }
                });
        }
        else if (page === 'loading-files') {
            // Similar – but loading files uses grouping, a bit complex; we can just toggle the page reload for simplicity.
            console.log('Loading files auto-refresh can be added similarly');
        }
    }
    
    function showNotification(msg) {
        let notify = document.querySelector('#auto-refresh-notify');
        if (!notify) {
            notify = document.createElement('div');
            notify.id = 'auto-refresh-notify';
            notify.style.cssText = 'position:fixed; bottom:20px; right:20px; background:#4caf50; color:white; padding:6px 12px; border-radius:20px; font-size:12px; z-index:9999; opacity:0; transition:opacity 0.3s; pointer-events:none;';
            document.body.appendChild(notify);
        }
        notify.textContent = msg;
        notify.style.opacity = '1';
        setTimeout(() => { notify.style.opacity = '0'; }, 2000);
    }
    
    function startAutoRefresh(seconds = 5) {
        if (refreshInterval) clearInterval(refreshInterval);
        refreshInterval = setInterval(() => {
            if (refreshEnabled) {
                refreshPageData();
            }
        }, seconds * 1000);
        refreshEnabled = true;
        showNotification(`Auto-refresh started (every ${seconds}s)`);
    }
    
    function stopAutoRefresh() {
        if (refreshInterval) {
            clearInterval(refreshInterval);
            refreshInterval = null;
        }
        refreshEnabled = false;
        showNotification('Auto-refresh stopped');
    }
    
    // Add a floating button to toggle auto-refresh
    // function addToggleButton() {
    //     let btn = document.querySelector('#auto-refresh-toggle');
    //     if (btn) return;
    //     btn = document.createElement('button');
    //     btn.id = 'auto-refresh-toggle';
    //     btn.innerHTML = '<i class="fas fa-sync-alt"></i> Auto Refresh OFF';
    //     btn.style.cssText = 'position:fixed; bottom:20px; left:20px; background:#18224b; color:white; border:none; padding:8px 14px; border-radius:30px; cursor:pointer; font-size:12px; z-index:9999; box-shadow:0 2px 5px rgba(0,0,0,0.2);';
    //     let isOn = false;
    //     btn.onclick = () => {
    //         isOn = !isOn;
    //         if (isOn) {
    //             startAutoRefresh(5);
    //             btn.innerHTML = '<i class="fas fa-sync-alt fa-spin"></i> Auto Refresh ON';
    //             btn.style.background = '#4caf50';
    //         } else {
    //             stopAutoRefresh();
    //             btn.innerHTML = '<i class="fas fa-sync-alt"></i> Auto Refresh OFF';
    //             btn.style.background = '#18224b';
    //         }
    //     };
    //     document.body.appendChild(btn);
    // }
    
    // Initialize when page loads
    // if (document.readyState === 'loading') {
    //     document.addEventListener('DOMContentLoaded', addToggleButton);
    // } else {
    //     addToggleButton();
    // }
})();

function togglePassword() {
    var pass = document.getElementById("password");

    if (pass.type === "password") {
        pass.type = "text";
    } else {
        pass.type = "password";
    }
}

